pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space mod capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Penalize residual in "wasted" harmonic classes: (0,10] is nearly unusable
    if post_residual <= 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        score += 25.0;
    } else if post_residual <= 30 {
        score += 8.0;
    }

    // Reward residual that is a good harmonic multiple (divisible classes)
    let class = post_residual / 10;
    if class % 3 == 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Tight fit reward: item fills most of the bin
    let tight = item_size as f64 / bin_residual as f64;
    if tight > 0.9 {
        score -= 40.0;
    } else if tight > 0.7 {
        score -= 15.0;
    }

    // Lookahead coupling: can next item fit in post_residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 0.2 * (next_item_size as f64);
        } else {
            score += 12.0;
            // If next item also can't fit anywhere else, waste matters more
            if next_item_size > bin_capacity / 2 && post_residual < 20 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bins attractive only when open
    // bins are crowded (high mean residual) or this is a poor fit
    if bin_residual == bin_capacity {
        let crowded = mean_residual / cap;
        // Opening a new bin is good when existing residuals are small (crowded)
        score = 0.5 * cap - 80.0 * (1.0 - crowded) - 0.3 * open_bins_count as f64;
        if post_residual == cap {
            // empty bin: prefer it when mean residual low and many bins open
            if mean_residual < 0.35 * cap {
                score -= 20.0 + 0.5 * open_bins_count as f64;
            }
        }
        // If item is large, fresh bin is fine
        if item_size > bin_capacity / 2 {
            score -= 25.0;
        }
    }

    // Stream progression: late in stream, consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (min size 1..~10) can
    // ever use are pure waste. Penalize tiny unusable gaps heavily.
    if post_residual > 0 {
        // gap smaller than the smallest plausible item is dead space
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual <= 15 {
            score += 25.0;
        }
        // diminishing penalty curve for larger gaps: waste grows superlinearly
        // as the gap approaches sizes that still can't host mid-size items
        let gap_frac = post_residual as f64 / bin_capacity as f64;
        score += 20.0 * gap_frac * gap_frac;
    } else {
        // perfect fit: strong reward
        score -= 80.0;
    }

    // Reward tight fits: fraction of residual consumed by this item.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit would be terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Opening a new bin is attractive only when open-bin pressure is low or
    // the item is large and would leave a big awkward gap elsewhere.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, modulated by how many bins are open
        score += 40.0;
        score -= 5.0 * open_bins_count as f64;
        // large items fit perfectly in fresh bins: reward proportionally
        score -= 0.5 * item_size as f64;
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    } else {
        // open-bin pressure: reward using existing bins when many are open
        score -= 2.0 * open_bins_count as f64;
        // prefer bins whose residual is near the mean (balanced depletion),
        // so we empty bins fully rather than spreading waste
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this placement (pairing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            // next item would leave dead space: mild penalty
            score += 10.0;
        } else if post_residual >= next_item_size {
            // next item can still fit: good chaining
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: exact fill is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item fits the post residual
    // (chaining placements), penalize dead space that nothing can use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item chains into this bin: reward proportionally to how snugly.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 60.0 - chain_waste.min(60.0);
        } else {
            // Dead space below next item size: penalize harder for small leftovers.
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
        // Bonus if the chain leaves an exact fill after the next item.
        if post_residual == next_item_size {
            score -= 250.0;
        }
    } else {
        // Last item: only current fit matters.
        score -= 30.0;
    }

    // Relative to mean residual: prefer bins that are tighter than average
    // (best-fit style), penalize using the emptiest bins for small items.
    score += (mean_residual - bin_residual as f64) * 0.6;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: make it attractive only when the item is large
    // relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score -= 20.0 + 40.0 * tightness;
        if next_item_size > 0 && post_residual < next_item_size {
            // Fresh bin can't chain the next item well; discourage.
            score += 25.0;
        }
    }

    // Mild preference to consolidate bins as the stream progresses.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of common small item sizes) are rewarded.
    let post = post_residual;
    let cap = bin_capacity as f64;

    // Class A: post_residual divisible by 10/20/25 -> clean future fits
    if post > 0 {
        if post % 10 == 0 {
            score -= 6.0;
        }
        if post % 25 == 0 {
            score -= 4.0;
        }
        if post % 5 == 0 {
            score -= 2.0;
        }
        // Integer-division thresholds: leftover in [1,9] is near-dead space
        let dead_zone = post / 10; // 0 => tiny leftover
        if dead_zone == 0 {
            score += 10.0; // penalize unusable slivers
        } else if dead_zone == 1 {
            score += 3.0;
        }
        // Sweet spots: leftover 30-50 accommodates the mid item range
        if post >= 30 && post <= 50 {
            score -= 5.0;
        }
        // Perfect fit reward
        if post == 0 {
            score -= 20.0;
        }
    } else {
        score -= 20.0;
    }

    // Lookahead coupling: harmonic match between post_residual and next item
    if next_item_size > 0 && next_item_size <= post {
        let gap = post - next_item_size;
        // Reward if next item leaves a further clean residue
        if gap == 0 {
            score -= 12.0;
        } else if gap % 10 == 0 {
            score -= 7.0;
        } else if gap <= 5 {
            score += 4.0; // creates sliver after next item
        }
    } else if next_item_size > post {
        // next item won't fit here; leftover class matters more
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: make empty bin moderately attractive only
    // when current bins are congested (mean residual low relative to item)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let congestion = (item_size as f64) / (mean_residual.max(1.0));
        // Base new-bin score: slightly worse than a good fit, better than a bad one
        score = cap * 0.5 - 8.0 * congestion + 4.0 * progress;
        if fitting_bins_count == 0 {
            score -= 30.0; // must open a new bin
        }
    } else {
        // Mild penalty for spreading across many open bins
        score += (open_bins_count as f64) * 0.15;
        // Prefer bins tighter than the mean (better packing density)
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: if next item exactly fills post_residual, huge reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 - slack * 0.8;
        } else {
            // next item cannot use this residual: penalize dead space
            score += 60.0;
        }
    }

    // Compare post_residual against mean residual: prefer leaving residuals near mean
    let diff = post_residual as f64 - mean_residual;
    score += (diff * diff).sqrt() * 0.3;

    // Last-chance bin bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize opening new bins when a decent fit exists in an open bin
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 120.0;
        // New bin more attractive late in stream if many open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        if post_residual as f64 > 0.7 * bin_capacity as f64 && open_bins_count > 3 {
            score -= 40.0 + 50.0 * progress;
        }
    }

    // Prefer tighter fits generally
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    score
}

