pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are unusable.
    if post_residual > 0 {
        let min_useful = 10u32; // smallest item that could ever arrive
        if post_residual < min_useful {
            // post_residual > 0 but < 10 is impossible given item >= 1; guard anyway
            score += 1000.0;
        } else if post_residual < 20 {
            // tiny gap: nearly dead space, heavy penalty
            score += 60.0 + (20 - post_residual) as f64 * 8.0;
        } else if post_residual < 35 {
            // awkward zone: only fits very small items
            score += 18.0 + (35 - post_residual) as f64 * 2.0;
        } else if post_residual < 55 {
            score += 6.0;
        }
        // exact fit: perfect placement, strong reward
        if post_residual == 0 {
            score -= 120.0;
        }
    }

    // Reward keeping residual large enough to host likely future items.
    let fit_future = (next_item_size as f64) <= post_residual as f64 && next_item_size > 0;
    if fit_future {
        score -= 25.0;
        // extra reward if the next item fits snugly (small slack after it)
        let next_slack = post_residual as f64 - next_item_size as f64;
        if next_slack < 15.0 {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // residual can't host the lookahead item: mild dead-space penalty
        score += 10.0 + (next_item_size as f64 - post_residual as f64) * 0.3;
    }

    // Open-bin pressure: prefer compacting into existing bins when many are open,
    // but allow opening a new bin when few bins are open (early stream).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * 12.0 * (0.5 + progress);
    score += pressure;

    // Last-chance bin: strongly favor using it to avoid opening a bin needlessly.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity or the current bin leaves a bad gap.
    if bin_residual == bin_capacity {
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        // A fresh bin is attractive only if it leaves a big, flexible residual
        // while existing alternatives would leave small dead gaps.
        score = 40.0 + waste_ratio * 20.0 + (open_bins_count as f64) * 3.0;
        if fit_future {
            score -= 30.0;
        }
        // late in the stream, prefer closing out existing bins
        score += progress * 15.0;
    }

    // Slight preference for bins tighter than average (good fits).
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post-residual, with a smooth non-linear penalty
    // that grows super-linearly for moderately large dead space.
    let mut score = post;
    score += 18.0 * norm_post * norm_post * (1.0 + 2.0 * progress);

    // Smooth interaction: how well the leftover matches the next item.
    // Reward when next_item_size fits into post_residual (chainability),
    // penalize when post_residual is just slightly too small (worst dead space).
    let next = next_item_size as f64;
    if next > 0.0 {
        let diff = (post - next) / cap;
        // smooth bump: positive when diff near 0 (perfect chaining)
        let bump = (-24.0 * diff * diff).exp();
        score -= 14.0 * bump * (0.5 + progress);
        // penalize near-miss: post slightly below next
        let miss = (diff + 0.06) * (diff + 0.06);
        if diff < 0.0 {
            score += 10.0 * miss * cap * (1.0 - progress);
        }
    }

    // Mean-residual coupling: placing into a bin far above the mean
    // residual preserves small residuals; smooth quadratic term.
    let dev = (post - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin, scaled smoothly by stream progress.
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.4 + 0.6 * progress);
    }

    // New-bin candidate (empty bin): penalize smoothly, more early in stream
    // when consolidation matters, less late when many bins are already open.
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64 / (1.0 + open_bins_count as f64);
        score += 30.0 * (1.0 - 0.5 * progress) * (1.0 - 0.3 * openness);
    }

    // Tight-fit reward: smooth function of fill ratio after placement.
    let fill = 1.0 - norm_post;
    score -= 10.0 * fill * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) more strongly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that no future item can plausibly use.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0; // unusable sliver
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            // bonus if next item fits snugly too
            let r = next_item_size as f64 / post_residual as f64;
            score -= 8.0 * r * r;
        } else {
            score += 4.0; // chain broken
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Crowding pressure: many open bins -> prefer consolidating into tight fits.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.05 * pressure * (post_residual as f64);

    // Time horizon: early in stream, keep bins flexible (avoid tiny residuals);
    // late in stream, prioritize filling bins aggressively.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - t) * 0.15 * post_residual as f64;
    score -= t * 0.10 * fit_ratio * 10.0;

    // New-bin candidate: only attractive when current bin would leave a bad
    // residual or when the fit is poor; an empty bin has full flexibility.
    if bin_residual == bin_capacity {
        let poor_fit_penalty = (bin_capacity as f64 - item_size as f64) * 0.10;
        let urgency = if fitting_bins_count <= 1 { 8.0 } else { 0.0 };
        score = 30.0 + poor_fit_penalty + urgency - t * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" the leftover space is.
    // Class 0: post_residual == 0 (perfect fit, huge reward)
    // Class 1: post_residual <= 5 (near-perfect)
    // Class 2: post_residual divisible by small harmonics (10, 20, 25, 50) -> likely reusable
    // Class 3: awkward leftover (1..9 gap, non-harmonic) -> penalize
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else {
        let harmonic = (post_residual % 10 == 0) || (post_residual % 25 == 0) || (post_residual % 50 == 0);
        if harmonic {
            score -= 10.0;
        } else {
            score += 8.0 + (post_residual % 10) as f64;
        }
    }

