            score += 5.0 + 15.0 * (miss / bin_capacity as f64);
            // If next item would have fit pre-placement but not post-placement,
            // we destroyed a chain opportunity.
            if bin_residual >= next_item_size {
                score += 25.0;
            }
        }
    } else {
        // Last item: just minimize post_residual strongly.
        score -= 10.0;
    }

    // --- Last-chance logic: only one bin fits the item, use it rather than open a new one ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // --- New-bin candidate handling (bin_residual == bin_capacity) ---
    if bin_residual == bin_capacity {
        // Opening a new bin is fine early in the stream or when many bins already open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Penalize new bins slightly when item is small (wasteful), reward for large items.
        score += 30.0 - 0.4 * item_size as f64;
        // Late in stream, prefer filling existing bins.
        score += 20.0 * progress;
        // If many open bins with large mean residual, avoid opening another.
        if mean_residual > item_size as f64 {
            score += 15.0;
        }
        // But if no open bin fits well, new bin should be attractive: subtract baseline.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

