    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        // Tighter than average bin: good candidate to consolidate.
        score -= 8.0 * (mean_residual - residual_f) / bin_capacity as f64;
    } else {
        // Looser than average: slight penalty to keep big residual bins for big future items.
        score += 4.0 * (residual_f - mean_residual) / bin_capacity as f64;
    }

