    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Base preference: tight fits (small post-residual) rewarded, amplified by progress.
    let tightness = 1.0 - norm_pr * norm_pr;
    score -= (1.0 + 3.0 * progress) * 20.0 * tightness;

    // Smooth non-linear penalty for dead space that cannot fit a typical next item.
    let dead = if norm_next > 0.0 { norm_next - norm_pr } else { 0.0 };
    let dead_pos = if dead > 0.0 { dead } else { 0.0 };
    score += 15.0 * dead_pos * dead_pos * (1.0 + progress);

    // Lookahead: reward leaving room exactly for the next item (smooth gaussian-like coupling).
    if next_item_size > 0 {
        let gap = (norm_pr - norm_next).abs();
        score -= 12.0 * (-(gap * gap) / 0.02).exp();
    }

    // Last-chance bonus: strongly favor using the only fitting bin, smoothly scaled by progress.
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + progress);
    }

    // Mild penalty when many bins are open and residual is large (fragmentation control).
    let frag = (open_bins_count as f64).ln() / (1.0 + (open_bins_count as f64).ln());
    score += 5.0 * frag * norm_pr * (1.0 - progress);

    // Deviation of this bin's residual from mean residual (smooth quadratic coupling).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // New-bin candidate: penalize opening a new bin, softly, more early in the stream.
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - 0.6 * progress);
        // But allow it when item is large and would leave a useful residual elsewhere anyway.
        score -= 10.0 * norm_item * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: bucket by capacity fractions ---
    // Class 0: post_residual == 0 (perfect fit) -> huge reward
    // Class 1: post_residual in 1..=10 (dead space, nothing fits) -> heavy penalty
    // Class 2: post_residual in 11..=33 (small item zone)
    // Class 3: post_residual in 34..=66 (medium zone)
    // Class 4: post_residual in 67..=99 (large zone, very reusable)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score += 40.0; // dead space penalty
    } else if post_residual <= 33 {
        score -= 5.0;
    } else if post_residual <= 66 {
        score -= 12.0;
    } else {
        score -= 25.0;
    }

    // --- Integer-division harmonic residue: post_residual % 10 ---
    // Residuals that are exact multiples of 10 align with the item grid.
    if post_residual % 10 == 0 {
        score -= 8.0;
    } else {
        score += (post_residual % 10) as f64 * 0.3;
    }

    // --- Lookahead coupling: reward if next item fits the post residual ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
            // exact harmonic match: next item leaves a clean class boundary
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; penalize more if residual is small-ish
            if post_residual < next_item_size && post_residual < 50 {
                score += 10.0;
            }
        }
    }

    // --- Last-chance bin: strongly favor using the only fitting bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is good only if current item leaves a clean,
        // reusable residual class and no existing bin fits well.
        let clean = post_residual % 10 == 0 || post_residual == 0;
        if clean {
            score -= 5.0;
        } else {
            score += 15.0;
        }
        // discourage opening bins when plenty of open bins fit the item
        if fitting_bins_count > 2 {
            score += 25.0;
        }
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // --- Spread / congestion coupling ---
    // Prefer bins whose residual deviates favorably from the mean residual:
    // placing into a below-mean-residual bin tightens fragmentation.
    let dev = bin_residual as f64 - mean_residual;
    score -= dev * 0.15;

    // Mild preference for fewer open bins overall (encourage closing bins).
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are unusable.
    if post_residual > 0 {
        let min_useful = 10u32; // smallest item that could ever arrive
        if post_residual < min_useful {
            // post_residual > 0 but < 10 is impossible given item >= 1; guard anyway
            score += 1000.0;
        } else if post_residual < 20 {
            // tiny gap: nearly dead space, heavy penalty
            score += 60.0 + (20 - post_residual) as f64 * 8.0;
        } else if post_residual < 35 {
            // awkward zone: only fits very small items
            score += 18.0 + (35 - post_residual) as f64 * 2.0;
        } else if post_residual < 55 {
            score += 6.0;
        }
        // exact fit: perfect placement, strong reward
        if post_residual == 0 {
            score -= 120.0;
        }
    }

    // Reward keeping residual large enough to host likely future items.
    let fit_future = (next_item_size as f64) <= post_residual as f64 && next_item_size > 0;
    if fit_future {
        score -= 25.0;
        // extra reward if the next item fits snugly (small slack after it)
        let next_slack = post_residual as f64 - next_item_size as f64;
        if next_slack < 15.0 {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // residual can't host the lookahead item: mild dead-space penalty
        score += 10.0 + (next_item_size as f64 - post_residual as f64) * 0.3;
    }

    // Open-bin pressure: prefer compacting into existing bins when many are open,
    // but allow opening a new bin when few bins are open (early stream).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * 12.0 * (0.5 + progress);
    score += pressure;

    // Last-chance bin: strongly favor using it to avoid opening a bin needlessly.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity or the current bin leaves a bad gap.
    if bin_residual == bin_capacity {
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        // A fresh bin is attractive only if it leaves a big, flexible residual
        // while existing alternatives would leave small dead gaps.
        score = 40.0 + waste_ratio * 20.0 + (open_bins_count as f64) * 3.0;
        if fit_future {
            score -= 30.0;
        }
        // late in the stream, prefer closing out existing bins
        score += progress * 15.0;
    }

    // Slight preference for bins tighter than average (good fits).
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
