pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Reward tight fits: shrink score as post_residual approaches 0 (non-linear).
    score -= 4.0 * (1.0 - post / cap) * (1.0 - post / cap);

    // Last-chance bin: strongly favor using the only bin that fits this item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin when alternatives exist,
    // unless the fit elsewhere would be terrible (large dead space) or the stream is late.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Base penalty for abandoning open bins.
            score += 8.0 + 0.15 * open_bins_count as f64;
            // Excuse: if the item is huge and would leave little waste in a fresh bin
            // while mean residual of open bins is small (poor fits elsewhere), soften.
            let waste_ratio = post / cap;
            if waste_ratio < 0.25 && mean_residual < item {
                score -= 10.0;
            }
            // Excuse: late in the stream, consolidating waste matters less; keep bins tidy.
            let t = step_index as f64 / (total_items.max(1) as f64);
            if t > 0.7 && post < 15.0 {
                score -= 4.0;
            }
        } else {
            // No alternative: new bin is mandatory, make it maximally attractive.
            score -= 12.0;
        }
    }

    // Lookahead: reward bins whose post-residual can still host the next item,
    // extra reward if it hosts it almost exactly (chained tight packing).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 2.5;
            let slack = post - nxt;
            if slack < 8.0 {
                score -= 2.0; // near-perfect chaining
            }
        } else {
            // Post-residual too small for the next item: mild penalty for stranding space.
            score += 1.5 * (1.0 - post / cap);
        }
    }

    // Global-state coupling: when open bins are on average very full (low mean residual),
    // slightly prefer packing into existing bins to close them out.
    score -= 0.02 * (cap - mean_residual);

    // Mild time-horizon bias: later items get marginally more aggressive packing.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 1.5 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: post residual, mildly compressed non-linearly
    let mut score = pr * (1.0 + 0.5 * x * x);

    // Smooth polynomial coupling with stream progress:
    // early on, keep bins flexible (reward larger residual more);
    // later, tighten packing (penalize wasted residual more).
    let t = progress * progress;
    score += x * x * (20.0 + 60.0 * t) * (cap * 0.01);

    // Interaction: post residual vs mean residual — avoid outlier dead space
    let dev = x - (mean_residual / cap);
    score += 15.0 * dev * dev * cap;

    // Last-chance bin bonus (only one fitting bin): reward using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * (1.0 - x);
    }

    // Lookahead: if next item fits exactly into post residual, strong reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_quality = (next_item_size as f64 - pr).abs() / cap;
        score -= 12.0 * (1.0 - fit_quality * fit_quality);
    }

    // Prefer denser bins when many bins are open
    score -= (open_bins_count as f64).ln().max(0.0) * 3.0 * (1.0 - x);

    // New-bin candidate: penalize mildly unless current bin fit is terrible
    if bin_residual == bin_capacity {
        score += 8.0 - 20.0 * (1.0 - x.abs());
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division into bands of 10.
    let band = post_residual / 10;
    // Dead-space penalty grows super-linearly for small residuals (unusable space).
    if post_residual > 0 {
        let frac = post_residual as f64 / cap;
        if frac < 0.10 {
            score += 18.0 * (1.0 - frac / 0.10);
        }
    }

    // Perfect fit: strongly reward zero residual.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic class bonus: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_post = post_residual - next_item_size;
        if next_post == 0 {
            score -= 45.0; // two-item perfect chain
        } else {
            let nb = next_post / 10;
            score -= 12.0 / (1.0 + nb as f64); // reward small chained residual
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item cannot use this residual: penalize proportionally to wasted class.
        score += 6.0 + band as f64 * 0.5;
    }

    // Last-chance bin: using it avoids opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Modulo-class coupling: residual divisible into halves/quarters of capacity is reusable.
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Prefer filling bins below mean residual (consolidate fullness).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Early stream: mild preference for opening bins to keep options; late stream: pack tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 5.0 - 12.0 * progress; // new bins cheaper early
    } else {
        score += 3.0 * progress; // late: favor existing bins slightly
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual below the minimum item size (1) can never be used again;
    // residuals just above small thresholds are nearly dead too.
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    } else if post_residual < 10 {
        // Truly unusable sliver.
        score += 45.0;
    } else if post_residual < 20 {
        // Very hard to fill later.
        score += 18.0;
    } else if post_residual < 35 {
        score += 6.0;
    }

    // Tightness reward: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * tightness;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: opening a new bin is only attractive when open bins
    // are congested or this bin's fit would waste space. Bias the empty bin
    // slightly upward by default so good fits in existing bins win.
    if bin_residual == bin_capacity {
        score += 12.0;
        // If the item fits perfectly in a fresh bin, allow opening when
        // many bins are already open (spreading load).
        if item_size >= 80 {
            score -= 20.0;
        }
        score += 0.05 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // reward this placement (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 22.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score -= 10.0;
        } else if next_item_size > post_residual && post_residual < 10 {
            // Dead residual that next item cannot use: penalize more.
            score += 15.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading.
    score += 0.15 * open_bins_count as f64;

    // Stream progression: late in the stream, be more conservative about
    // wasting residual capacity.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong lookahead reward: exact match of next item into post_residual is ideal.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - 1.5 * slack; // exact match (slack=0) gets the biggest bonus
        if slack < 10.0 {
            score -= 15.0; // near-perfect 2-step packing
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize proportionally to the gap.
        let gap = (next_item_size - post_residual) as f64;
        score += 0.8 * gap.min(60.0);
    }

    // Dead-space penalty: residual too small for any plausible item (min size 1, but
    // practically small leftovers are waste).
    if post_residual < 10 {
        score += 25.0;
    }

    // Compare against mean residual: prefer bins whose post_residual is close to
    // mean_residual (balanced packing) but reward tighter fits overall.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: neutral-ish baseline, slightly above a good fit so that
    // we only open a new bin when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Late in the stream, opening fresh bins is less attractive (waste risk).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Tight fit reward: small post_residual relative to item size means efficient use.
    score -= 0.5 * (item_size as f64 / bin_capacity as f64) * 20.0;

    // Many open bins: prefer consolidation into existing bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

