        } else if slack_after_next < 10 {
            score += 15.0; // chains into dead space
        } else {
            score -= slack_after_next as f64 * 0.3;
        }
    }
    // Next item barely misses this residual: mild penalty for breaking a chain.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 5.0;
    }

    // Last-chance bonus: this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Crowding pressure: many open bins -> prefer filling existing ones tighter.
    score -= (open_bins_count as f64).ln().max(0.0) * 4.0;

    // Mean-residual coupling: when average slack is low, tighten packing;
    // when slack is abundant, opening bins is cheap so be pickier.
    score += (mean_residual - post_residual as f64) * 0.15;

    // Time horizon: early in the stream, be exploratory (favor new bins slightly);
    // late in the stream, squeeze everything into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 12.0;

    // New-bin candidate: only attractive when the item is large relative to a
    // fresh bin and existing residuals are poor fits.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 15.0 - large_item * 25.0;
        if post_residual < 20 {
            score += 10.0; // large item leaves little waste in a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
