    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - norm_pr);
    }

    // Mild penalty when many bins are open and this placement worsens mean residual balance.
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Discard near-empty leftovers (dead space) smoothly.
    score += 15.0 * (-norm_pr * 6.0).exp() * (0.5 + 0.5 * progress);

    // New-bin candidate handling: make empty bin attractive only when fits are poor.
    if bin_residual == bin_capacity {
        score -= 5.0;
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

