    score += post_residual as f64 * 0.5;

    // Harmonic class: post_residual mod 10 — residuals that are multiples of 10
    // are more reusable for common item sizes (items drawn 1..100).
    let post_mod = post_residual % 10;
    score += post_mod as f64 * 1.5;

    // Integer-division thresholds: classify post_residual into capacity fractions.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual < quarter && post_residual > 0 {
        // Dead space: too small for most items (min size 1, but tiny slivers waste bins).
        score += 12.0;
    } else if post_residual < half {
        score += 3.0;
    } else if post_residual >= half && post_residual < bin_capacity {
        score -= 4.0; // roomy bin still useful
    }

    // Perfect fit reward: zero post_residual is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: does the next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Excellent: chain placement keeps bin productive.
            score -= 8.0;
            // Harmonic pairing: next item leaves another multiple-of-10 residual.
            let post2 = post_residual - next_item_size;
            score -= (post2 % 10 == 0) as f64 * 4.0;
            if post2 == 0 {
                score -= 6.0;
            }
        } else {
            // Next item won't fit here; penalize more if this bin's residual
            // is a stranded sliver.
            if post_residual < quarter {
                score += 8.0;
            } else {
                score += 2.0;
            }
        }
    }

    // Last-chance logic: if this is the only fitting bin, using it avoids
    // opening a new bin — reward strongly.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins
    // offer poor fits. Its post_residual == bin_capacity - item_size.
    if bin_residual == bin_capacity {
        // Neutral base; penalize slightly so only genuinely bad open-bin fits
        // (large scores above) lose to it.
        score += 5.0;
        // Early stream: opening bins is cheap and builds structure.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 6.0;
        // If many open bins, prefer reusing them over spawning more.
        score += open_bins_count as f64 * 0.8;
    }

    // Mean-residual coupling: if this bin is far below the mean residual,
    // it is already fragmented; prefer bins closer to mean for balance.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Modulo harmonic bonus: item_size and post_residual sharing class
    // (both divisible by 5) tends to tile well.
    if item_size % 5 == 0 && post_residual % 5 == 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (min size 1..~10) can
    // ever use are pure waste. Penalize tiny unusable gaps heavily.
    if post_residual > 0 {
        // gap smaller than the smallest plausible item is dead space
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual <= 15 {
            score += 25.0;
        }
        // diminishing penalty curve for larger gaps: waste grows superlinearly
        // as the gap approaches sizes that still can't host mid-size items
        let gap_frac = post_residual as f64 / bin_capacity as f64;
        score += 20.0 * gap_frac * gap_frac;
    } else {
        // perfect fit: strong reward
        score -= 80.0;
    }

    // Reward tight fits: fraction of residual consumed by this item.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit would be terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Opening a new bin is attractive only when open-bin pressure is low or
    // the item is large and would leave a big awkward gap elsewhere.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, modulated by how many bins are open
        score += 40.0;
        score -= 5.0 * open_bins_count as f64;
        // large items fit perfectly in fresh bins: reward proportionally
        score -= 0.5 * item_size as f64;
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    } else {
        // open-bin pressure: reward using existing bins when many are open
        score -= 2.0 * open_bins_count as f64;
        // prefer bins whose residual is near the mean (balanced depletion),
        // so we empty bins fully rather than spreading waste
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this placement (pairing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            // next item would leave dead space: mild penalty
            score += 10.0;
        } else if post_residual >= next_item_size {
            // next item can still fit: good chaining
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: if next item exactly fills post_residual, huge reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 - slack * 0.8;
        } else {
            // next item cannot use this residual: penalize dead space
            score += 60.0;
        }
    }

    // Compare post_residual against mean residual: prefer leaving residuals near mean
    let diff = post_residual as f64 - mean_residual;
    score += (diff * diff).sqrt() * 0.3;

    // Last-chance bin bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize opening new bins when a decent fit exists in an open bin
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 120.0;
        // New bin more attractive late in stream if many open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        if post_residual as f64 > 0.7 * bin_capacity as f64 && open_bins_count > 3 {
            score -= 40.0 + 50.0 * progress;
        }
    }

    // Prefer tighter fits generally
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
