pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit = fitting_bins_count as f64;

    // Base: prefer small post-residual (tight fit), non-linearly.
    let x = pr / cap; // normalized post residual in [0,1)
    let mut score = 100.0 * x * x * (3.0 - 2.0 * x); // smoothstep: punishes large leftover

    // Interaction: stream progress amplifies tightness pressure late in stream.
    score += 40.0 * progress * x * x;

    // Lookahead coupling: reward if next item fits the post residual smoothly.
    let fits_next = if nx > 0.0 && pr >= nx { 1.0 - (pr - nx) / cap } else { 0.0 };
    score -= 25.0 * fits_next * (1.0 - progress);

    // Penalize when this bin's residual deviates badly from mean residual (fragmentation).
    let dev = (pr - mean_residual) / cap;
    score += 15.0 * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin (unless post residual would be terrible).
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - x) * x;
    }

    // Mild penalty proportional to number of open bins to encourage consolidation.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: bin_residual == bin_capacity. Its post_residual is large,
    // so the smoothstep base already penalizes it; add a smooth extra term that
    // decays as the stream progresses (early on, opening bins is cheaper).
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) * (1.0 - x);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by modulo classes
    let post = post_residual as i64;
    let cap = bin_capacity as f64;

    // Reward tight fits: post_residual in small harmonic classes
    if post == 0 {
        score -= 200.0; // perfect fit
    } else if post <= 10 {
        score -= 60.0; // near-perfect: dead space is likely unusable anyway
    }

    // Modulo-class logic: residuals divisible by small integers pair well with
    // typical item sizes, so reward "harmonic" residuals, penalize prime-ish ones.
    let h = if post % 10 == 0 {
        0.0
    } else if post % 5 == 0 {
        4.0
    } else if post % 2 == 0 {
        8.0
    } else {
        14.0
    };
    score += h;

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        let nx = next_item_size as i64;
        if nx == post {
            score -= 120.0;
        } else if nx < post {
            // next item fits but leaves another residual; reward smooth chaining
            let chain = post - nx;
            if chain % 10 == 0 {
                score -= 30.0;
            } else {
                score -= (chain as f64).min(20.0);
            }
        } else {
            // next item cannot use this residual: penalize proportional waste
            score += 10.0 + 0.2 * (nx - post) as f64;
        }
    }

    // Fraction of capacity wasted: quadratic penalty on large residuals
    let frac = post as f64 / cap;
    score += 25.0 * frac * frac;

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        // opening a new bin wastes (capacity - item) potentially; penalize mildly
        // but reward when open bins are fragmented (mean residual small)
        score = 40.0 + 0.3 * mean_residual - (item_size as f64) * 0.2;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Progress-aware tightening: later in stream, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (cap - post as f64) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: residuals too small to ever fit a future item are wasted.
    // Min useful item is ~1..100; treat residuals < 10 as pure dead space, and
    // residuals that cannot fit the lookahead item as likely dead space too.
    if post_residual < 10 {
        score += 60.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Gap can't hold the next item: penalize proportionally to how close it is to useless
        score += 12.0 + 0.35 * (post_residual as f64);
    } else {
        // Reward gaps that can still host the lookahead item
        score -= 6.0;
    }

    // Reward tight fits (small post_residual relative to item size)
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading to new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress * 4.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open
        score += 18.0 + 3.0 * pressure;
    } else {
        // Slight bonus for reusing existing bins when open-bin count is high
        score -= 0.6 * pressure.min(10.0);
    }

    // Prefer bins whose residual is close to the mean residual (keeps bin profiles uniform)
    let dev = ((bin_residual as f64) - mean_residual).abs();
    score += 0.15 * dev;

    // Prefer bins that can also fit the next item after this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.5 * (post_residual as f64 - next_item_size as f64).min(20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match with next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match bonus (post_residual == next_item_size).
        if diff == 0.0 {
            score -= 60.0;
        } else {
            // Penalize mismatch, scaled by how tight the residual is.
            score += diff * 0.8;
        }
        // Penalize leaving dead space that cannot fit the next item.
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
        // Reward residual large enough to still fit next item comfortably.
        if post_residual >= next_item_size {
            score -= 10.0;
        }
    } else {
        // Last item: simply minimize waste.
        score += 5.0;
    }

    // Penalize creating tiny unusable residuals (< half of minimum plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor relative to mean).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: make it attractive only when item is large relative to capacity
    // and existing residuals are poor fits. Baseline mild penalty so we prefer reusing bins.
    if bin_residual == bin_capacity {
        score += 15.0;
        // If next item fits exactly in the new bin's post-residual, discourage extra waste.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    // Slight preference for using more of a bin (fill level).
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual means less dead space.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness * (item_size as f64);

    // Penalize very small unusable leftovers (dead space), unless zero.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit bonus
    }

    // Lookahead: if the next item fits into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0 + 0.2 * (next_item_size as f64);
        } else {
            // next item won't fit; penalize wasted large residual gap
            let gap = (post_residual as f64 - 1.0).max(0.0);
            if gap > (next_item_size as f64) * 0.5 {
                score += 0.15 * gap;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer bins with below-mean residual (fill emptier ones less? no: fill fuller bins first)
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.10 * dev;

    // Dynamic time horizon: late in the stream, consolidate harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * tightness;

    // Many open bins -> discourage new bins, favor reusing; new-bin candidate gets penalty scaled by open count.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * (open_bins_count as f64);
    }

    // Mild penalty for leaving residual that equals a "typical" item chunk (keeps flexibility)
    if post_residual >= 10 && post_residual <= 20 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items - 1) as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with non-linear polynomial shaping.
    let mut score = pr * (1.0 + 0.9 * norm_pr * norm_pr);

    // Smooth interaction: as the stream progresses, penalize large residuals more
    // (less time left to fill them), rewarding tight fits late in the stream.
    score += 12.0 * progress * norm_pr * norm_pr * cap;

    // Dead-space penalty: residuals too small for the smallest plausible item
    // (smoothly ramped rather than a hard cutoff).
    let dead = ((18.0 - pr) / 18.0).clamp(0.0, 1.0);
    score += 25.0 * dead * dead;

    // Lookahead coupling: reward if the next item can use the post_residual
    // (smooth quadratic reward on the gap between next item and post residual).
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).abs();
        score -= 8.0 * (-gap / 15.0);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Mild penalty proportional to number of open bins to discourage bin sprawl,
    // scaled down as progress advances (late sprawl is less harmful to undo).
    score += 0.6 * (1.0 - progress) * open_bins_count as f64;

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a fragmented outlier; penalize smoothly.
    let dev = (mean_residual - pr) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate handling: an empty bin should only win when it offers
    // genuinely better future utility; give it a mild base disadvantage that
    // fades as progress grows (early on, spreading items is cheap).
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress) + 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover is a "usable" residue
    // class (divisible by common small sizes) are more attractive.
    let harmonic_bonus = match post_residual {
        0 => 40.0,                                  // perfect fill
        r if r % 10 == 0 => 12.0,                   // aligns with typical sizes
        r if r % 5 == 0 => 6.0,
        r if r % 2 == 0 => 2.0,
        _ => 0.0,
    };
    score -= harmonic_bonus;

    // Dead-space penalty: tiny post_residual that is not zero is nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: reward post_residual that can host the next item exactly
    // or with a clean remainder; penalize near-miss leftovers.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual >= next_item_size {
            let rem = post_residual % next_item_size;
            if rem == 0 {
                score -= 10.0;
            } else if rem < 10 {
                score += 6.0;
            }
        } else {
            // next item cannot fit here; slightly penalize wasting large residuals
            if post_residual > 30 {
                score += 8.0;
            }
        }
    }

    // Integer-division threshold on post_residual fraction of capacity.
    let frac = post_residual as f64 / bin_capacity as f64;
    let band = (frac * 4.0).floor(); // quarters of capacity
    score += match band as u32 {
        0 => -3.0, // nearly full bin: good
        1 => 0.0,
        2 => 2.0,
        _ => 4.0,  // leaving more than 3/4 empty is bad
    };

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer it only when no open bin fits well
    // (large residual waste avoided) or stream is early with few bins.
    if bin_residual == bin_capacity {
        let waste = item_size as f64; // opening a bin "wastes" capacity - item_size
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = mean_residual / bin_capacity as f64;
        // open new bin if mean residual is small (fragmented) or item is huge
        score = 55.0 + waste * 0.4 - pressure * 30.0 - progress * 5.0;
        if item_size >= 80 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 8.0; // fresh bin can pair with next item
        }
    }

    // Mild preference for tighter (smaller residual) bins among equals.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later (unusable gaps) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }

    // Perfect fit is extremely desirable.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits proportionally to how much of the bin was consumed.
    score -= 0.5 * (item_size as f64 / bin_capacity as f64) * 100.0;

    // If this bin is the last chance to avoid opening a new bin, reward using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure from number of open bins: with many open bins, prefer filling
    // existing bins over opening new ones.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 8.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or mean
        // residual across open bins is still large (room to consolidate).
        score += 30.0 + open_pressure + 0.3 * mean_residual;
        // Opening a new bin is acceptable if the next item is large and would
        // leave a bad gap in any existing bin.
        if next_item_size > 0 && next_item_size > post_residual.max(0) && post_residual < next_item_size as u32 {
            score -= 10.0;
        }
    } else {
        // Existing bin gets a mild bonus for keeping bins consolidated.
        score -= open_pressure * 0.5;
        // Lookahead: if the next item fits exactly into the post-residual,
        // strongly favor this placement.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > 0 && next_item_size < post_residual {
            score -= 0.2 * next_item_size as f64;
        }
    }

    // Slight preference to use bins earlier in the stream (stability).
    score += 0.001 * step_index as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space (small residuals are hard to fill).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, use it
    // rather than opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            // next item fits: mildly good, but prefer leaving flexible space
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use the leftover space: penalize proportionally
            score += 0.25 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // New-bin candidate handling: an empty bin is only attractive when the item
    // is large (poor fit elsewhere likely) or open bins are already fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        let fragmented = mean_residual < 0.35 * bin_capacity as f64;
        if large_item || fragmented || open_bins_count == 0 {
            score -= 20.0 + 15.0 * progress;
        } else {
            score += 35.0; // discourage opening new bins when decent fits exist
        }
    }

    // Global state coupling: when mean residual across bins is high, prefer
    // consolidating into bins that reduce variance (i.e., tighter fits).
    let residual_dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * residual_dev;

    // Late in the stream, avoid creating any new residual waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    // Mild penalty for using very full bins early (keep big spaces flexible).
    if fit_ratio > 0.9 && progress < 0.5 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer tight fits, penalize large residuals super-linearly
    let mut score = pr as f64 * (1.0 + 0.8 * x * x);

    // Smooth non-linear coupling with stream progress:
    // early on, tolerate slack (exploit future flexibility); late, punish waste.
    let progress_coupling = (0.5 - 1.6 * progress) * pr * (1.0 - x);
    score += progress_coupling;

    // Penalize residuals that nothing else fits well: couple with mean residual
    let mean_gap = (mean_residual - pr) / cap;
    score += 12.0 * mean_gap * mean_gap * mean_gap;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * (1.0 - x);
    }

    // Lookahead: reward bins whose post-residual can still host the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 {
        // penalize creating residual just below next item size (dead space)
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += 0.35 * gap * (1.0 + progress);
    }

    // New-bin candidate: only attractive when open bins are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (open_bins_count as f64) / (1.0 + mean_residual / cap);
        score = 45.0 + 8.0 * fragmentation - 30.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // big item coming, fresh bin is useful
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues that are "dead space"
    // (too small for the smallest plausible item) get penalized.
    // Items are 1..=100, so treat post_residual < 10 as dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Integer-division harmonic classes: post_residual bucketed by fifths of capacity.
    let fifth = bin_capacity / 5; // 20
    let post_class = post_residual / fifth; // 0..=5
    // Favor placements landing in "harmonic" classes: near-full bins (class 0)
    // and mid classes that still fit common next items.
    match post_class {
        0 => score -= 15.0, // nearly perfect fill
        1 => score -= 8.0,  // tight but reusable
        2 => score -= 4.0,  // moderate
        3 => score += 2.0,  // awkward zone
        4 => score += 6.0,  // mostly empty -> wasteful use of this bin
        _ => {}             // class 5: empty/new bin, keep base score
    }

    // Lookahead coupling: does next_item_size land exactly in the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            // Harmonic penalty on the leftover after the lookahead item:
            if slack < 10 {
                score += 10.0; // chains into dead space
            } else {
                score -= (slack.min(40)) as f64 * 0.15;
            }
        } else {
            score += 6.0; // next item cannot use this bin's remainder
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a fresh bin for a single item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals
    // are all large (i.e., open bins are congested) or item is big.
    if bin_residual == bin_capacity {
        let congestion = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let penalty = 30.0 + 40.0 * congestion + 10.0 * progress;
        // If the item is huge relative to typical residual, opening a new bin
        // can be better: reduce the penalty.
        let size_relief = (item_size as f64 / bin_capacity as f64) * 35.0;
        score += (penalty - size_relief).max(0.0);
    }

    // Mild preference for tighter bins among equals (low residual spread).
    if (bin_residual as f64 - mean_residual).abs() < 5.0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (dead space), while mid-range residuals are neutral.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        // Unusable sliver: dead space penalty proportional to its uselessness.
        score += (10.0 - pr) * 3.0;
    } else if pr == 0.0 {
        // Perfect fit: strongly reward closing the bin.
        score -= 25.0;
    } else if pr >= 10.0 && pr < 20.0 {
        // Only fits the smallest items: moderately penalize.
        score += (20.0 - pr) * 0.8;
    }

    // Reward tight fits generally: relative fill ratio.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * 12.0;

    // Open-bin pressure: discourage spreading across too many bins,
    // but relax pressure near the end of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (1.0 - 0.5 * progress);
    score += pressure * 0.15;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // reward this placement (chained fit).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (n - pr).abs() < 1.0 && pr > 0.0 {
            score -= 20.0;
        } else if n <= pr {
            score -= 4.0;
        } else {
            // Next item cannot use this residual: penalize leaving large leftovers.
            score += (pr / bin_capacity as f64) * 6.0;
        }
    }

    // New-bin candidate: an empty bin should only win when no open bin offers
    // a decent fit. Penalize the empty-bin candidate so it is chosen only when
    // all open bins have poor fits (their dead-space penalties will exceed this).
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fits (small dead space).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= 20.0;
    }

    // 2-step lookahead: if the next item fits in the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit_quality = (post_residual - next_item_size) as f64;
        score -= 25.0 - next_fit_quality.min(25.0) * 0.4;
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize proportionally to how much space we strand.
        score += (next_item_size - post_residual) as f64 * 0.35;
    }

    // Compare against mean residual: bins tighter than average are good targets.
    let dev = (post_residual as f64 - mean_residual) / (mean_residual + 1.0);
    score += dev * 8.0;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize opening new bins, more so as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress;
    }

    // Mild preference for consolidating into fewer open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) more strongly than linear.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize leaving awkward dead space: residual that is too small for
    // typical future items but nonzero.
    let awkward = (post_residual > 0 && post_residual < 10) as i32 as f64;
    score += 25.0 * awkward;

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use this bin's remainder: mild penalty scaled by waste.
            score += 0.05 * post_residual as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer using bins with below-mean residual (larger space) slightly less
    // when item is large, to keep big holes for big items.
    let hole = bin_residual as f64 - mean_residual;
    score -= 0.03 * hole * (item_size as f64 / bin_capacity as f64);

    // Time horizon: early in the stream, be conservative about opening new
    // bins (favor existing bins); late, allow more freedom.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, discount later.
        score += 15.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        // But if no open bin fits well, new bin becomes attractive.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else if fitting_bins_count == 0 {
        // Should not happen, but guard.
        score += 50.0;
    }

    // Mild penalty for spreading across many open bins when item is small.
    if item_size < 30 {
        score += 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;

    // Base: quadratic in post_residual (dead space penalized super-linearly)
    let mut score = pr * (1.0 + 1.5 * norm_pr);

    // Smooth coupling with stream progress: late in the stream, tight fits matter more
    score += 20.0 * norm_pr * norm_pr * progress;

    // Reward near-full packing via cubic term on residual utilization
    let utilization = (cap - pr) / cap;
    score -= 10.0 * utilization * utilization * utilization;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 30.0 * progress;
    }

    // Lookahead: if next item can use the post residual, reward; else penalize waste
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let waste = pr / cap; // for new bin, post_residual = cap - item
        let fit_quality = 1.0 - waste; // higher = tighter fit
        score += 40.0 * fit_quality + 15.0 * progress;
    }

    // Mild dispersion penalty: avoid creating residuals far from mean
    score += 0.05 * (pr - mean_residual).abs();

    // Slight preference for consolidating into fewer bins
    score += 0.5 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: dead space in [1..10] is nearly useless,
    // [11..20] marginal, [21..35] usable for small items, >35 valuable.
    let class = post_residual / 10; // integer division harmonic bucket
    match class {
        0 => score += 25.0,                 // 0..9 : dead space penalty
        1 => score += 8.0,                  // 10..19
        2 => score -= 2.0,                  // 20..29
        3 => score -= 6.0,                  // 30..39
        _ => score -= 10.0,                 // 40+  : excellent leftover
    }

    // Perfect / near-perfect fit rewards
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead coupling: does the leftover accommodate the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // exact modulo match is a jackpot
            if post_residual % next_item_size == 0 && post_residual == next_item_size {
                score -= 30.0;
            } else if post_residual - next_item_size <= 10 {
                score -= 12.0; // next item leaves only tiny waste
            } else {
                score -= 4.0;
            }
        } else {
            // leftover cannot host next item: penalize proportionally to wasted potential
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base reluctance to open a new bin
        score = cap + 40.0;
        // if item fits almost perfectly in the fresh bin, that's fine anyway
        if item_size as f64 / cap > 0.9 {
            score -= 40.0;
        }
        // early in stream or many bins already open: discourage new bins less
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 15.0;
        // if existing bins are crowded on average, a new bin is reasonable
        if mean_residual < item_size as f64 {
            score -= 50.0;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.05 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // Gaps that no plausible item (>=1, but realistically small) can use are waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fits are highly desirable.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 25.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot go here; mild penalty for wasting the lookahead opportunity.
        score += 6.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (encourage consolidation rather than spreading).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score += pressure * 2.0 * (1.0 - progress * 0.5);

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and existing residuals are poor fits.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.2;
        // If item is large, a fresh bin is more attractive.
        if item_size > bin_capacity / 2 {
            score -= 12.0;
        }
    }

    // Prefer bins whose residual is tight relative to the item (good fill ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    // Mean residual coupling: when mean residual is high, spreading is less costly;
    // when low, pack tightly.
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing the bin exactly.
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: reward when the next item fits into the post residual.
    if next_item_size > 0 {
        let next_fits = next_item_size <= post_residual;
        if next_fits {
            // Reward proportional to how snugly the next item would fit.
            score -= 40.0 + (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Penalize dead space that the next item cannot use.
            score += (post_residual as f64 - (next_item_size as f64 - post_residual as f64)) * 0.3;
            // If post residual is too small for anything useful (below min size),
            // penalize proportionally to wasted space.
            if post_residual < 10 {
                score += (10 - post_residual) as f64 * 4.0;
            }
        }
        // Chain fit: next item exactly fills post residual -> excellent two-item plan.
        if next_item_size == post_residual {
            score -= 60.0;
        }
    }

    // Last chance: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Relative to mean residual: prefer bins that are already more filled
    // (smaller residual) than average -> best-fit style bias.
    score += (bin_residual as f64 - mean_residual) * 0.6;

    // New-bin candidate handling: make opening a new bin attractive only when
    // the item is large and no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin: residual after placement is large.
        score += 25.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            // A fresh bin can host a clean two-item sequence.
            score -= 30.0;
        }
        if item_size >= 50 {
            score -= 20.0;
        }
        // Early in the stream, opening bins is cheap; late, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
    }

    // Mild preference for tighter fits overall (quadratic dead-space penalty).
    let r = post_residual as f64;
    score += 0.02 * r * r / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportional fill achieved.
    let fill = item_size as f64 / cap;
    score -= 60.0 * fill * fill;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (next - post_residual as f64).abs() < 0.5 {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next / cap);
        } else {
            // Next item won't fit here; slight penalty proportional to wasted potential.
            score += 6.0 * (1.0 - post_residual as f64 / cap);
        }
    }

    // Last-chance bonus: only this bin can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 70.0;
    }

    // Slight preference for bins with below-mean residual when many bins are open
    // (keeps a diverse residual portfolio; equalizes when few bins).
    let mean_gap = bin_residual as f64 - mean_residual;
    if open_bins_count > 4 {
        score += 0.15 * mean_gap.max(0.0);
        score -= 0.05 * (-mean_gap).max(0.0);
    }

    // Early in stream: be pickier about perfect fits (favor spreading); late: just fill.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 10.0 * (1.0 - (post_residual as f64 / cap).abs());

    // Brand-new empty bin: only attractive when item is huge or no good open option.
    if bin_residual == bin_capacity {
        if item_size >= 60 {
            score -= 15.0;
        } else {
            score += 20.0 + 0.3 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = norm_pr * (1.0 + 0.8 * progress * progress + 0.4 * progress);

    // Penalize near-full residuals less late in the stream (dead space matters less)
    let tightness = 1.0 - (norm_pr * norm_pr);
    score += 2.0 * tightness * (1.0 - progress);

    // Reward tight fits (small post residual) more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 3.0 + 2.0 * progress;
    }

    // Lookahead: prefer bins whose post_residual can host next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = (pr - next_item_size as f64) / cap;
        score -= 1.5 * (1.0 - slack * slack) * (0.5 + progress);
    } else if next_item_size > 0 {
        score += 1.0 + progress;
    }

    // Mild penalty for spreading across many open bins
    score += 0.02 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Deviation from mean residual: prefer bins near the mean (balanced packing)
    score += 0.3 * (pr - mean_residual).abs() / cap;

    // New bin candidate: neutral baseline, only chosen if no decent fit exists
    if bin_residual == bin_capacity {
        score = 6.0 + 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space?
    // Residuals divisible into small harmonics (e.g. 25, 20, 10) are reusable.
    let r = post_residual;
    if r == 0 {
        score -= 60.0; // perfect fill
    } else {
        let harmonic: f64 = if r % 25 == 0 {
            3.0
        } else if r % 20 == 0 {
            2.5
        } else if r % 10 == 0 {
            2.0
        } else if r % 5 == 0 {
            1.0
        } else {
            0.0
        };
        score -= harmonic * 8.0;

        // Integer-division thresholds: dead space smaller than typical items is wasted.
        if r < 10 {
            score += 25.0; // unusable dead space
        } else if r < 20 {
            score += 10.0;
        }

        // Fraction of capacity wasted
        score += (r as f64 / bin_capacity as f64) * 15.0;
    }

    // Lookahead coupling: if next item fits exactly into post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 40.0;
        } else if next_item_size <= r {
            // next item fits; harmonic compatibility of leftover after next
            let r2 = r - next_item_size;
            if r2 % 10 == 0 { score -= 12.0; }
            score -= 6.0;
        } else {
            // next item won't fit here: penalize leaving tight-but-broken space
            if r >= next_item_size.saturating_sub(5) {
                score += 12.0;
            }
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 3.0 + (mean_residual / bin_capacity as f64) * 20.0;
        score += 45.0 - pressure.min(45.0);
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 20.0; // big next item: fresh bin is fine
        }
    }

    // Stream progression: later in stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: post_residual as dead space, but weight it non-linearly.
    // Small post-residuals (1..=10) are "unusable dead space" -> heavy penalty.
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps that are too small for typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64);
    }

    // Reward tight fits: post_residual near zero is excellent.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly in the post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_tight = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
        score -= 15.0 * next_tight;
    }
    // If next item cannot fit in the leftover, mild penalty for creating stranded space.
    else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize new-bin / spreading behavior).
    score += 0.35 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it unattractive unless residual pressure is high
    // or the fit in open bins would be terrible.
    if bin_residual == bin_capacity {
        score += 40.0 + 2.0 * open_bins_count as f64;
        // If mean residual across open bins is small (bins nearly full),
        // a new bin becomes more acceptable.
        score -= mean_residual.min(60.0) * 0.4;
    }

    // Mean-residual coupling: prefer bins below mean residual (fill fuller bins first).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Slight late-stream urgency to consolidate as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: penalize dead space quadratically, but forgive residuals that
    // exactly match the next item's size (perfect 2-step lookahead match).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0; // chain fit: this bin will be perfectly consumed next step
    } else if next_item_size > 0 && post_residual > next_item_size {
        // next item fits too: mild bonus proportional to tightness of the pair
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item won't fit in the leftover: penalize small unusable remnants
        let rem = post_residual as f64;
        if rem < 10.0 {
            score += 25.0; // tiny dead space is nearly worthless
        }
    }

    // Prefer bins whose residual deviates below the mean (tighter bins fill first),
    // keeping loose bins available for large future items.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 20.0 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Late in the stream, closing bins tightly matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Never prefer a fresh bin when a good fit exists elsewhere; make the empty
    // bin expensive unless the item is large relative to typical residual.
    if bin_residual == bin_capacity {
        let big_item = (item_size as f64) > mean_residual + 5.0;
        if big_item {
            score -= 5.0; // opening a new bin for an oversized item can be right
        } else {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize dead space that cannot be reused by typical items (max next item 100).
    if post_residual > 0 {
        let waste = (post_residual as f64).powf(1.8);
        score += waste * 0.4;
    }

    // Reward tight fits: post_residual near 0 is excellent.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 - slack.min(30.0) * 0.5;
    }

    // Penalize leaving a gap that the next item just barely misses (near-fit frustration).
    if next_item_size > post_residual && post_residual > 0 {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 15.0 {
            score += 20.0 - miss * 1.2;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a bin is usually bad unless existing fits are poor.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 150.0;
        // Reduce penalty if many open bins are fragmented (mean residual low) and few fit.
        let frag = (mean_residual - post_residual as f64).abs();
        score -= frag * 0.3;
        // Late in the stream, closing out bins matters less; slightly cheaper to open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 20.0;
        // If this is the last chance, allow opening a new bin more readily.
        if fitting_bins_count == 1 {
            score -= 70.0;
        }
        // Few open bins: opening is cheaper.
        if open_bins_count <= 2 {
            score -= 30.0;
        }
    }

    // Mild preference for bins below mean residual (consolidate fuller bins).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.15;

    // Prefer filling bins with more residual when the item is large (avoid stranding big items).
    if item_size > 60 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize post residual, but the penalty grows non-linearly with stream progress
    // (later in the stream, dead space is more costly to recover).
    let mut score = pr * (1.0 + 2.0 * progress * progress);

    // Non-linear waste coupling: residual^2 scaled by progress — punishes small unusable gaps more as stream advances.
    score += (norm_pr * norm_pr) * cap * (0.5 + progress);

    // Perfect fit reward (smooth exponential-like decay via polynomial approximation).
    let perfect = 1.0 - norm_pr;
    score -= 8.0 * perfect * perfect * perfect * (1.0 + 0.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - 0.5 * progress);
    }

    // Scarcity pressure: many open bins with high mean residual -> prefer filling existing bins.
    let scarcity = (open_bins_count as f64).ln1p() * (mean_residual / cap);
    score -= 3.0 * scarcity * (1.0 + progress);

    // Lookahead: reward leaving space that still fits the next item (smooth interaction).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack_ratio = 1.0 - (pr - nxt) / cap;
            score -= 4.0 * slack_ratio * slack_ratio * nxt / cap;
        } else {
            // Penalize leaving a gap that cannot fit the lookahead item, scaled by how far off it is.
            let gap = (nxt - pr) / cap;
            score += 6.0 * gap * gap * (1.0 + progress);
        }
    }

    // Mild preference for tighter bins (smaller residual before placement) via smooth coupling.
    score += 0.02 * (bin_residual as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // --- Harmonic class of the leftover space ---
    // Class 0: perfect fill (post_residual == 0) -> huge reward
    // Class 1: unusable sliver (post_residual < 10) -> dead space penalty
    // Class 2: usable chunk (post_residual >= 10) -> mild reward scaled by size
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual < 10 {
        score += 120.0; // dead space: nearly unusable sliver
    } else {
        // reward proportional to how much space is still "harmonically usable"
        // i.e., divisible into the smallest item class (10)
        let harmonic_use = (post_residual / 10) as f64 * 10.0;
        score -= 0.35 * harmonic_use;
        // penalty for non-multiple-of-10 remainder (waste fraction)
        let waste = post_residual % 10;
        score += 3.0 * waste as f64;
    }

    // --- Integer-division threshold classes on post_residual ---
    // Buckets: [10..25), [25..50), [50..75), [75..100)
    // Mid-range leftovers are the most flexible; extreme ones less so.
    let bucket = post_residual / 25;
    match bucket {
        0 => score += 8.0,           // small but usable
        1 => score -= 10.0,          // sweet spot: quarter-to-half free
        2 => score -= 4.0,           // decent
        _ => score -= 2.0,           // large leftover (almost-empty bin)
    }

    // --- Lookahead coupling: does next_item_size fit in post_residual? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // great: chain the next item here
            let fit_quality = (post_residual - next_item_size) as f64;
            score -= 40.0 + 0.5 * fit_quality;
            // harmonic bonus if next item exactly divides leftover
            if post_residual % next_item_size == 0 {
                score -= 25.0;
            }
        } else {
            // next item won't fit here: mild penalty, stronger if sliver remains
            score += 15.0;
            if post_residual < 10 {
                score += 30.0;
            }
        }
    }

    // --- Last-chance bin: if this is the only fitting bin, strongly prefer it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // --- New-bin candidate logic ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when the current item fits
        // poorly everywhere else or open bins are congested.
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / cap);
        if fitting_bins_count == 0 {
            score -= 300.0; // must open a bin
        } else if item_size >= 60 {
            // big items: prefer fresh bin unless a near-perfect fit exists elsewhere
            score -= 20.0 + 0.3 * congestion;
        } else {
            // small/medium items: keep filling existing bins
            score += 45.0 + 5.0 * congestion;
        }
        // late in the stream, avoid scattering into new bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // --- Capacity-fraction alignment: reward placements near harmonic fractions ---
    let fill_frac = item_size as f64 / cap;
    for &f in &[0.25_f64, 0.5, 0.75, 1.0] {
        let d = (fill_frac - f).abs();
        if d < 0.05 {
            score -= 12.0;
        }
    }

    // --- Mean-residual coupling: prefer bins close to the mean (balance) ---
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    // --- Tie-break: prefer tighter bins (smaller residual) slightly ---
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
