            score += 8.0;
        }
    }

    // Mean residual coupling: prefer bins below mean residual (more filled bins first).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: make it moderately attractive only when current bins fit poorly.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
