    // Penalize dead space: residuals too small for the smallest plausible item
    let small_item_floor = 1.0;
    if (post_residual as f64) > 0.0 && (post_residual as f64) < small_item_floor + 3.0 {
        score += 0.0; // tiny residuals may still be usable
    }
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // dead space penalty
    }

    // Lookahead coupling: reward bins whose post residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 60.0;
            // extra reward if post residual fits next item snugly
            let slack = post_residual - next_item_size;
            if slack < 5 {
                score -= 25.0;
            }
        } else {
            // post residual can't host next item: penalize proportionally to waste
            let unusable = post_residual as f64 / bin_capacity as f64;
            score += 30.0 * unusable;
        }
    }

    // Last-chance bin bonus: only one bin fits -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Tightness reward: favor bins that are already well-filled
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 50.0 * fill_ratio;

    // Prefer bins with residual close to item size (snug fit)
    let snug = (bin_residual - item_size) as f64;
    score += 0.3 * (snug - mean_residual).abs();

    // Time horizon: early in the stream, be conservative with new bins;
    // late in the stream, pack tightly into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * fill_ratio;

    // Many open bins: discourage opening new bins, encourage consolidation
    if bin_residual == bin_capacity {
        // candidate new bin
        let new_bin_penalty = 150.0 + 12.0 * open_bins_count as f64 + 80.0 * progress;
        // but if nothing fits well (large post residual waste), new bin may win
        let waste_existing = if post_residual < bin_residual {
            (bin_residual - item_size) as f64
        } else {
            0.0
        };
        score = new_bin_penalty + waste_existing * 0.5;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 40.0;
        }
    } else {
        // existing bin: consolidation pressure when many bins are open
        score += 2.0 * open_bins_count as f64 * (1.0 - fill_ratio);
    }

    // Mean residual anchoring: prefer bins whose residual is near the mean
    // (keeps the bin population homogeneous, easier future packing)
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post-residual with non-linear (quadratic/cubic) shaping.
    let mut score = pr * (1.0 + 0.6 * pr_norm) + 20.0 * pr_norm * pr_norm;

    // Smooth polynomial coupling of post-residual with stream progress:
    // later in the stream, tighter packing of residual matters more.
    let coupling = pr_norm * (1.0 - pr_norm) * 4.0; // smooth bump in [0,1]
    score += coupling * (40.0 + 60.0 * progress);

    // Penalize dead space that likely cannot be used by the next item.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let slack = pr - ns;
        if slack >= 0.0 {
            // next item fits: reward a bit
            score -= 5.0 * (1.0 - slack / cap);
        } else {
            // next item does not fit: penalize unusable residual smoothly
            let unusable = (-slack) / cap;
            score += 15.0 * unusable * (1.0 + progress);
        }
    }

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 + 20.0 * progress;
    }

    // Mild penalty for spreading across too many open bins early on.
    let open_norm = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += 2.0 * open_norm * pr_norm * (1.0 - progress);

    // Keep a fresh-bin candidate competitive only when residual is large.
    if bin_residual == bin_capacity {
        score += 5.0 * (1.0 - progress) - 3.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify into capacity fractions.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let dead_threshold = 10u32; // smallest possible item

    // Class 0: unusable dead space (nothing can fit) -> strongly reward fullness
    if post_residual < dead_threshold {
        score -= 60.0 + (dead_threshold - post_residual) as f64;
    }
    // Class 1: "harmonic small" zone [10, quarter): only small items fit
    else if post_residual < quarter {
        score -= 12.0;
        // residue modulo classes: post_residual divisible by small harmonics
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 5 == 0 { score -= 3.0; }
    }
    // Class 2: mid zone [quarter, half): decent but not ideal
    else if post_residual < half {
        score -= 4.0;
        if post_residual % 10 == 0 { score -= 4.0; }
    }
    // Class 3: large zone [half, capacity): wasteful placement, penalize
    else {
        score += 15.0;
    }

    // Perfect / near-perfect fit reward via modular harmonic classes
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: does next_item_size fit into the harmonic class of post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item still fits: reward proportionally to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / cap);
            // harmonic bonus: next item lands exactly on a class boundary
            if (post_residual - next_item_size) % 10 == 0 { score -= 5.0; }
        } else {
            // next item won't fit here: penalize mildly unless this bin was last-chance
            score += 6.0;
        }
    } else {
        // last item in stream: minimize residual waste maximally
        score -= 20.0;
    }

    // Last-chance bin logic: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 45.0;
        // but if mean residual across open bins is large (fragmented), new bin is attractive
        if mean_residual > cap * 0.6 { score -= 30.0; }
        if open_bins_count == 0 { score -= 100.0; }
    }

    // Stream progression: early on, prefer tight packing; late, consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / cap);

    // Fragmentation pressure: many open bins with high mean residual -> favor big-fill bins
    if open_bins_count > 3 && mean_residual > cap * 0.4 {
        score -= (item_size as f64 / cap) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
        if post_residual > 30 {
            score += 15.0; // bad fit cancels part of the last-chance bonus
        }
    }

    // Open-bin pressure: many open bins -> discourage spreading, encourage filling.
    let pressure = open_bins_count as f64;
    score += pressure * 1.5 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: only attractive when current fit wastes space
    // or the next item fits perfectly in a fresh bin.
    if bin_residual == bin_capacity {
        let next_fits_fresh = next_item_size > 0 && next_item_size <= bin_capacity;
        let fresh_bonus = if next_fits_fresh && (bin_capacity as f64 - next_item_size as f64).abs() < 1e-9 {
            -45.0
        } else if next_fits_fresh && next_item_size >= bin_capacity - post_residual.max(0) {
            -20.0
        } else {
            20.0
        };
        score += fresh_bonus + pressure * 2.0;
    }

    // Lookahead: if the next item exactly consumes the post residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item can't use leftover; leftover is likely dead space
        score += (post_residual as f64).min(15.0);
    }

    // Mild stream progression effect: later in stream, tighten packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: if this bin is much tighter than average, favor it.
    score -= (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already favored).

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward proportional to how snugly the next item will fit here.
            let lookahead_slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - lookahead_slack / bin_capacity as f64);
            // Extra bonus for near-perfect two-item packing.
            if post_residual == next_item_size {
                score -= 20.0;
            }
        } else {
            // Penalize dead space that the next item cannot use.
            score += 0.5 * (post_residual as f64 - (post_residual as f64 % next_item_size as f64));
            score += 3.0;
        }
    } else {
        // Last item: only tightness matters.
        score -= 5.0;
    }

    // Relative-to-mean residual: prefer bins already below average fill pressure
    // (consolidating waste into few bins).
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 0.3 * (mean_residual - res);
    } else {
        score += 0.3 * (res - mean_residual);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless existing fits are bad.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Allow new bin early in stream when many bins will be needed anyway.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // If next item is huge, a fresh bin gives flexibility.
        if next_item_size >= 60 {
            score -= 8.0;
        }
    }

    // Mild penalty for leaving residuals in the awkward 1..=9 dead zone.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
        } else {
            score += 8.0;
        }
        // Chain fit: post residual leaves a good chunk for the next item
        let chain = post_residual.min(next_item_size.saturating_sub(1)) as f64;
        score += 0.05 * chain;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Global pressure: many open bins with high mean residual -> prefer consolidation
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score -= 0.15 * pressure;

    // Time horizon: late in the stream, be conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress;

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        let fit_quality = item_size as f64 / bin_capacity as f64;
        let bad_fit = post_residual as f64 > 0.0 && next_item_size > 0
            && post_residual < next_item_size;
        let mut new_bin_score = 30.0 + 0.5 * (open_bins_count as f64);
        if bad_fit { new_bin_score -= 45.0; }
        if next_item_size > 0 && post_residual >= next_item_size { new_bin_score += 10.0; }
        // New bins are fine early, expensive late
        new_bin_score += 40.0 * progress;
        if fit_quality > 0.8 { new_bin_score -= 15.0; }
        score = score.min(new_bin_score);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let post_norm = post / cap;

    // Base: prefer small post residual, with non-linear (quadratic/cubic) shaping.
    let mut score = post + 60.0 * post_norm * post_norm + 40.0 * post_norm * post_norm * post_norm;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, dead space becomes more costly.
    let coupling = post_norm * (1.0 - post_norm) * 4.0; // peaks at post_norm = 0.5
    score += coupling * 30.0 * (0.5 + progress);

    // Tight fit reward: subtract when item fills most of the bin.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill * fill;

    // Last-chance bin: strongly favor using it (avoid opening a new bin).
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * progress;
    }

    // Penalize opening a new bin when open bins fit well, unless item is large
    // and residual is near-capacity (new-bin candidate case: residual == capacity).
    if bin_residual == bin_capacity {
        let large = (item_size as f64 / cap) * (1.0 - item_size as f64 / cap) * 4.0;
        score += 15.0 * (1.0 - large) * (1.0 - progress) - 10.0 * large;
    }

    // Lookahead: bonus if the post residual can host the next item exactly-ish.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / cap);
    } else if next_item_size > 0 {
        // Post residual too small for next item: mild penalty scaled by dead space.
        score += 8.0 * post_norm * post_norm;
    }

    // Mild penalty for spreading across many open bins.
    score += 0.3 * (open_bins_count as f64).sqrt() * post_norm;

    // Encourage balancing residuals toward the mean early on.
    score += 2.0 * (1.0 - progress) * (post - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: quantize into capacity fractions.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Reward near-perfect fits: residual classes 0..=5 are "harmonic".
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 18.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    }

    // Penalize "dead space" classes: residuals that few item sizes can use.
    // Items are 1..100; a residual r is usable if r >= 1, but small awkward
    // bands (like 51..=59 or 76..=89 after big items) are hard to fill.
    let m = post_residual % 25;
    if m >= 20 && post_residual < 50 {
        score += 6.0; // awkward sub-class
    }

    // Reward residuals that are multiples of common item sizes (harmonic resonance).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 7.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 22.0;
        } else {
            score -= (next_item_size as f64) * 0.15;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this bin's remainder -> penalize leftover.
        score += frac * 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a mild default so that any
    // decent existing fit beats it, but a truly bad fit does not.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.05 * (open_bins_count as f64);
    }

    // Stream progression: late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.05;

    // Prefer bins tighter than the mean (best-fit flavor).
    score += (bin_residual as f64 - mean_residual) * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: residuals too small to ever be useful (min item size 1..100 unknown,
    // so treat gaps < 10 as near-dead, gaps < next_item_size as unusable for lookahead).
    if post_residual < 10 {
        score += 60.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits (waste ratio relative to item size).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 30.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; with few, opening new bins is cheap.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += 0.8 * pressure * (mean_residual / bin_capacity as f64).ln().abs().min(2.0);

    // New-bin candidate: only attractive when current bin residuals are large and fragmented.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        if fitting_bins_count <= 1 {
            score -= 55.0; // forced new bin anyway
        } else if avg_fill < 0.35 {
            score -= 20.0; // early: fresh bin fine
        } else {
            score += 35.0 + 40.0 * avg_fill; // late: keep packing into open bins
        }
    }

    // Lookahead synergy: prefer bins whose leftover accommodates the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

