            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot fit: penalize dead space relative to gap.
            score += 0.5 * gap;
        }
    }

    // Relative to mean residual: bins with residual near mean are "typical"; prefer
    // bins that are more filled than average (lower residual than mean).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize so it's chosen only when fits are truly bad.
    if bin_residual == bin_capacity {
        score += 40.0 + 0.2 * open_bins_count as f64;
        // Allow new bin late in stream if lookaheads are hopeless elsewhere.
        if next_item_size == 0 {
            score += 20.0;
        }
    }

    // Slight preference for consolidating into fewer bins as stream progresses.
    score += 0.05 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

