    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (0.5 + 0.5 * progress);

    let mut score = pr * (1.0 + 0.6 * poly);

    // Penalize large dead space more aggressively as stream progresses
    score += 8.0 * norm_pr * norm_pr * norm_pr * (0.3 + progress);

    // Perfect fit reward (smooth)
    let fit_quality = 1.0 - norm_pr;
    score -= 12.0 * fit_quality * fit_quality * fit_quality;

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead coupling: if next item fits the post residual, reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 6.0 * (1.0 - slack * slack);
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // New-bin candidate: keep it neutral-to-slightly-penalized unless residuals are tight
    if bin_residual == bin_capacity {
        score += 3.0 + 10.0 * (mean_residual / cap) * (1.0 - progress);
    }

    // Mild pressure against proliferating bins
    score += 0.15 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean residual divergence penalty
    score += 2.0 * (norm_pr - mean_residual / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize leftover space into capacity fractions.
    // Classes: [0..5], (5..15], (15..30], (30..50], (50..cap]
    let pr = post_residual;
    let class: f64 = if pr == 0 { 0.0 }
        else if pr <= 5 { 1.0 }
        else if pr <= 15 { 2.0 }
        else if pr <= 30 { 3.0 }
        else if pr <= 50 { 4.0 }
        else { 5.0 };
    score -= 12.0 * class; // reward leaving residuals in "useful" harmonic bands

    // Perfect or near-perfect fit is strongly favored.
    if pr == 0 { score -= 40.0; }
    else if pr <= 5 { score -= 20.0; }

    // Lookahead compatibility: reward when next item fits the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt) <= pr as f64 {
            // next item fits: reward proportionally to how snugly
            score -= 10.0 * (1.0 - (pr as f64 - nxt) / cap);
        } else {
            // next item does NOT fit this residual: penalize wasting space
            score += 6.0 * (1.0 - pr as f64 / cap);
        }
        // Harmonic modulo check: next item pairs well if post_residual % next_item_size leaves small remainder
        if next_item_size > 0 && pr >= next_item_size {
            let rem = pr % next_item_size;
            if rem <= 5 { score -= 8.0; }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: penalize unless current bin fit is poor.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 30.0;
        // cheaper to open new bin when many bins are open and mean residual is small
        score -= 0.3 * open_bins_count as f64;
        score -= 10.0 * (1.0 - mean_residual / cap);
        // opening a bin early in the stream is fine; late is expensive
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // if item is large relative to capacity, new bin is natural
        score -= 0.2 * item_size as f64;
    }

    // Mild preference for tighter bins overall (small residual before placement).
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }
    // Reward residual that exactly fits the lookahead item (k=2 synergy).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize residuals too small for the next item (dead space for the future).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * tightness;

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // when few bins are open, opening a new bin is relatively cheap.
    let pressure = (open_bins_count as f64 / (1.0 + step_index as f64)).min(1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when bin pressure is high.
        score += 12.0 + 30.0 * pressure;
        // Cheap to open early in the stream.
        score -= 10.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    } else {
        // Reward using existing bins, especially under pressure.
        score -= 8.0 * pressure;
    }

    // Last-chance bin: strongly favor using it to avoid waste.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer bins below mean residual (emptier bins) to keep tight bins for big items.
    score -= 0.05 * (mean_residual - bin_residual as f64);

    // Early stream: be greedy with filling; late stream: avoid fragmentation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits (low post_residual)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // next item fills this bin perfectly
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // penalize large gap between post_residual and next item
            score += gap * 0.5;
            // reward if next item leaves a still-usable residual
            let next_post = post_residual - next_item_size;
            if next_post == 0 {
                score -= 300.0;
            } else if next_post <= 10 {
                score -= 50.0;
            }
        } else {
            // next item cannot fit here; post_residual becomes dead space unless large
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 0.3;
        }
    }

    // Compare against mean residual: bins tighter than average are better targets
    score -= (mean_residual - post_residual as f64) * 0.2;

    // Last-chance bin bonus: if only this bin fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Penalize new-bin candidate unless item is huge or no good fit exists
    if bin_residual == bin_capacity {
        score += 40.0; // base cost of opening a new bin
        if item_size > 70 {
            score -= 60.0; // big items are fine in fresh bins
        }
    }

    // Late in stream, prefer closing out bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer bins that leave residuals usable for typical item sizes.
    if post_residual > 0 {
        let usable = if post_residual >= 10 { 0.0 } else { (10 - post_residual) as f64 * 2.5 };
        score += usable;
    }

    // Exact / near-exact fits get strong reward.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Lookahead: if next item fits into post_residual, reward; if next item
    // would fit this bin better than the current item, slight penalty for waste.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        }
        if bin_residual >= next_item_size && post_residual < next_item_size {
            // current placement destroys room for next item: mild penalty
            score += 3.0;
        }
    }

    // Penalize opening a new bin, more strongly when many bins are open.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
        // But if existing bins are all crowded (mean residual small) and
        // this item is large, new bin is less bad.
        let progress = step_index as f64 / (total_items.max(2) as f64);
        let crowded = mean_residual < item_size as f64 * 1.2;
        if crowded {
            score -= 20.0 + 5.0 * progress;
        }
        // Large items early: better to pack them into existing space.
        if item_size > 70 {
            score += 10.0;
        }
    }

    // Mild preference for bins with residual close to item size (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.15;

    // Global state: spread items across bins when mean residual is high.
    score -= 0.05 * mean_residual;

    // Early stream: encourage consolidation; late stream: allow slight
    // relaxation to close out bins.
    let progress = step_index as f64 / (total_items.max(2) as f64);
    score *= 1.0 - 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Smooth non-linear coupling: post_residual penalized more heavily as stream progresses
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);
    // Reward tight fits, weighted by stream progress
    score -= 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.4 + 0.6 * progress);
    // Dead-space hazard: small post-residual that can't fit typical next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let waste = (ns - pr).max(0.0) / cap;
        score += 10.0 * waste * (1.0 - progress);
        // Reward bins whose post-residual still fits the next item
        let fits_next = if pr >= ns { 1.0 } else { 0.0 };
        score -= 5.0 * fits_next * (0.5 + 0.5 * progress);
    }
    // Last-chance bin bonus: smooth in fitting_bins_count
    let scarcity = 1.0 / (fitting_bins_count as f64);
    score -= 6.0 * scarcity * (0.3 + 0.7 * progress);
    // Mild coupling with mean residual to prefer bins deviating from the mean when tight
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev * (1.0 - progress);
    // New-bin candidate: penalize opening new bins smoothly with progress and open bins
    if bin_residual == bin_capacity {
        score += 15.0 * (0.3 + 0.7 * progress) + 0.5 * open_bins_count as f64;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;

    // --- Harmonic class of the post-residual (decade classes) ---
    // Class 0 (0..10): dead space, nearly unusable -> heavy penalty
    // Class 1 (10..20): marginal -> mild penalty
    // Classes 2..5: increasingly reusable -> graded rewards
    let class = pr / 10;
    score += match class {
        0 => 22.0,
        1 => 9.0,
        2 => 0.0,
        3 => -2.0,
        4 => -4.0,
        _ => -6.0,
    };

    // Perfect fit: harmonic class zero, ideal closure of a bin
    if pr == 0 {
        score -= 18.0;
    }

    // Modulo coupling: residuals that are nice multiples of common item
    // granularities (mod 10 == 0) tend to combine well with future items.
    if pr % 10 == 0 && pr > 0 {
        score -= 3.0;
    }

    // --- Lookahead (k=2) ---
    if next_item_size > 0 {
        if pr >= next_item_size {
            // next item can also land here: chain placement is valuable
            score -= 7.0;
            // extra reward if next item exactly fills what remains after
            if pr - next_item_size == 0 {
                score -= 6.0;
            }
        } else {
            // this placement strands the lookahead item elsewhere
            score += 5.0;
        }
    }

    // --- Last-chance bin: avoid opening a new bin when this is the only fit ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 16.0;
    }

    // --- New-bin candidate (bin_residual == bin_capacity) ---
    if bin_residual == bin_capacity {
        // by default prefer reusing an open bin
        score += 12.0;
        // if few bins can fit the item, opening fresh space is attractive
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
        // late in the stream, consolidate rather than proliferate bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 6.0;
    }

    // --- Coupling with the mean residual across open bins ---
    // Placing into a bin whose post-residual deviates favorably from the
    // mean (leaving more usable space than average) is rewarded.
    score += (mean_residual - pr as f64) * 0.05;

    // Mild pressure to keep the number of open bins from exploding
    score += open_bins_count as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 {
        let pr = post_residual as f64;
        // Dead-space penalty: tiny leftovers are penalized far more than their size.
        if pr < 10.0 {
            score += 60.0 * (10.0 - pr) / 10.0; // unusable sliver
        } else if pr < 20.0 {
            score += 25.0 * (20.0 - pr) / 10.0; // only fits smallest items
        }
        // Reward perfect and near-perfect fits.
        if post_residual == 0 {
            score -= 100.0;
        } else if post_residual <= 5 {
            score -= 40.0;
        }
        // Reward a residual that can still host a typical future item.
        if post_residual >= 30 {
            score -= 8.0;
        }
    } else {
        score -= 100.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 - slack.min(30.0) * 0.5;
    }
    // Penalize if next item would be stranded by a tiny leftover.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, favor consolidation into existing bins.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    if bin_residual < bin_capacity {
        score -= 4.0 * pressure;
    } else {
        // New-bin candidate: penalize mildly, more when many bins are open.
        score += 10.0 + 6.0 * pressure;
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 12.0 * (1.0 - progress);
    }

    // Prefer bins tighter than the mean residual (better fit quality).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= 0.3 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but keep a floor so post_residual stays the anchor.
    let pr = post_residual as f64;
    score = 0.6 * pr + 0.4 * (pr * pr) / (bin_capacity as f64);

    // --- 2-step lookahead: reward exact match of post_residual to next item ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        // Perfect 2-step chaining (post_residual == next_item_size) is ideal.
        if gap < 1.0 {
            score -= 25.0;
        } else {
            score += 0.8 * gap;
            // If next item cannot fit here at all, this bin is a dead end for the chain.
            if pr < nxt {
                score += 6.0 + 0.15 * (nxt - pr);
            }
        }
        // Bonus if the bin after two placements would be nearly full (waste < 10).
        let two_step_residual = pr - nxt;
        if two_step_residual >= 0.0 && two_step_residual < 10.0 {
            score -= 12.0;
        }
    } else {
        // Last item: just minimize leftover waste.
        score -= 10.0;
    }

    // --- Relative to mean residual: avoid leaving much more space than average ---
    score += 0.5 * (pr - mean_residual).max(0.0);
    // Slight reward for being tighter than average.
    score -= 0.25 * (mean_residual - pr).max(0.0);

    // --- Last-chance bonus: if this is the only bin that fits, avoid opening a new one ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive for large items with no good chain,
        // or when open bins are heavily fragmented.
        let fragmentation = if open_bins_count > 0 { mean_residual / (bin_capacity as f64) } else { 0.0 };
        score += 20.0 - 18.0 * fragmentation;
        // For small items, almost always prefer an existing bin.
        if item_size <= 30 {
            score += 15.0;
        }
        // If the next item is small, a fresh bin wastes its potential.
        if next_item_size > 0 && next_item_size <= 30 {
            score += 8.0;
        }
    }

    // Mild stream-progression pressure: late in the stream, tighten up and
    // avoid spawning bins for marginal gains.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    } else {
        score -= 4.0 * progress;
    }

    // Penalize creating tiny unusable slivers (< 5) which are near-dead space.
    if pr > 0.0 && pr < 5.0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) more aggressively than linear.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Penalize bins whose residual becomes a "dead zone" that next item cannot use.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 12.0 + 0.25 * post_residual as f64;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            // Reward bins that can also accommodate the lookahead item.
            let slack = post_residual - next_item_size;
            score -= 6.0 * (1.0 - slack as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: pure tightness matters.
        score -= 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
        if post_residual <= bin_capacity / 10 {
            score -= 10.0;
        }
    }

    // Dynamic time horizon: early in the stream, encourage keeping residuals
    // large (flexibility); late in the stream, prioritize closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let flexibility_weight = 1.0 - progress;
    score += flexibility_weight * 20.0 * (post_residual as f64 / bin_capacity as f64);
    score -= progress * 5.0 * (bin_residual as f64 / bin_capacity as f64);

    // Global state coupling: many open bins with high mean residual suggests
    // fragmentation; prefer bins below the mean residual (consolidation).
    if open_bins_count > 2 {
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 8.0 * dev;
    }

    // Mild penalty for very full bins early on (avoid overfilling when stream unknown).
    if bin_residual as f64 / bin_capacity as f64 > 0.9 && progress < 0.3 {
        score += 4.0;
    }

    // New-bin candidate adjustment: an empty bin is only attractive when the
    // current fit is poor or open bins are heavily fragmented.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / bin_capacity as f64;
        let fragmentation = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        score += 25.0 - 40.0 * fragmentation - 20.0 * (1.0 - poor_fit);
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) - norm_pr * progress;
    score += 8.0 * poly * (1.0 + progress);

    // Penalize dead space more aggressively as stream advances
    score += progress * norm_pr * norm_pr * 12.0;

    // Reward tight fits (small post residual), smoothly
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 4.0;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - progress);
    }

    // Lookahead: favor bins whose post residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 3.0 * (1.0 - pr / (pr + nxt));
        } else {
            score += 2.0 * (nxt - pr) / cap;
        }
    }

    // Slight preference for consolidating into fewer bins when many are open
    score += (open_bins_count as f64).ln().max(0.0) * 0.3 * (norm_pr - mean_residual / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residual divisible by common item sizes
    // (10,20,25,50) is more reusable than odd dead space.
    let mut reusability = 0.0;
    for m in [10u32, 20, 25, 50].iter() {
        if post_residual % m == 0 && post_residual > 0 {
            reusability += 15.0;
        }
    }
    // Small residual that still fits the smallest plausible item is good.
    if post_residual >= 10 {
        reusability += 10.0;
    } else if post_residual > 0 {
        // dead space below minimum item size: penalize
        reusability -= 40.0;
    }
    score -= reusability;

    // Integer-division thresholds on post_residual: prefer residuals in
    // "harmonic bands" that combine well (e.g. can host 2+ mid items).
    let band = post_residual / 20; // 0..5
    score -= band as f64 * 5.0;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot use this residual: mild penalty proportional to waste
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a bin should only win when no open bin
    // offers a decent fit. Empty-bin residual == capacity gets a penalty that
    // scales with how well existing bins could absorb the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // penalize new bins more as the stream matures (amortization)
        score += 80.0 + 40.0 * progress;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: new bin is fine
        }
    }

    // Mild preference to consolidate: fewer open bins -> tighter packing pressure
    score += open_bins_count as f64 * 0.05;

    // Deviation from mean residual: prefer bins whose residual is near-typical
    // unless post_residual is a perfect fit (already rewarded).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    let dead_zone_max = 9u32;
    if post_residual > 0 && post_residual <= dead_zone_max {
        score += (dead_zone_max - post_residual + 1) as f64 * 25.0;
    }
    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to residual (high fill ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Pressure from number of open bins: prefer consolidation when many bins open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).sqrt() * (2.0 + 3.0 * progress);

    // Mean-residual coupling: placing into a bin far from mean residual is penalized,
    // nudging selection toward bins whose residual matches the fleet average.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item is large and this placement leaves nothing for it, slight penalty
    // unless the bin is nearly emptied anyway.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it unattractive unless the current placement would
    // create severe dead space or no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > 0 && post_residual <= dead_zone_max;
        if !poor_fit && fitting_bins_count > 0 {
            score += 45.0 + 5.0 * open_bins_count as f64;
        } else {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
