pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: penalize opening a new bin, but less when
    // the item fits poorly everywhere or residual space is very fragmented.
    if bin_residual == bin_capacity {
        score += 55.0;
        // If mean residual is large, existing bins are roomy -> opening a new
        // bin is more acceptable (reduce penalty slightly).
        score -= (mean_residual / bin_capacity as f64) * 20.0;
        // If the next item is small, new bin will absorb it well.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Lookahead synergy: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward if post-residual is a near-perfect host for next item.
            let slack = post_residual - next_item_size;
            if slack <= 5 {
                score -= 10.0;
            }
        } else {
            // Post-residual too small for next item: dead-space risk scaled by gap.
            let gap = (next_item_size - post_residual) as f64;
            score += (gap / 20.0).min(8.0);
        }
    }

    // Prefer bins below mean residual (larger-than-average space) for big items.
    let residual_f = bin_residual as f64;
    if item_size > 50 {
        score += (mean_residual - residual_f) * 0.3;
    } else {
        // Small items: prefer tighter-than-average bins to preserve big spaces.
        score -= (mean_residual - residual_f) * 0.2;
    }

    // Mild preference for reusing existing bins as open-bin count grows.
    if bin_residual != bin_capacity {
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: post-residual scaled by a smooth polynomial of stream progress.
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Non-linear coupling: dead-space penalty grows quadratically as residual shrinks,
    // modulated by progress so late-stream tightness is punished harder.
    let tightness = 1.0 - (pr / cap);
    score += 6.0 * tightness * tightness * (0.5 + progress);

    // Reward filling a bin nearly exactly, smoothly via a bell-shaped term.
    let fill = item_size as f64 / cap;
    score -= 10.0 * fill * (1.0 - fill) * 4.0 * fill * (1.0 - fill);

    // Lookahead: smooth interaction between post-residual and next item fit.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_quality = 1.0 - ((pr - nxt).abs() / cap);
        score -= 4.0 * fit_quality * fit_quality * (1.0 - progress);
    }

    // Last-chance bonus (smoothly weighted by scarcity of fitting bins).
    if fitting_bins_count <= 1 {
        score -= 5.0 * (1.0 - progress);
    }

    // Mild pressure toward consolidating into existing bins as many bins stay open.
    score += 0.15 * open_bins_count as f64 * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fit classes rewarded
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit: ideal
    } else if pr <= 10 {
        score -= 35.0;
    } else if pr <= 25 {
        score -= 15.0;
    } else if pr <= 50 {
        score += 5.0;
    } else {
        score += 20.0; // large dead space
    }

    // Modulo classes: residuals that are multiples of common item sizes are more reusable
    let reusable = (pr % 10 == 0) || (pr % 20 == 0) || (pr % 25 == 0);
    if reusable {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 18.0;
            // bonus if next item would fill bin nearly exactly
            let gap = pr - next_item_size;
            if gap <= 5 {
                score -= 12.0;
            }
        } else {
            score += 10.0;
        }
    } else {
        // last item: prefer tightest fit
        score -= 5.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate handling: only prefer fresh bin when no open bin fits well
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        // penalize opening a new bin mildly; more when many open bins are already loose
        score += 30.0 + 40.0 * (1.0 - pressure);
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits: must open new bin
        }
    }

    // Mean residual deviation: prefer bins near the mean residual (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Stream progression: late in stream, tighten packing (penalize waste more)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * progress;

    // Too many open bins: discourage spreading
    if open_bins_count > 8 {
        score += 0.3 * (open_bins_count as f64 - 8.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

