    // Lookahead: if the next item fits the post-residual, reward leaving that room.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // But penalize if post-residual is nonzero yet too small for the next item (dead space trap).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 20.0;
    }

    // Prefer bins tighter than the mean residual (good fits first).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.5;

    // Late-stream consolidation: favor filling existing bins as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
