}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit, but penalize very small dead space less than moderate dead space
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let tightness = pr / cap;
    score += 12.0 * tightness * tightness; // quadratic dead-space penalty

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            let gap = pr - ns;
            // perfect chain match strongly rewarded
            score -= 20.0 * (1.0 - gap / cap);
            if gap == 0.0 {
                score -= 15.0; // perfect two-item fill bonus
            }
        } else {
            // next item does NOT fit => dead space is likely wasted
            let overflow = ns - pr;
            score += 8.0 * (overflow / cap).min(1.0);
        }

        // reward if next item would fit better in this bin's post-residual
        // than in the mean residual of other bins
        if ns <= pr && ns > mean_residual {
            score -= 10.0; // this bin uniquely chains the next item
        }
    } else {
        // last item: minimize post residual aggressively
        score += 5.0 * tightness;
    }

    // Relative to mean residual: prefer bins tighter than average
    if mean_residual > 0.0 {
        score += 6.0 * (pr - mean_residual) / cap;
    }

    // Last-chance bin: strongly favor using it to avoid opening new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is terrible
    if bin_residual == bin_capacity {
        score += 30.0;
        // but if the item is huge and would leave a well-usable residual chain, soften
        if item_size as f64 / cap > 0.7 {
            score -= 12.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // must open new bin
        }
    }

    // Early stream: slightly prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0 * (open_bins_count as f64).ln().max(0.0) * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize dead space: small post-residuals are good, but a residual too small
    // for the smallest item (1) is perfect; mid-range leftovers are worst.
    let dead = post_residual as f64;
    score += 0.35 * (dead / 100.0) * (dead / 100.0) * 100.0;

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
