            score += 4.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    } else {
        // Last item: just minimize waste.
        score += dead;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate logic: an empty bin is a fallback; make it unattractive
    // unless existing bins would be badly fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // Open a new bin when open bins have little usable space on average.
        score = 60.0 - 40.0 * (1.0 - fragmentation) - 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // pairing large items into fresh bins can help
        }
    }

    // Mild global regularization: prefer spreading load when many bins are open.
    score += 0.02 * (open_bins_count as f64 - (bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post_norm = post / cap;

    // Base: prefer tight fills (small post_residual), with smooth non-linear shaping
    let mut score = post + 20.0 * post_norm * post_norm;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p = progress;
    score += 15.0 * (1.0 - p) * post_norm * (1.0 - post_norm); // early: tolerate mid residuals
    score -= 12.0 * p * (1.0 - post_norm) * (1.0 - post_norm); // late: reward fuller bins strongly

    // Dead-space penalty: residuals too small for typical items are wasted
    if post > 0.0 && post < 10.0 {
        score += 8.0 * (10.0 - post) / 10.0;
    }

    // Lookahead coupling: reward leaving room for the next item (smooth, non-linear)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let slack = post - nxt;
        if slack >= 0.0 {
            let fit = slack / cap;
            score -= 10.0 * fit * (1.0 - fit);
        } else {
            score += 4.0 * (-slack / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + p);
    }

    // Mild diversity pressure: avoid concentrating into already-tight bins when many bins open
    let mean_norm = mean_residual / cap;
    if post_norm < mean_norm {
        score += 5.0 * (mean_norm - post_norm) * (mean_norm - post_norm);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
