    score += 0.15 * progress * post_residual as f64;

    // Penalize very small unusable residuals (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary: reward tight fits strongly (nonlinear).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio).powi(3) * 40.0;

    // Perfect or near-perfect fill gets a big bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: penalize bins whose post-residual can't hold the next item
    // if the next item is small enough that wasting space matters.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) < nxt {
            // Dead space relative to next item's need.
            score += 0.5 * (nxt - post_residual as f64);
        } else {
            // Bin remains useful for the next item: reward.
            score -= 5.0;
        }
        // If next item fits perfectly in post residual, big reward.
        if post_residual as u32 == next_item_size {
            score -= 20.0;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins are fragmented or this is a poor fit everywhere.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin, decaying as stream progresses
        // and as the number of open bins grows (amortization effect).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_penalty = 60.0 - 30.0 * progress;
        // If many bins can fit the item, opening a new one is wasteful.
        new_bin_penalty += 8.0 * (fitting_bins_count as f64).min(6.0);
        // If mean residual is high (fragmented state), a fresh bin is more attractive.
        new_bin_penalty -= (mean_residual / bin_capacity as f64) * 20.0;
        // If this is the only fitting bin, never open a new bin.
        if fitting_bins_count == 1 {
            new_bin_penalty += 50.0;
        }
        score += new_bin_penalty.max(0.0);
    } else {
        // Mild reward for consolidating into existing bins, scaled by how
        // full the bin already is (prefer filling nearly-full bins).
        let used = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= used * 10.0;
    }

    // Global state coupling: when many bins are open, prefer placements that
    // reduce fragmentation (low post residual already does this); add a small
    // penalty proportional to open bins to discourage spreading.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    // Time-horizon term: early in the stream, be slightly more conservative
    // about tight fits (future items unknown); later, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0 * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    let poly = x * x * (1.0 - progress) + x * progress * (1.0 - x);
    let mut score = pr * (1.0 + 0.7 * poly);

    // Penalize waste relative to mean residual state.
    score += 0.3 * (pr - mean_residual) * (1.0 + progress);

    // Reward tight fits, more so late in the stream.
    score -= (1.0 - x) * (1.0 + 1.5 * progress) * 10.0;

    // Last-chance bin bonus: avoid opening new bins when this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 6.0 * progress;
    }

    // Lookahead: reward leaving space compatible with the next item.
    if next_item_size > 0 {
        let gap = (pr as u32).saturating_sub(next_item_size) as f64;
        let fit_next = if post_residual as u32 >= next_item_size { 1.0 } else { 0.0 };
        score += 0.25 * gap * (1.0 - x);
        score -= 4.0 * fit_next * (1.0 - x) * (1.0 - x);
    }

    // Mild penalty for many open bins, encouraging consolidation.
    score += 0.05 * open_bins_count as f64 * x;

    // New-bin candidate: prefer opening a new bin only for large items leaving bad residuals elsewhere.
    if bin_residual == bin_capacity {
        score = pr as f64 + 5.0 - 0.02 * item_size as f64;
        if fitting_bins_count == 1 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction band does the leftover fall in
    let pr = post_residual as u32;
    let class = pr / 10; // 0..=10 harmonic classes
    match class {
        0 => score -= 40.0,               // perfect fill
        1 => score -= 25.0,               // excellent
        2 => score -= 12.0,
        3 => score -= 4.0,
        4 | 5 => score += 6.0,            // awkward half-full leftover
        6 | 7 => score += 14.0,
        8 => score += 22.0,
        _ => score += 30.0,               // nearly empty -> wasted slot
    }

    // Modulo coupling: leftover that can host common small sizes (next item lookahead)
    if next_item_size > 0 && next_item_size <= pr {
        let fits_next = pr - next_item_size;
        score -= 8.0 + (fits_next as f64) * 0.15;
        // exact-fit chains reward
        if fits_next % 10 == 0 {
            score -= 6.0;
        }
    } else if next_item_size > 0 {
        // leftover cannot host next item: penalize more if next item is large (will need fresh bin anyway)
        score += (next_item_size as f64) * 0.08;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless current leftovers are truly bad
    if bin_residual == bin_capacity {
        score += 55.0;
        // but if no bin fits well, opening is fine: soften when mean residual is small
        if mean_residual < 15.0 {
            score -= 45.0;
        }
        // late in stream, prefer closing out open bins
        if next_item_size > 0 && next_item_size > mean_residual as u32 {
            score -= 20.0;
        }
    }

    // Dead-space penalty: residuals that no plausible item (1..=80) can use efficiently
    if pr > 0 && pr < 10 {
        score += 18.0; // tiny dead space
    }

    // Stream progression: early on, be conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    // Slight preference for tighter bins overall
    score += (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are unusable.
    let dead_threshold = 10.0_f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) < dead_threshold {
        // Dead space penalty: smaller dead gap is worse (wasted capacity).
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Penalize "awkward" gaps that only fit tiny items but not the typical item.
    if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
        score += post_residual as f64 * 2.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap <= 10 {
            score -= 30.0 - gap as f64;
        } else {
            score -= 5.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (the new-bin candidate has bin_residual == bin_capacity, so this penalty
    // naturally hits it when open_bins_count is high).
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 3.0 + 15.0;
        // But if existing bins would leave large dead space, new bin becomes attractive.
        if (post_residual as f64) < dead_threshold {
            score -= 40.0;
        }
    } else {
        // Mild bonus for consolidating into already-open bins.
        score -= 3.0;
    }

    // Late-stream tightening: as the stream progresses, prefer tighter fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * (0.5 + progress);

    // Deviation from mean residual: prefer bins already tighter than average.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: prefer tight fits (small post_residual)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 30.0; // perfect chaining
        } else if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize dead space proportionally
            score += 8.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    } else {
        // last item: minimize waste directly
        score += 5.0;
    }

    // Compare against mean residual: bins tighter than average are good targets
    score -= 3.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;

    // Last-chance bin: strongly favor using it to avoid opening a bin for one item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize leaving tiny unusable slivers unless next item can use them
    if post_residual > 0 && post_residual < 10 && post_residual != next_item_size {
        score += 6.0;
    }

    // New-bin candidate: only attractive when existing bins are very fragmented
    if bin_residual == bin_capacity {
        let fragmentation = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
        score += 20.0 - 10.0 * fragmentation.min(2.0);
        if fitting_bins_count == 0 {
            score -= 100.0; // must open new bin
        }
    }

    // Early stream: be slightly conservative, keep bins balanced
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strong bonus for very small post-residual.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 40.0 * tightness * tightness;
    }

    // Penalize dead space: residuals too small for any plausible future item.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 0.0;
    } else if post_residual < 10 {
        score += 12.0; // small unusable sliver
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot follow here; mild penalty proportional to leftover.
            score += 5.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Time horizon: early in the stream, be more open to new bins (long future
    // to exploit flexibility); late in the stream, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus a progress-dependent surcharge,
        // discounted when current bins are heavily fragmented.
        let mut new_bin_cost = 55.0 + 60.0 * progress;
        if mean_residual > 30.0 {
            new_bin_cost += (mean_residual - 30.0) * 0.3;
        }
        if open_bins_count > 0 && open_bins_count < 3 && progress < 0.3 {
            new_bin_cost -= 15.0; // early exploration of new bins is cheap
        }
        // If this item would leave a bad residual in every existing bin,
        // opening fresh is attractive; approximate via post_residual on empty bin.
        new_bin_cost += (bin_capacity - item_size) as f64 * 0.15;
        score = score.min(new_bin_cost);
        score = new_bin_cost;
    } else {
        // Existing bin: slight penalty when many bins are open and this is a loose fit.
        if post_residual > 40 {
            score += 8.0 * progress;
        }
        // Reward filling bins that are close to full (consolidation pressure).
        let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 15.0 * fill * progress;
    }

    // Global fragmentation coupling: many open bins with high mean residual
    // suggests poor packing; push toward using the emptiest-feeling bins.
    score += 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.35 * x * x);

    // Smooth polynomial coupling of post_residual with stream progress
    let p = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 12.0 * p * (pr * pr) / cap;

    // Penalize large dead space more as stream progresses (less time to reuse it)
    score += 8.0 * p * x * x * cap;

    // Reward tight fits: low post residual relative to item size
    let item = item_size as f64;
    score -= 6.0 * item / cap * (1.0 - x);

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * p;
    }

    // New-bin candidate: penalize slightly, unless open bins are very full on average
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 / (1.0 + mean_residual / cap);
        score += 20.0 - 10.0 * (crowded / (1.0 + crowded));
    }

    // Lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 4.0 * (nx - pr) / cap;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) heavily rewarded,
    // small dead space (1..=9) heavily penalized.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 9 {
        score += 40.0 - (post_residual as f64) * 3.0; // dead space penalty
    } else if post_residual <= 19 {
        score += 10.0;
    } else if post_residual >= 50 {
        score -= 15.0; // large residual still reusable
    }

    // Modulo-10 harmonic band: residuals divisible by 10 pair well with
    // typical item sizes; odd residuals are harder to fill.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 2 == 1 && post_residual < 50 {
        score += 4.0;
    }

    // Integer-division thresholds on next_item_size lookahead:
    // if next item fits the post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // extra reward if next item exactly fills remaining space
        if post_residual == next_item_size {
            score -= 30.0;
        }
        // next item leaves a class-0 residual too
        if (post_residual - next_item_size) % 10 == 0 {
            score -= 6.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // next item won't fit here; mildly penalize tiny residuals
        if post_residual < 20 {
            score += 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a bin unless the item is large
    // relative to capacity or current bins are nearly full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 - (item_size as f64 / bin_capacity as f64) * 60.0
            + mean_residual * 0.5 - progress * 10.0;
        // discourage new bin if many bins can fit the item
        score += (fitting_bins_count as f64) * 6.0;
    }

    // Prefer tighter bins overall: deviation from mean residual.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Late stream: consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it is too small for the smallest plausible item (<=10),
    // or too small for the lookahead item.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 120.0; // unusable sliver -> strong penalty
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0; // gap can't host the next item
        } else {
            // smooth dead-space pressure for medium gaps
            let gap_frac = post_residual as f64 / bin_capacity as f64;
            score += 15.0 * gap_frac * (1.0 - gap_frac) * 4.0;
        }
    } else {
        score -= 60.0; // perfect fill: strongly reward
    }

    // Reward tight fits: item filling most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // already-open bins rather than opening new ones.
    let bin_pressure = open_bins_count as f64 / (1.0 + total_items as f64 / 50.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open,
        // but allow it when the current bin would leave a bad gap.
        score += 30.0 + 20.0 * bin_pressure;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // pair fits perfectly in a fresh bin: soften the penalty
            score -= 20.0;
        }
    } else {
        score -= 8.0 * bin_pressure.min(3.0);
    }

    // Prefer bins below the mean residual (denser bins) slightly.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Late in the stream, prioritize exact packing over bin economy.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // can still host the next item (chained fit), penalize dead space otherwise.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain bonus: scaled by how snugly the next item fits too.
            let chain_tightness = (post_residual - next_item_size) as f64;
            score -= 45.0 - 0.25 * chain_tightness;
        } else {
            // Next item won't fit here: penalize proportionally to wasted potential.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.35 * waste.min(60.0);
        }
    } else {
        // Last item: prefer tightest possible packing.
        score += 0.0;
    }

    // Prefer filling bins whose residual is already below the mean (consolidate).
    if (bin_residual as f64) < mean_residual {
        score -= 0.30 * (mean_residual - bin_residual as f64).min(50.0);
    } else {
        score += 0.15 * ((bin_residual as f64) - mean_residual).min(50.0);
    }

    // Last-chance bin: if this is the only bin that can fit the item, use it
    // rather than opening a new bin (unless post_residual is tiny/dead).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize leaving very small unusable fragments (dead space < smallest item).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Mild pressure to close out bins early in the stream; explore new bins later.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress);

    // Slight penalty per crowded state to encourage spreading when many bins open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of the stream completed (dynamic time horizon).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit: strongly reward leaving (almost) no dead space.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual < 10 {
        // Unusable dead space below the minimum item size: penalize.
        score += 15.0;
    }

    // Reward tightness relative to the bin's current residual (relative fit quality).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio * fit_ratio;

    // Lookahead: reward if the next item can fit into the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        // Chain potential: stronger when the chain is snug.
        let chain_waste = (post_residual - next_item_size) as f64;
        score -= 18.0 - 0.3 * chain_waste.min(50.0);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual is dead space for the known next item: penalize mildly.
        score += 6.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Crowd pressure: with many open bins, prefer consolidating into existing ones.
    score += 0.15 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Global residual context: bins with residual far below the mean are
    // "scrap" bins; using them is good, filling roomy bins is less urgent.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.10 * dev;

    // Early in the stream, be slightly more willing to keep bins tight /
    // allow new bins for better long-term structure; late, pack aggressively.
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Default mild penalty so a decent existing fit beats opening a new bin,
        // but relax it when the existing fit is poor or no real alternative exists.
        let mut new_bin_penalty = 35.0;
        if fitting_bins_count == 0 {
            new_bin_penalty = -5.0; // no alternative: new bin is fine
        } else if fit_ratio < 0.35 && post_residual < 15 {
            new_bin_penalty = 5.0; // existing fit is excellent anyway
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // Opening a fresh bin lets the next item join cleanly.
            new_bin_penalty -= 8.0;
        }
        // Late in the stream, avoid scattering into new bins.
        new_bin_penalty += 20.0 * progress;
        score += new_bin_penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64 / bin_capacity as f64;
    let mut score = r;

    // Non-linear coupling: dead space penalty grows with stream progress
    let dead = r * r * (0.5 + progress);
    score += dead;

    // Reward tight fits via smooth cubic shaping of post_residual
    let tight = (1.0 - r).powi(3);
    score -= 1.5 * tight;

    // Interaction of post_residual with mean residual: prefer bins near the mean
    let dev = (post_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 0.4 * dev * dev;

    // Lookahead: penalize if next item cannot use the resulting residual
    if next_item_size > 0 {
        let usable = if (post_residual as f64) >= next_item_size as f64 { 1.0 } else { 0.0 };
        let gap = ((post_residual as f64) - next_item_size as f64).abs() / bin_capacity as f64;
        score -= 0.8 * usable * (1.0 - gap);
        score += 0.5 * (1.0 - usable) * r;
    }

    // Last-chance bonus: smooth reward when few fitting bins remain
    let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
    score -= 0.6 * scarcity;

    // Mild penalty for proliferating open bins, smoothed by progress
    score += 0.05 * (open_bins_count as f64).ln() * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: prefer residuals in "usable" classes
    // (multiples of 10 and small residuals that are likely dead space anyway).
    let post_class = post_residual % 10;
    // Penalize residuals that are awkward (1..9 mod 10 harder to fill with typical items)
    if post_class > 0 {
        score += 3.0 * (post_class as f64) / 10.0;
    }

    // Perfect fit reward: item exactly fills the bin
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tight fit reward: post_residual smaller than typical small item
    if post_residual < 10 {
        score -= 8.0;
    }

    // Harmonic pairing: does next item fit exactly into post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 25.0; // exact two-item completion
        } else {
            score -= 10.0 * (1.0 - slack as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 {
        // next item cannot follow into this bin: penalize proportionally
        score += 4.0;
    }

    // Integer-division threshold classes on post_residual
    let quarter = bin_capacity / 4;
    if post_residual >= 3 * quarter {
        score += 2.0; // very roomy leftover, fine but not urgent
    } else if post_residual >= quarter {
        score -= 2.0; // mid-range leftover is usable
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Prefer reusing open bins early; new bins more acceptable later
        score += 5.0 + 10.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
    }

    // Slight preference to balance residuals toward mean
    score += 0.05 * ((bin_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are unusable, penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 20.0;
    }

    // Reward perfect fills.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits relative to bin capacity.
    score -= (item_size as f64 / bin_capacity as f64) * 25.0;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> favor filling existing ones, penalize waste.
    score += (open_bins_count as f64) * 2.0;

    // Prefer bins below mean residual (filling emptier bins keeps tight ones flexible).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64) * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: exact match of post_residual with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // chain fit: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            // Slack that can still host the next item is partially acceptable;
            // reward proportionally to how tightly the next item will fit.
            let tightness = (next_item_size as f64) / (post_residual as f64);
            score -= 60.0 * tightness;
        } else {
            // Post-residual too small for the next item: dead space penalty,
            // worse when the leftover is tiny (highly unusable).
            let deadness = 1.0 - (post_residual as f64) / (next_item_size as f64);
            score += 40.0 * deadness;
        }
    } else {
        // Last item: only a perfect fit matters.
        if post_residual > 0 {
            score += 50.0;
        }
    }

    // Penalize leaving residual far below the mean (fragmented small gaps),
    // unless it is a perfect or chain fit.
    score += 0.5 * ((mean_residual - post_residual as f64).abs());

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate: default to expensive; only attractive when the item
    // is large relative to capacity (few open bins would leave good residuals).
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 1.5 - 0.5 * (item_size as f64);
        // If it is the only fitting option, opening a new bin is fine.
        if fitting_bins_count == 1 {
            score -= 200.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
    }

    // Mild preference for bins with larger residual among equals (better packing).
    score -= 0.1 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to hold typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 3.0;
        } else {
            // post_residual too small for next item: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // filling existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= 0.5 * mean_residual * (1.0 - progress);
        score -= open_bins_count as f64 * 0.3;
    } else {
        // New-bin candidate: make it attractive only when existing bins fit poorly.
        let poor_fit_penalty = if fitting_bins_count > 0 {
            (bin_capacity as f64 - item_size as f64) * 0.05
        } else {
            0.0
        };
        score += poor_fit_penalty;
        // Early in stream, opening new bins is cheap; later, expensive.
        score += 6.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 2.0;
        }
    }

    // Mild preference for bins whose residual is close to item size.
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += diff * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear (quadratic) penalty growth
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Stream-progress coupling: later in stream, penalize wasted residual more strongly
    score += 25.0 * progress * norm_pr * norm_pr * cap;

    // Smooth interaction with mean residual: avoid bins far from fleet mean
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 15.0 * dev * dev * cap * (0.5 + 0.5 * progress);

    // Dead-space avoidance: residual too small for the smallest plausible item (1..100 unknown, use item_size as proxy)
    let dead = (pr - next_item_size as f64).max(0.0) / cap;
    score += 30.0 * dead * dead * cap;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 20.0 + 30.0 * progress;
    }

    // Lookahead: reward if next item fits in post-residual (smooth reward)
    let fits_next = (next_item_size as f64 / cap).min(1.0);
    let usable = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
    score -= 12.0 * fits_next * usable * (1.0 - progress);

    // Mild penalty for many open bins to encourage consolidation
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residue modulo capacity fractions.
    // Small post_residual classes (1..=9) are near-perfect fits -> strong reward.
    let tiny_class = post_residual < 10;
    if tiny_class {
        score -= 60.0 - (post_residual as f64) * 4.0;
    }

    // Mid classes: leftover divisible by common item sizes is reusable.
    for d in [10u32, 20, 25, 50] {
        if post_residual % d == 0 && post_residual > 0 {
            score -= 12.0;
        }
    }

    // Penalize awkward residues (dead space) via modulo of capacity.
    if post_residual % 5 != 0 {
        score += 6.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this bin becomes a perfect pair -> big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits but leaves another residue: partial reward
        let nr = post_residual - next_item_size;
        if nr < 10 {
            score -= 25.0;
        } else if nr % 10 == 0 {
            score -= 10.0;
        }
    } else if next_item_size > post_residual && post_residual < 10 {
        // unusable sliver with no follow-up -> penalize mildly
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + (post_residual as f64) * 0.3;
    }

    // New-bin candidate: neutral-ish baseline, slightly penalized so we
    // only open fresh bins when no decent fit exists.
    if bin_residual == bin_capacity {
        score += 15.0 - (fitting_bins_count as f64) * 3.0;
        // late in stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Spread pressure: when many bins are open, favor tightening the tightest.
    if (post_residual as f64) < mean_residual {
        score -= 4.0;
    }

    // Integer-division threshold on post_residual: discourage leaving >half empty.
    if post_residual * 2 > bin_capacity {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps heavily.
    // Dead space = post_residual that is too small for typical future items.
    let min_item = 1u32;
    if post_residual < min_item.max(0) {
        score += 1000.0; // impossible gap (should not happen)
    }
    // Non-linear penalty for small-but-nonzero dead space: gaps below ~30
    // are unlikely to be filled by future items drawn from unknown distribution.
    let dead_threshold = 30.0;
    if (post_residual as f64) < dead_threshold {
        let dead = dead_threshold - post_residual as f64;
        score += 2.5 * dead * dead / dead_threshold; // quadratic dead-space penalty
    }

    // Reward tight fits (low post_residual) beyond the raw linear term.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // With many options, mild penalty to spread load toward best fits only.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Open bins pressure: discourage opening new bins when many are already open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize with open_bins_count pressure and progress.
        score += 25.0 + 10.0 * open_bins_count as f64 + 20.0 * progress;
        // But if no existing bin fits well, allow new bin: handled via fitting_bins_count
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    } else {
        // Existing bin: reward keeping bins closed.
        score -= 3.0 * open_bins_count as f64;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 30.0; // perfect chaining
        } else if (slack as f64) < dead_threshold {
            score -= 10.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here; leftover is likely dead space.
        score += 8.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins).
    score += 0.5 * ((post_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
