pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize large dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < 30 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            // Exact chaining bonus: item + next fills bin almost perfectly.
            let chain_waste = (bin_residual as i64 - item_size as i64 - next_item_size as i64).abs() as f64;
            score -= 12.0 * (1.0 - chain_waste / (bin_capacity as f64));
        } else {
            score += 6.0; // placement kills next item's fit here
        }
    }

    // New-bin candidate handling: make empty bins attractive only when fits are poor.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else {
            (fitting_bins_count as f64).recip()
        };
        // Base cost of opening a bin.
        score += 35.0;
        // Under time pressure early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // If many bins fit the item, discourage new bin.
        score += 12.0 * pressure.min(1.0);
        // If mean residual is high, open bins are underused -> prefer new bin less.
        score += (mean_residual / bin_capacity as f64) * 15.0;
    }

    // Prefer spreading load when many bins are open with high residuals.
    let spread = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 6.0 * spread;

    // Mild time-horizon scaling: later in stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (1.0 + progress) - pr_norm * progress * progress;
    score += 30.0 * poly;

    // Reward tight fits, more strongly later in the stream
    let tightness = 1.0 - pr_norm;
    score -= 25.0 * tightness * (0.5 + progress);

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0 + 20.0 * progress;
    }

    // Penalize opening new bins when many bins are open and mean residual is high
    let nb = (bin_residual as f64 - cap).abs() < 1e-9;
    if nb {
        score += 15.0 + 10.0 * (open_bins_count as f64).sqrt() + 5.0 * progress;
    }

    // Lookahead: favor bins whose post-residual can fit the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 {
        score += 8.0 * (next_item_size as f64 - pr).max(0.0) / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues mod 10 define "usable" classes.
    // Residuals that are multiples of 10 or small (<=10) pair well with future items.
    let pr = post_residual;
    let class = pr % 10;
    if pr == 0 {
        score -= 60.0; // perfect closure, best possible outcome
    } else if pr <= 10 {
        score -= 25.0; // dead space capped at 10, acceptable
    } else if class == 0 {
        score -= 15.0; // multiple-of-10 residual: highly reusable
    } else if class <= 5 {
        score += 3.0;  // mid-band residue slightly wasteful
    } else {
        score += 8.0;  // awkward residue class (6..9)
    }

    // Integer-division thresholds: how many 10-sized "units" fit in post residual.
    let units = pr / 10;
    if units >= 3 {
        score -= 8.0; // room for several future items
    } else if units == 0 && pr > 0 {
        score += 12.0; // tiny unusable sliver
    }

    // Lookahead coupling: does next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Harmonic match check: does post residual mod next item size leave a good class?
            let rem = pr % next_item_size;
            if rem == 0 {
                score -= 20.0; // exact future fit
            } else if rem <= 5 {
                score -= 6.0;
            } else {
                score -= 2.0;
            }
        } else {
            score += 6.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a neutral-ish baseline that
    // only wins when open bins would create bad dead space.
    if bin_residual == bin_capacity {
        // Penalize slightly so we prefer decent existing fits,
        // but the base post_residual (= capacity - item) keeps it competitive.
        score += 10.0;
        // Open new bin early in stream when few bins exist (cheap diversification).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if open_bins_count == 0 {
            score -= 100.0;
        } else if progress < 0.2 && post_residual < 30 {
            score -= 12.0;
        }
        // If next item is large and would not fit any post placement, new bin attractive.
        if next_item_size > 50 && post_residual < next_item_size as f64 as u32 {
            score -= 10.0;
        }
    }

    // Mean residual coupling: if this bin is far below mean residual, it is a
    // laggard bin; prefer filling it to consolidate.
    if (bin_residual as f64) < mean_residual - 10.0 {
        score -= 5.0;
    } else if (bin_residual as f64) > mean_residual + 10.0 {
        score += 5.0;
    }

    // Prefer tighter fits as stream progresses (less room for experimentation).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.3;

    // Mild penalty per open bin to discourage bin proliferation.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly reward zero waste.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residuals too small to hold even the smallest
    // plausible item are pure waste. Penalize them quadratically.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 200.0 * (min_item - post_residual) as f64;
    }

    // Unusable gap heuristic: small but nonzero gaps that cannot fit the
    // lookahead item are risky; penalize if next item could have used them.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 3.0 * (next_item_size - post_residual) as f64;
    }

    // Reward placements that leave room for the next item (flexibility).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 2.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins over opening new ones.
    score += 0.5 * open_bins_count as f64;

    // Mean residual coupling: if this bin is tighter than average, prefer it
    // (fills nearly-full bins first, keeps slack concentrated elsewhere).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Slight preference for using existing bins vs. the fresh empty-bin
    // candidate: an empty bin has full residual, so its raw score is high;
    // nudge it further up unless the fit is genuinely poor elsewhere.
    if bin_residual == bin_capacity {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly into the post-residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - gap / (bin_capacity as f64));
    }
    // Penalize if next item would be wasted by leaving a gap just below next_item_size.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Last-chance bonus: only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is very poor.
    if bin_residual == bin_capacity {
        let pressure = (post_residual as f64) / (bin_capacity as f64);
        score += 10.0 + 25.0 * pressure;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 8.0 * (1.0 - progress);
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    if open_bins_count > 3 {
        let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= 5.0 * fill;
    }

    // Nudge toward bins whose residual is near the mean residual (balanced packing).
    score += 0.05 * ((bin_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = item_size as f64 / cap;
    let norm_pr = pr / cap;
    let mut score = norm_pr;
    // smooth polynomial coupling of post_residual with progress
    score += 0.6 * norm_pr * norm_pr * (1.0 + progress);
    score -= 0.8 * fit * (1.0 - norm_pr) * (1.0 - progress);
    // lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let gap = norm_pr - nxt;
        if gap >= 0.0 {
            score -= 0.5 * gap * (1.0 - gap);
        } else {
            score += 0.4 * (-gap) * (-gap);
        }
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 0.7 * (1.0 - norm_pr);
    }
    // penalize deviation from mean residual (encourage balanced fills)
    score += 0.15 * (norm_pr - mean_residual / cap).abs();
    // late-stream: prefer tighter bins, discourage hoarding open bins
    score += 0.3 * progress * norm_pr;
    score += 0.02 * open_bins_count as f64 * progress;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: small post_residual classes are "perfect" fits.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class bonus: post_residual in {0,1..=5,6..=10} tiers
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    } else {
        // dead-space penalty grows super-linearly for large leftovers
        score += (pr * pr) / cap;
    }

    // Modulo arithmetic on post_residual: leftovers that are multiples of common
    // item sizes are more reusable later.
    let reusable = |r: u32| -> f64 {
        let mut bonus = 0.0;
        for m in [10u32, 20, 25, 50] {
            if m > 0 && r % m == 0 && r > 0 {
                bonus += 6.0;
            }
        }
        bonus
    };
    score -= reusable(post_residual);

    // Integer-division threshold: leftover large enough to hold next item is good
    if next_item_size > 0 && post_residual >= next_item_size {
        // reward proportionally to how well next item would nest
        let nest = (next_item_size as f64) / (post_residual as f64);
        score -= 12.0 * nest;
        // extra: exact match leaves another perfect class
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > 0 {
        // leftover too small for next item: penalize modulo-incompatible chunks
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when item is huge and
    // would leave a badly-shaped residue in any open bin.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / cap);
        let big_item = item_size as f64 >= 0.6 * cap;
        if big_item && fitting_bins_count > 0 {
            score += 20.0; // discourage new bin when some bin fits a big item
        } else if fitting_bins_count == 0 {
            score -= 40.0; // must open new bin
        } else if pressure < 1.0 && progress < 0.5 {
            score -= 5.0; // early stream: allow moderate bin creation
        }
    }

    // Mild tie-breaker: prefer bins with residual close to mean (balance classes)
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if post_residual <= 10 {
            // Gap too small for any item (min size 1..100 stream): pure dead space.
            score += (11.0 - pr) * 8.0;
        } else if post_residual <= 25 {
            // Small gap: only usable by small items; penalize moderately.
            score += (26.0 - pr) * 3.0;
        }
    } else {
        // Perfect closure of the bin — strongly reward.
        score -= 25.0;
    }

    // Reward tight fits: ratio of item to residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 12.0;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: with many open bins, discourage opening yet another.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; allow it only if
        // existing bins would leave nasty dead space (their scores already high).
        score += 20.0 + pressure;
    } else {
        // Mild reward for using existing bins, scaled by pressure.
        score -= 2.0 + pressure * 0.15;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // reward this placement strongly (chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 4.0;
        }
        // If next item cannot use the leftover gap, penalize big leftovers a bit more.
        if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
            score += 3.0;
        }
    }

    // Deviation from mean residual: prefer bins whose residual is close to the
    // item need (keeps residuals homogeneous and mergeable).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: if the next item can fill this bin's post-residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // perfect two-item closure
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how much would then remain
            let two_step_residual = post_residual - next_item_size;
            score -= 120.0 - (two_step_residual as f64) * 1.5;
        } else if next_item_size > post_residual {
            // next item cannot use the leftover; penalize dead space growth
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual is tighter than average
    // (keeps large cavities open for large future items).
    let residual_f = bin_residual as f64;
    if residual_f > mean_residual {
        score += (residual_f - mean_residual) * 0.8;
    } else {
        score -= (mean_residual - residual_f) * 0.3;
    }

    // Last-chance bin: if this is the only fitting bin, avoid wasting it on a bad fit
    // but still prefer it over opening a new bin when fit is decent.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: only open a new bin when the item fits very poorly
    // everywhere else (post_residual tiny leftover is good, large leftover is bad).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 90.0;
        // If item is large relative to capacity, a fresh bin is attractive.
        score -= (item_size as f64) * 0.6;
        // If the stream is near its end, opening a bin is less costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 30.0;
        // If many bins are open with large mean residual, prefer reusing them.
        score += (open_bins_count as f64).sqrt() * 8.0 + mean_residual * 0.4;
    }

    // Mild penalty when this bin would be left with a hard-to-fill sliver
    // (dead space between 16 and 40, the classic awkward zone).
    if post_residual >= 16 && post_residual <= 40 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score as post_residual shrinks (non-linearly).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead (k=2): if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let chain_quality = 1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        score -= 10.0 * chain_quality;
    } else if next_item_size > 0 && (next_item_size as f64) > post_residual as f64 {
        // Dead space: next item cannot use the leftover; penalize small unusable gaps.
        let waste = post_residual as f64 / next_item_size as f64;
        score += 6.0 * (1.0 - waste.min(1.0));
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Time horizon: early in the stream, keep bins flexible (favor larger post_residual slightly);
    // late in the stream, squeeze tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.15 * progress; // late-stage placements get relatively cheaper for tight bins

    // Global state coupling: many open bins with high mean residual -> encourage consolidation
    // into existing bins; penalize the new-bin candidate more when mean residual is large.
    let consolidation_pressure = (mean_residual / bin_capacity as f64) * (open_bins_count as f64).ln(1.0 + open_bins_count as f64).max(0.0);
    score += 4.0 * consolidation_pressure;

    // New-bin candidate handling: residual == capacity means a fresh empty bin.
    // Penalize opening a new bin unless the item is large and would leave a useful residual,
    // or no existing bin is a decent fit.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let large_item_bonus = (item_frac - 0.5).max(0.0) * 20.0; // big items justify fresh bins
        let poor_fit_pressure = if fitting_bins_count == 0 { 0.0 } else { 8.0 };
        score += 18.0 - large_item_bonus + poor_fit_pressure;
        // If the next item is huge, a fresh bin pairs well with it later.
        if next_item_size as f64 >= 0.6 * bin_capacity as f64 {
            score -= 6.0;
        }
    }

    // Small nudge toward bins whose residual exceeds the item by an "ideal" amount,
    // creating residual bands that future mid-size items can still use.
    let ideal = 30.0;
    let band_penalty = ((post_residual as f64 - ideal).abs()) / bin_capacity as f64;
    score += 3.0 * band_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on wasted space (dead space grows super-linearly)
    let mut score = norm_pr * norm_pr * cap;

    // Smooth cubic coupling with stream progress: later in the stream,
    // dead space is more costly (fewer chances to fill it).
    score *= 1.0 + 0.8 * progress * norm_pr;

    // Reward tight fits via smooth saturating term (post_residual near 0)
    let tightness = (-norm_pr * 6.0).exp();
    score -= 12.0 * tightness * (0.5 + progress);

    // Penalize bins whose residual deviates from the mean residual (smooth divergence term)
    let dev = (mean_residual - pr) / cap;
    score += 4.0 * dev * dev * cap;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead coupling: smooth interaction of post_residual with next item size
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        // If next item would fit exactly in post_residual, reward; smooth via quadratic gap
        let gap = (pr - ns) / cap;
        score += 6.0 * gap * gap - 5.0 * (-(gap.abs()) * 8.0).exp();
    }

    // Mild pressure to consolidate when many bins are open
    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr) * 2.0;

    // New-bin candidate: make empty bins moderately attractive only when
    // existing bins would leave large dead space (smooth threshold-free rule)
    if bin_residual == bin_capacity {
        score = cap * (0.35 + 0.4 * progress) - 8.0 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "useful"
    // denominators (multiples of common item sizes 10..80).
    let pr = post_residual as u32;
    let mut harmony = 0.0f64;
    for d in [10u32, 20, 25, 50, 100] {
        if pr % d == 0 {
            harmony += cap / d as f64; // finer denominators reward more
        }
    }
    score -= harmony * 0.8;

    // Penalize dead zones: residual in awkward bands (e.g. 1..10, 11..19, 21..24)
    let dead_penalty = if pr == 0 { 0.0 }
        else if pr < 10 { 40.0 }
        else if pr < 20 { 15.0 }
        else if pr < 25 { 10.0 }
        else if pr > 80 { 0.0 }
        else { 0.0 };
    score += dead_penalty;

    // Integer-division threshold: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_waste = post_residual - next_item_size;
        score -= 60.0 - (chain_waste as f64) * 1.5;
        // extra bonus if chain leaves a harmonic residual again
        if chain_waste % 10 == 0 { score -= 10.0; }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item can't chain here: mild penalty scaled by how badly it misses
        score += ((next_item_size - post_residual) as f64).min(30.0) * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: keep it neutral-ish, slightly penalized so
    // it only wins when open bins are truly bad fits.
    if bin_residual == bin_capacity {
        score += 12.0 + mean_residual * 0.15;
    }

    // Phase of stream: late in stream, be greedier about tight fits
    let phase = step_index as f64 / total_items.max(1) as f64;
    score -= phase * (post_residual as f64) * 0.3;

    // Prefer filling bins close to mean residual (balance pressure)
    score += ((post_residual as f64) - mean_residual).abs() * 0.1;

    // Coupling: exact fill bonus
    if post_residual == 0 { score -= 50.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fits the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but leaves further waste — mild reward scaled by slack.
            score -= 50.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use the leftover: penalize dead space more if large.
            let dead = (post_residual as f64) - (next_item_size as f64);
            score += 0.5 * dead;
        }
    }

    // Penalize small unusable residuals (dead space below minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Compare post residual against mean residual: leaving more than average waste is bad.
    score += 0.3 * ((post_residual as f64) - mean_residual).max(0.0);
    score -= 0.2 * (mean_residual - post_residual as f64).max(0.0);

    // New-bin candidate (empty bin): make it moderately attractive by default so it
    // wins only when open bins have bad fits; base new-bin score ~ capacity residual.
    if bin_residual == bin_capacity {
        // Slight bonus so a fresh bin beats a bin with terrible leftover, but not beats good fits.
        score -= 30.0;
        // Early in the stream, opening bins is cheap; later, prefer consolidation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 * progress;
        // If many bins are open, discourage spreading.
        score += 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual near zero).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Penalize creating small dead space that likely becomes unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0;
        }
        // Perfect two-item packing bonus.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // When many bins are open, prefer consolidating into the fullest bins.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += pressure * (bin_residual as f64 - mean_residual) * 0.4;

    // Prefer bins below mean residual slightly less (fill emptier bins when few are open).
    if open_bins_count <= 2 {
        score -= 5.0;
    }

    // Time horizon: early in stream, encourage opening new bins for good future flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, relax later; penalize more if a decent fit exists.
        let base = 10.0 + 40.0 * progress;
        score += base;
        if post_residual < 30 {
            score += 20.0; // an open bin already gives a tight fit
        }
    }

    // Late in the stream, be greedy: fill existing bins aggressively.
    if progress > 0.8 {
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post-residual, with a smooth non-linear penalty
    // that grows super-linearly for moderately large dead space.
    let mut score = post;
    score += 18.0 * norm_post * norm_post * (1.0 + 2.0 * progress);

    // Smooth interaction: how well the leftover matches the next item.
    // Reward when next_item_size fits into post_residual (chainability),
    // penalize when post_residual is just slightly too small (worst dead space).
    let next = next_item_size as f64;
    if next > 0.0 {
        let diff = (post - next) / cap;
        // smooth bump: positive when diff near 0 (perfect chaining)
        let bump = (-24.0 * diff * diff).exp();
        score -= 14.0 * bump * (0.5 + progress);
        // penalize near-miss: post slightly below next
        let miss = (diff + 0.06) * (diff + 0.06);
        if diff < 0.0 {
            score += 10.0 * miss * cap * (1.0 - progress);
        }
    }

    // Mean-residual coupling: placing into a bin far above the mean
    // residual preserves small residuals; smooth quadratic term.
    let dev = (post - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin, scaled smoothly by stream progress.
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.4 + 0.6 * progress);
    }

    // New-bin candidate (empty bin): penalize smoothly, more early in stream
    // when consolidation matters, less late when many bins are already open.
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64 / (1.0 + open_bins_count as f64);
        score += 30.0 * (1.0 - 0.5 * progress) * (1.0 - 0.3 * openness);
    }

    // Tight-fit reward: smooth function of fill ratio after placement.
    let fill = 1.0 - norm_post;
    score -= 10.0 * fill * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of common small item sizes) are rewarded.
    let post = post_residual;
    let cap = bin_capacity as f64;

    // Class A: post_residual divisible by 10/20/25 -> clean future fits
    if post > 0 {
        if post % 10 == 0 {
            score -= 6.0;
        }
        if post % 25 == 0 {
            score -= 4.0;
        }
        if post % 5 == 0 {
            score -= 2.0;
        }
        // Integer-division thresholds: leftover in [1,9] is near-dead space
        let dead_zone = post / 10; // 0 => tiny leftover
        if dead_zone == 0 {
            score += 10.0; // penalize unusable slivers
        } else if dead_zone == 1 {
            score += 3.0;
        }
        // Sweet spots: leftover 30-50 accommodates the mid item range
        if post >= 30 && post <= 50 {
            score -= 5.0;
        }
        // Perfect fit reward
        if post == 0 {
            score -= 20.0;
        }
    } else {
        score -= 20.0;
    }

    // Lookahead coupling: harmonic match between post_residual and next item
    if next_item_size > 0 && next_item_size <= post {
        let gap = post - next_item_size;
        // Reward if next item leaves a further clean residue
        if gap == 0 {
            score -= 12.0;
        } else if gap % 10 == 0 {
            score -= 7.0;
        } else if gap <= 5 {
            score += 4.0; // creates sliver after next item
        }
    } else if next_item_size > post {
        // next item won't fit here; leftover class matters more
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: make empty bin moderately attractive only
    // when current bins are congested (mean residual low relative to item)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let congestion = (item_size as f64) / (mean_residual.max(1.0));
        // Base new-bin score: slightly worse than a good fit, better than a bad one
        score = cap * 0.5 - 8.0 * congestion + 4.0 * progress;
        if fitting_bins_count == 0 {
            score -= 30.0; // must open a new bin
        }
    } else {
        // Mild penalty for spreading across many open bins
        score += (open_bins_count as f64) * 0.15;
        // Prefer bins tighter than the mean (better packing density)
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftovers are nearly unusable
    if post_residual > 0 {
        if post_residual <= 10 {
            // tiny gap: dead space, heavy penalty
            score += (11.0 - post_residual as f64) * 12.0;
        } else if post_residual < 20 {
            score += (20.0 - post_residual as f64) * 4.0;
        } else {
            // larger leftovers still useful: mild reward
            score -= (post_residual as f64 - 20.0).min(60.0) * 0.15;
        }
    } else {
        // perfect fill: strong reward
        score -= 40.0;
    }

    // Tight fit reward: fraction of bin consumed
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 15.0;

    // Open-bin pressure: discourage spreading across many bins
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // (avoid opening a new bin) unless fit is terrible
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post-residual exactly-ish, reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item won't fit here: leftover likely dead space
            score += (post_residual as f64) * 0.5;
        }
    }

    // Progression: as stream ends, slightly prefer compacting into open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // New-bin candidate: empty bin should only win when fits are bad.
    // Give it a moderate baseline so good fits in open bins beat it.
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    // Mean residual coupling: if open bins are generally full, opening new bins is fine
    score -= (mean_residual - 50.0).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer post_residual exactly matching next_item_size (perfect 2-step chain)
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score += diff * 0.8;
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize residuals too small for the next item (dead space)
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Reward tight fits relative to mean residual
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 10.0;

    // Penalize bins far from the mean residual (outliers create fragmentation)
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    // Last-chance bonus: if this is the only fitting bin, prefer using it over new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it unattractive unless nothing fits well
    if bin_residual == bin_capacity {
        score += 30.0;
        // Early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
        // If next item is huge, a fresh bin may be valuable
        if next_item_size >= 70 {
            score -= 10.0;
        }
    }

    // Mild penalty for many open bins to encourage consolidation
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post-residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 25.0;

    // Penalize dead space that cannot fit the next item.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        }
    } else {
        // Last item: strongly prefer filling an existing bin.
        score -= 30.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: make it unattractive unless residual is very fragmented globally.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // Open a new bin only late in stream when mean residual is small and many bins open.
        let open_new_bonus = 40.0 - fragmentation * 60.0 - progress * 15.0
            - (open_bins_count as f64 * 0.05);
        score += open_new_bonus.max(5.0);
    }

    // Prefer bins whose residual deviates below the mean (compact bins first).
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.15;

    // Mild preference for using bins with moderate residual (avoid hoarding large residuals).
    if bin_residual as f64 > mean_residual * 1.5 && bin_residual != bin_capacity {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Smooth polynomial base: reward small post_residual with non-linear decay
    let mut score = pr * (1.0 + 0.8 * fit_norm * fit_norm);

    // Stream-progress coupling: later in stream, tolerate residual more gently
    score *= 1.0 - 0.3 * progress * (1.0 - fit_norm);

    // Penalize dead space that cannot fit the next item (smooth quadratic)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = ((nxt - pr) / cap).max(0.0);
        score += 12.0 * gap * gap * (1.0 - progress);
        // Reward if next item fits exactly-ish
        let snug = (nxt - pr).abs() as f64 / cap;
        score -= 6.0 * (1.0 - snug) * (1.0 - snug) * fit_norm;
    }

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - fit_norm);
    }

    // Mean-residual divergence penalty: avoid leaving bin far from fleet mean
    score += 0.15 * (mean_residual - pr).abs();

    // Mild penalty for opening new bins when many open bins exist
    let new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    score += new_bin * (5.0 + 0.5 * open_bins_count as f64) * (1.0 - 0.5 * progress);

    // Item-size coupling: large items prefer tight fits (cubic interaction)
    let isz = item_size as f64 / cap;
    score -= 10.0 * isz * isz * isz * (1.0 - fit_norm) * (1.0 - fit_norm);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse capacity fractions (1/8 granularity)
    let item_class = item_size / 13;
    let next_class = next_item_size / 13;

    // Perfect-fit reward: post_residual in low harmonic classes is precious
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 150.0;
    }

    // Dead-space penalty: unusable residue (smaller than min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Modulo coupling: item class pairs that tile capacity well
    // (e.g. class 2 (~26) + class 4 (~52) ≈ 78, class 1 + class 5 ≈ 78...)
    let pair_sum = item_class + next_class;
    if next_item_size > 0 {
        if pair_sum == 6 || pair_sum == 7 {
            score -= 25.0; // complementary harmonic classes
        }
        // Next item fits exactly into post_residual -> strong reward
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            // Prefer leaving room for the next item
            score -= (post_residual - next_item_size) as f64 * 0.8;
        } else {
            // Next item won't fit here; penalize tight leftovers
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 120.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer tighter fits
        score += fitting_bins_count as f64 * 2.0;
    }

    // Integer-division thresholds on post_residual (harmonic bands)
    let band = post_residual / 25; // 0,1,2,3
    score += band as f64 * 6.0;

    // Prefer filling bins with small residuals relative to mean
    score += (mean_residual - post_residual as f64) * 0.5;

    // Late in the stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when current bin would be wasted
    if bin_residual == bin_capacity {
        // Opening new bin is penalized unless this bin leaves bad residue
        let bad_leftover = (post_residual > 0 && post_residual < 10)
            || (next_item_size > 0 && next_item_size > post_residual && post_residual > 0);
        if bad_leftover {
            score -= 60.0;
        } else {
            score += 30.0 + open_bins_count as f64 * 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fill is the ideal outcome.
        score -= 100.0;
    }

    // Tightness reward: fraction of the bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Penalize post_residuals that cannot fit the lookahead item but could otherwise
    // have been useful — encourages reserving space for known upcoming demand.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }
    // Reward leaving exactly enough room for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, using it avoids a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing space;
    // with few open bins, spreading items is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.8 * pressure * (0.5 + progress);

    // Prefer bins whose residual is below average (they are the cramped ones to fill first).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate: empty bin starts with a handicap so it only wins when all
    // open bins would create severe dead space.
    if bin_residual == bin_capacity {
        score += 45.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post_residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // 2-step lookahead: reward when next item exactly fills the post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0; // perfect chain: bin fully closed after next item
        } else if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            // prefer small gaps after the follow-up placement
            score -= 40.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            // next item cannot fit here: mild penalty proportional to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 0.15 * over;
        }
    } else {
        // last item: prefer minimal residual
        score -= 20.0 * tightness;
    }

    // Relative to mean residual: bins tighter than average are more valuable
    let rel = (bin_residual as f64) - mean_residual;
    score += 0.05 * rel;

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        let waste = post_residual as f64; // = capacity - item
        score += 45.0;
        score -= 0.3 * waste; // large items justify a fresh bin more
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0; // fresh bin can chain the next item too
        }
    }

    // Early in stream: slightly discourage proliferating bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 2 {
        score += (1.0 - progress) * 3.0 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: reward if the next item fits into the post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 4.0 * (next_item_size as f64 / 100.0);
    } else if next_item_size > 0 && post_residual > 0 {
        // Waste penalty if residual can't hold next item.
        score += 3.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's genuinely
    // better (e.g., many open bins with poor residuals, or perfect fit
    // potential). Base penalty scales with number of open bins.
    if bin_residual == bin_capacity {
        let mut penalty = 14.0 + 0.5 * open_bins_count as f64;
        // If existing bins fit poorly (high mean residual mismatch), soften.
        let mean_res_gap = (mean_residual - item_size as f64).abs();
        if mean_res_gap > 30.0 {
            penalty -= 8.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        penalty += 6.0 * progress;
        score += penalty;
    }

    // Mild preference for bins with residuals close to the item (exact-fit feel).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 5.0 * fit_ratio;

    // Slight global balance: prefer bins whose residual is above mean
    // (keeps spread of residuals even).
    score += 0.05 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let mut score = post_residual as f64;

    // Smooth polynomial coupling of post_residual with stream progress:
    // tight fits (small post_residual) are rewarded more strongly as the stream matures.
    let pr = post_residual as f64 / bin_capacity as f64;
    let coupling = pr * pr * (0.5 + 1.5 * progress) + pr * (1.0 - progress);
    score += 10.0 * coupling;

    // Reward near-exact fits with a smooth quadratic bonus.
    let fit_quality = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
    score -= (1.0 - fit_quality) * (1.0 - fit_quality) * (8.0 + 6.0 * progress);

    // Penalize leaving dead space that can't fit the next item (smooth interaction).
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).max(0.0) / bin_capacity as f64;
        score += gap * gap * 5.0;
        // Bonus when post_residual exactly accommodates the next item.
        let next_fit = 1.0 - ((post_residual as i64 - next_item_size as i64).unsigned_abs() as f64 / bin_capacity as f64);
        score -= next_fit * next_fit * 4.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0 + 4.0 * progress;
    }

    // Mild penalty for spreading across many open bins when mean residual is high.
    let spread = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.02 * spread;

    // New-bin candidate: prefer it only when it beats wasting residual space,
    // penalized slightly more as the stream progresses (consolidation pressure).
    if bin_residual == bin_capacity {
        score += 2.0 + 3.0 * progress * (1.0 - item_size as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues mod 10 and mod 25.
    let r10 = post_residual % 10;
    let r25 = post_residual % 25;

    // Penalize awkward residuals (dead space that is hard to fill later).
    // Residuals near multiples of 25 are "harmonic" with common item sizes.
    if r25 == 0 {
        score -= 12.0; // perfectly harmonic residual
    } else if r25 <= 5 || r25 >= 20 {
        score += 6.0;  // awkward sliver or near-full
    }

    if r10 == 0 {
        score -= 4.0;
    } else if r10 <= 3 {
        score += 3.0;
    }

    // Integer-division thresholds: small post_residual = tight fit (good).
    if post_residual <= 10 {
        score -= 20.0;
    } else if post_residual <= 20 {
        score -= 8.0;
    } else if post_residual > 60 {
        score += 10.0; // wasteful: item much smaller than residual
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let poor_fit = (bin_residual as f64 - item_size as f64) > 40.0
            && mean_residual > item_size as f64;
        if poor_fit || fitting_bins_count == 0 {
            score -= 15.0 + 10.0 * progress;
        } else {
            score += 30.0; // prefer existing bins when a decent fit exists
        }
    }

    // Lookahead coupling: if next item could exactly fill post_residual,
    // strongly favor this bin (harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual && post_residual - next_item_size <= 10 {
            score -= 12.0;
        } else if next_item_size > post_residual {
            score += 5.0; // next item won't fit here; residual likely dead
        }
    }

    // Crowding pressure: many open bins -> prefer tightening existing ones.
    if open_bins_count > 4 {
        score -= (open_bins_count.min(20) as f64) * 0.5;
    }

    // Mean residual alignment: bins close to the mean are "typical" targets.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A gap is "dead" if it is too small for the smallest plausible item (size 1..100),
    // but especially if it cannot even fit the lookahead item.
    if post_residual > 0 {
        if next_item_size > 0 && post_residual < next_item_size {
            score += 18.0; // cannot fit the next item -> likely dead space
        }
        // Non-linear penalty for very small gaps (classic dead zone < 15)
        if post_residual < 15 {
            score += (15.0 - post_residual as f64) * 2.5;
        } else if post_residual < 30 {
            score += (30.0 - post_residual as f64) * 0.6;
        }
    } else {
        // Perfect fit: reward strongly
        score -= 25.0;
    }

    // Reward when this bin is the last fitting option (avoid opening new bin needlessly)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than opening new bins (new bin gets residual = capacity, so add pressure).
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins and stream progress
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 6.0 + 2.0 * open_bins_count as f64 + 10.0 * progress;
        // But if no open bin can fit at all, allow new bin
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Slight preference for bins below mean residual (consolidate waste)
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Lookahead synergy: bonus if post_residual exactly accommodates next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        score -= (bin_capacity as f64 - leftover as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter residual is better (already in score).

    // Aggressive 2-step lookahead: reward when the NEXT item exactly fills
    // the post-residual (perfect 2-item packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // exact 2-step match: excellent
        } else if post_residual >= next_item_size {
            // next item fits but leaves leftover; mild bonus proportional to fit quality
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // dead space that next item cannot use: penalize dead space size
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize residuals that are hard to fill later (small odd leftovers)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Relative to mean residual: bins with more free space than average are
    // slightly preferred targets (keeps tight bins free for small items).
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate handling: empty bin should only win when the fit
    // would otherwise leave large dead space in existing bins.
    if bin_residual == bin_capacity {
        // neutral baseline; slight penalty so good existing fits win,
        // but not so large that it never opens when fits are poor.
        score += 6.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 5.0; // discourage opening bins for mediocre 2-step fits
        }
    }

    // Late in the stream, consolidation matters more: prefer filling bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: waste below a threshold is heavily discounted.
    if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves slack; scale bonus by how snug.
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use this bin's remainder: mild penalty for
            // stranding residual that could have hosted it.
            let stranded = (next_item_size - post_residual) as f64;
            score += 3.0 * (stranded / 100.0).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a fresh bin opening.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize fragmenting a large residual when the bin is relatively empty
    // (better to fill nearly-full bins first, keep large-capacity bins flexible).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    if fill_ratio < 0.3 && post_residual > 30 {
        score += 6.0;
    }

    // Time-horizon term: early in the stream, be conservative with new bins;
    // late in the stream, tightness dominates anyway so relax fragmentation penalty.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (mean_residual / bin_capacity as f64);

    // Many open bins: prefer consolidating into existing ones over opening new.
    if bin_residual == bin_capacity {
        // Brand-new-bin candidate: only attractive when existing bins fit poorly
        // or the item is huge relative to mean residual.
        score += 10.0 + 3.0 * open_bins_count as f64;
        if item_size as f64 > mean_residual + 20.0 {
            score -= 12.0;
        }
    } else {
        // Slight bonus for using an existing bin when many are open.
        score -= 1.0 * (open_bins_count.min(20) as f64) / 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap;
    let poly = prn * prn * (1.0 - prn) * (2.0 - progress);
    score -= 30.0 * poly;

    // Penalize large post-residual more as stream progresses (dead space matters late)
    score += progress * 10.0 * prn * prn;

    // Reward tight fits: small post_residual relative to capacity
    score -= (1.0 - prn) * (1.0 - prn) * (item_size as f64 / cap) * 8.0;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 12.0;
    } else if next_item_size > 0 {
        score += 4.0;
    }

    // Prefer fuller bins relative to mean residual of open bins
    score += (mean_residual - pr) * 0.5;

    // Mild penalty for many open bins (encourage consolidation)
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
