pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10, or gaps that no
    // plausibly arriving item can use) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // A perfect fit (post_residual == 0) is maximally rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Gaps too small for the lookahead item are wasteful if the next item
    // could otherwise have used this bin; penalize mildly.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Reward gaps that can still accommodate the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Open-bins pressure: penalize spreading across many bins when residuals
    // are already fragmented; encourage consolidation into existing bins.
    score += (open_bins_count as f64) * 0.9;

    // If this bin is the last chance to fit (only one fitting bin), strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // When mean residual is low (bins are nearly full), prefer tight fits;
    // when mean residual is high, tolerate larger leftovers.
    score -= 0.15 * mean_residual;

    // Slight preference for reusing existing bins vs. the fresh empty bin:
    // an empty bin has bin_residual == bin_capacity, so its post_residual is
    // naturally large; add a small extra penalty to opening new bins unless
    // dead-space avoidance says otherwise.
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    // Late in the stream, tighten up: less tolerance for leftover space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills this bin afterwards.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect lookahead match: strong bonus (subtract).
        if gap == 0.0 {
            score -= 60.0;
        } else {
            // Penalize mismatch proportional to gap, scaled by how large next item is.
            score += gap * (0.4 + next_item_size as f64 / 200.0);
        }
        // If next item cannot fit here at all after placement, mild penalty.
        if next_item_size as u32 > post_residual {
            score += 15.0;
        }
    } else {
        // Last item: prefer tightest fit only.
        score += 0.0;
    }

    // Tightness reward: smaller post_residual relative to capacity is better.
    score -= (bin_capacity - post_residual) as f64 * 0.15;

    // Penalize creating tiny unusable dead space (1..=5) that likely wastes the bin.
    if post_residual > 0 && post_residual < 6 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, favor it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are all poor.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - post_residual as f64;
        // If mean residual of open bins is large, opening new bin is wasteful.
        score += 40.0 + mean_gap.max(0.0) * 0.5;
        // Early in stream, keep fewer bins; later, allow spreading.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 20.0;
        // If many open bins and mean residual small, new bin more acceptable.
        if mean_residual < 15.0 && open_bins_count > 2 {
            score -= 30.0;
        }
    }

    // Mild penalty for bins far below mean residual (fragmentation avoidance).
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += dev * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 30.0 * tightness;

    // Penalize dead space below typical small-item threshold.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item won't fit here; slight penalty proportional to wasted potential.
            score += 3.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    } else {
        // Last item: prefer minimal leftover.
        score += 0.0;
    }

    // Prefer bins whose residual is below the mean (consolidate space).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Time horizon: early in stream, be more willing to open new bins (penalize using tight open bins less);
    // late in stream, consolidate to avoid opening bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: cheaper early, expensive late.
        score += 15.0 * progress;
        // Discourage new bins when many bins already open.
        score += 1.5 * open_bins_count as f64;
    } else {
        score -= 5.0 * progress;
    }

    // Mild penalty for very low fill (wasteful placement into a large-residual bin).
    if tightness < 0.5 {
        score += 6.0 * (0.5 - tightness);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap;

    // Base: prefer small post_residual, with smooth polynomial shaping
    let mut score = post * (1.0 + 2.0 * x * x);

    // Tightness reward: near-perfect fits get strong smooth bonus
    let tight = (1.0 - x).powi(3);
    score -= 60.0 * tight * (0.5 + progress);

    // Progress coupling: late in stream, penalize slack more aggressively
    score += 40.0 * progress * x * (1.0 - x);

    // Dead-space penalty: residuals too small to matter are dead space
    let dead = (x * (1.0 - x)).powi(2);
    score += 30.0 * dead;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - x);
    }

    // Lookahead: favor bins whose post_residual still fits the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 12.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 15.0 * (nxt - post) / cap;
        }
    }

    // Mean-residual coupling: avoid bins far from the fleet mean (fragmentation)
    score += 8.0 * ((post - mean_residual) / cap).abs();

    // New-bin candidate: mild penalty so we prefer existing bins unless they're poor
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "small" classes are dead space; heavily penalize them.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Dead-space penalty grows super-linearly once residual < ~20% capacity.
    if frac < 0.2 {
        score += (0.2 - frac) * 90.0;
    } else {
        score -= (frac - 0.2) * 15.0; // reward leaving usable space
    }

    // Modulo-10 harmonic class: residuals that are multiples of 10 pair well
    // with the known size granularity; reward them slightly.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this is a perfect harmonic pair — reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let nf = (post_residual - next_item_size) as f64 / cap;
            score -= (1.0 - nf) * 12.0; // tighter next-fit leftover is better
        } else {
            // next item cannot use this residual at all: penalize proportionally
            score += (next_item_size as f64 - pr) * 0.25;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless residual becomes tiny).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if frac < 0.1 {
            score += 20.0; // but not if it creates near-zero waste anyway
        }
    }

    // New-bin candidate: neutral baseline, slightly above a decent fit so we
    // only open new bins when existing fits are poor.
    if bin_residual == bin_capacity {
        score = cap * 0.55;
        if fitting_bins_count == 0 {
            score -= 30.0; // nothing fits elsewhere: must open
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // big pair coming, fresh bin is fine
        }
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - pr).max(0.0) * 0.3;
    score += progress * 3.0 * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer bins that end up with small (but usable) residual => lower post_residual is good.
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to hold even the
    // smallest plausible future item (<= 12) are effectively dead space. Penalize hard.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0 - (post_residual as f64) * 4.0; // dead-space penalty, worst at post_residual == 1
    }

    // Perfect fit reward: strongly favor bins whose residual is exactly consumed.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward placements that leave room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin can also host the next item: chain placement is valuable.
            score -= 8.0 + (next_item_size as f64) * 0.1;
        } else if post_residual > 0 && post_residual < next_item_size {
            // The leftover gap is smaller than the next item: likely dead space.
            score += 10.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits the item, using it
    // avoids opening a new bin — reward it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer tight packing
    // into existing bins so we do not accumulate many half-empty bins.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    score += open_pressure;

    // New-bin candidate handling: an empty bin (residual == capacity) should only win
    // when no open bin offers a decent fit. Make the empty bin less attractive by default.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, growing with how many bins are already open.
        score += 45.0 + open_bins_count as f64 * 2.0;
        // But if the current item is huge relative to typical residual, opening fresh
        // may be the right call: soften the penalty a bit for large items.
        if item_size >= 60 {
            score -= 20.0;
        }
        // If the mean residual across open bins is small (open bins are nearly full),
        // a new bin is more justified.
        if mean_residual < item_size as f64 {
            score -= 30.0;
        }
    } else {
        // Real bins: compare residual against the mean residual. Bins tighter than the
        // mean are better targets (first-fit-decreasing-like behavior).
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    // Mild progression coupling: later in the stream, pack more aggressively
    // (slightly favor existing bins over residual size).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching:
    // reward bins whose post-residual closely matches the next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / (bin_capacity as f64));

        // Perfect 2-step match: post_residual == next_item_size -> huge reward.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Next item fits with small slack -> mild extra reward.
        else if post_residual >= next_item_size && post_residual - next_item_size <= 5 {
            score -= 12.0;
        }
        // Next item would NOT fit in this bin's post-residual -> penalize
        // leaving a bin that strands the lookahead item (dead space).
        if post_residual < next_item_size && post_residual > 0 {
            let waste_ratio = post_residual as f64 / bin_capacity as f64;
            score += 30.0 * waste_ratio;
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin (only fitting bin): strongly favor using it to avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize opening a new bin when a reasonably tight fit exists elsewhere.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost + penalty scaled by how full existing
        // bins are on average (wasteful to open new bins when residuals are small).
        score += 15.0 + 0.3 * (mean_residual as f64).max(0.0);
        // But if no open bin fits (this call is the only one), the new bin is
        // the natural choice; soften the penalty.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Lookahead-aware new-bin bonus: if next item is large, opening a fresh
        // bin now keeps flexibility.
        if next_item_size > 50 {
            score -= 10.0;
        }
    }

    // Late in the stream, consolidate: prefer tighter fills to close bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Slight preference for bins among many open bins (encourage consolidation).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize high fill ratio less.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fill * fill;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual < 10 {
        score -= 25.0; // perfect-ish fit, great
    } else if post_residual <= 20 {
        score += 6.0;
    } else if post_residual < 35 {
        score += 14.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 18.0;
        } else if (bin_residual as u32) >= item_size + next_item_size {
            score -= 8.0;
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    score += 0.6 * open_bins_count as f64;

    // Mean residual coupling: if this bin is below mean residual (fuller), favor it.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Time horizon: early in stream, be pickier about wasting space; late, just fit.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.25 * progress;

    // New-bin candidate: make it moderately unattractive unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 40.0 + 8.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (0.5 + progress);
    score += poly * cap * 0.3;

    // Reward tight fits (small post_residual) more strongly late in the stream
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (10.0 + 40.0 * progress);

    // Penalize dead space that no plausible future item can use
    if next_item_size > 0 && (next_item_size as f64) > pr {
        score += (next_item_size as f64 - pr) * (0.5 + progress);
    }

    // Lookahead synergy: if next item fits the post_residual, reward this bin
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 + 12.0 * (1.0 - (pr - next_item_size as f64) / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 25.0 * progress;
    }

    // Prefer bins with below-mean residual when many bins are open (balance)
    score += (mean_residual - pr) * 0.15 * (open_bins_count as f64).ln().max(1.0);

    // Mild preference for keeping fewer open bins early on
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    // New-bin candidate: penalize slightly so it only wins when fits are bad
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress + 0.5 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into
    // "dead" classes (small, unusable slivers) are penalized.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is excellent
    } else {
        // dead-space penalty grows as residual becomes unusable
        // (too small for the smallest plausible item)
        if pr < 10 {
            score += 25.0; // tiny sliver: wasted space
        }
        // modulo classes: residuals divisible by 10 tend to combine
        // with items of sizes 10..80 more often
        if pr % 10 == 0 {
            score -= 12.0;
        } else if pr % 5 == 0 {
            score -= 6.0;
        }
        // integer division thresholds: coarse residual buckets
        let bucket = pr / 20; // 0..5
        score -= bucket as f64 * 4.0;
    }

    // Harmonic coupling with the lookahead item (k=2).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // exact match for the next item
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score -= 15.0; // near-exact chain fit
        } else if post_residual < next_item_size {
            score += 8.0; // cannot host next item
        }
        // parity harmony between item and next item
        if (item_size + next_item_size) % 2 == 0 {
            score -= 2.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when open bins
    // are very crowded or the fit is terrible.
    if bin_residual == bin_capacity {
        // neutral base for new bin; make it attractive only if residuals are low
        score -= 10.0 * (1.0 - mean_residual / bin_capacity as f64);
        score += 20.0; // default bias against opening new bins
    }

    // Stream progression: early on, be slightly more willing to keep bins tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Penalize bins far below the mean residual (fragmented outliers).
    score += ((mean_residual - bin_residual as f64) * 0.05).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size are pure waste.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 1000.0;
    }
    // Small gaps that no realistic item can use (below typical smallest size ~10)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        // mildly unusable zone
        score += 15.0;
    }

    // Tight fit reward: near-zero post residual is excellent.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open-bin pressure: penalize placements that encourage opening many bins;
    // prefer filling already-open bins when open_bins_count is high.
    let obp = open_bins_count as f64;
    score += obp * 0.8;

    // Mean residual coupling: when mean residual is high, prefer bins that
    // absorb more space (lower post_residual already does this); add small tilt
    // toward bins below mean residual (they need filling more).
    if (bin_residual as f64) > mean_residual {
        score += 3.0;
    } else {
        score -= 3.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 80.0;
        } else if slack < 10 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here anyway; slight penalty for leaving mid-size gap
        if post_residual >= 10 {
            score += 5.0;
        }
    }

    // New-bin candidate handling: only open a new bin when the item is large
    // (would leave a big hole in an existing bin) or no bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = item_size > 60;
        if large_item || fitting_bins_count == 0 {
            score -= 25.0 + 20.0 * progress;
        } else {
            score += 30.0 + obp * 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (superlinear penalty on wasted space).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward when post_residual matches next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff <= 5.0 {
            // Perfect chain: post_residual exactly fits the next item.
            score -= 30.0 * (1.0 - diff / 6.0);
        } else if post_residual >= next_item_size {
            // Next item still fits here: mild reward proportional to closeness.
            score -= 8.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item would NOT fit after this placement: penalize dead space.
            score += 10.0 + 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // Last item: prefer minimal post_residual.
        score -= 15.0 * tightness;
    }

    // Relative-to-mean coupling: bins tighter than average are better targets.
    score += 0.4 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize opening a new bin unless current bins are nearly full or none fit well.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let avg_waste = if open_bins_count > 0 { mean_residual } else { bin_capacity as f64 };
        // New bin is attractive only if existing bins are very tight on average,
        // or the item is large and would leave a big awkward gap elsewhere.
        let new_bin_bonus = if avg_waste < 15.0 {
            20.0
        } else if item_size >= 60 {
            8.0 * progress
        } else {
            -5.0
        };
        score += 10.0 - new_bin_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: perfect packing gets a big discount.
    if post_residual == 0 {
        score -= cap * 2.0;
    } else {
        // Penalize dead space that is too small to hold any plausible item.
        let dead_threshold = 10.0_f64.min(cap * 0.15);
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Prefer fuller bins when multiple candidates exist (best-fit flavor).
        score += (bin_residual as f64 - post_residual as f64).recip() * 10.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // reward heavily; if it would be blocked, penalize moderately.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (next_item_size as u32) <= post_residual {
            let chain_fit = 1.0 - ((post_residual as f64 - next) / cap).abs();
            score -= chain_fit * 15.0;
        } else {
            score += 5.0 + next * 0.1;
        }
    }

    // Global state: if open bins are collectively empty-ish, discourage new bins.
    let mean_fill = 1.0 - (mean_residual / cap);
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let horizon_pressure = (1.0 - progress) * (open_bins_count as f64).ln();

    // Encourage consolidation when many bins are open and mean residual is low.
    score -= mean_fill * 8.0 - horizon_pressure * 0.5;

    // New-bin candidate handling: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowd = (open_bins_count as f64) * (1.0 - mean_fill);
        score += 20.0 - crowd.min(18.0) - progress * 5.0;
    }

    // Mild best-fit bias toward smaller post residuals overall.
    score += (post_residual as f64 / cap) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
