        } else if next_item_size <= post_residual {
            // next fits but leaves another residual: mild reward scaled by class
            score -= 5.0 + (class as f64) * 0.5;
        } else {
            // next item cannot use this leftover: penalize large dead space
            score += post * 0.05;
        }
        // Harmonic pairing: next_item_size divides capacity into nice chunks
        let next_class = next_item_size / (bin_capacity / 10).max(1);
        if next_class >= 4 && post_residual >= next_item_size {
            score -= 3.0; // big-next-item synergy
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are
    // nearly full on average (mean_residual low) or the fit is terrible.
    if bin_residual == bin_capacity {
        score += 15.0;
        if mean_residual < 12.0 {
            score -= 10.0; // open bins nearly saturated, new bin reasonable
        }
        if post_residual == bin_capacity && next_item_size > 0 && next_item_size > bin_capacity / 2 {
            score -= 12.0; // big next item, keep a fresh bin
        }
    }

    // Prefer bins with residual close to item size (tight fit) via ratio term.
    let tightness = (bin_residual as f64 - item_size as f64) / cap_f;
    score += tightness * 10.0;

    // Slight preference for fuller bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - bin_residual as f64 / cap_f) * progress * 5.0;

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect chain (post_residual == next_item_size) is ideal.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64 - next).abs() < 0.5 {
            // Perfect match: next item exactly fills this bin.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits here; reward tight leftover after that.
            let chained = post_residual - next_item_size;
            score -= 25.0 - 0.4 * chained as f64;
        } else {
            // Next item won't fit: penalize proportional to how much wasted potential.
            score += 10.0 + 0.3 * (next - post_residual as f64);
        }
    } else {
        // Last item: prefer minimal leftover.
        score += 0.0;
    }

    // Dead-space penalty: small but nonzero post_residual is hard to use later.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Compare against mean residual: prefer bins that are already tight (below mean residual).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    // (many fitting bins or a tight fit elsewhere should suppress new bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base cost of a fresh bin, softened late in the stream or when
        // the item fits very few bins.
        let mut new_bin_cost = 55.0;
        if fitting_bins_count <= 1 {
            new_bin_cost -= 30.0;
        }
        if next_item_size > 0 && next_item_size as f64 > item_size as f64 {
            // Big next item: a fresh bin is more valuable for the lookahead.
            new_bin_cost -= 15.0;
        }
        new_bin_cost -= 10.0 * progress;
        score += new_bin_cost.max(5.0);
    }

    // Mild tie-break: prefer fuller bins (smaller residual) overall.
    score += 0.1 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) more strongly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that no future item can plausibly use.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0; // unusable sliver
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            // bonus if next item fits snugly too
            let r = next_item_size as f64 / post_residual as f64;
            score -= 8.0 * r * r;
        } else {
            score += 4.0; // chain broken
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Crowding pressure: many open bins -> prefer consolidating into tight fits.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.05 * pressure * (post_residual as f64);

    // Time horizon: early in stream, keep bins flexible (avoid tiny residuals);
    // late in stream, prioritize filling bins aggressively.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - t) * 0.15 * post_residual as f64;
    score -= t * 0.10 * fit_ratio * 10.0;

    // New-bin candidate: only attractive when current bin would leave a bad
    // residual or when the fit is poor; an empty bin has full flexibility.
    if bin_residual == bin_capacity {
        let poor_fit_penalty = (bin_capacity as f64 - item_size as f64) * 0.10;
        let urgency = if fitting_bins_count <= 1 { 8.0 } else { 0.0 };
        score = 30.0 + poor_fit_penalty + urgency - t * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Base: prefer small post-residual, with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.5 * x * x);

    // Polynomial coupling of post-residual with stream progress:
    // early on tolerate slack; late in stream penalize dead space more strongly
    let prog_coupling = x.powi(2) * (1.0 + 3.0 * progress * progress) + x.powi(3) * progress;
    score += 30.0 * prog_coupling;

    // Reward tight fits smoothly: item nearly filling bin
    let fit_ratio = item_size as f64 / cap;
    score -= 15.0 * fit_ratio * fit_ratio * (1.0 - x);

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - x);
    }

    // Lookahead: reward leaving room for next item (smooth kernel)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            let slack = (pr - n) / cap;
            score -= 20.0 * (-((slack - 0.2).powi(2)) * 8.0).exp();
        } else {
            score += 10.0 * ((n - pr) / cap);
        }
    }

    // Mild penalty for spreading across many open bins
    score += 0.3 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins near the mean (smooth quadratic)
    score += 0.05 * (pr - mean_residual).powi(2) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bins whose post_residual lies in
    // "usable" residue classes (multiples of small divisors) are more likely
    // to be filled by future items, so reward them.
    let pr = post_residual;
    if pr > 0 {
        // Perfect fit: ideal.
        if pr == 0 {
            score -= 1000.0;
        } else {
            // Reward leftovers that are highly divisible (harmonic classes).
            let mut harmony = 0.0;
            if pr % 2 == 0 { harmony += 2.0; }
            if pr % 4 == 0 { harmony += 2.0; }
            if pr % 5 == 0 { harmony += 2.0; }
            if pr % 10 == 0 { harmony += 3.0; }
            if pr % 20 == 0 { harmony += 3.0; }
            if pr % 25 == 0 { harmony += 2.0; }
            if pr % 50 == 0 { harmony += 4.0; }
            score -= harmony;

            // Penalize dead space: leftovers too small for the smallest items
            // (1..=10 range) are pure waste, but small leftovers in classes
            // matching next_item_size can still be useful.
            if pr < 10 {
                score += (10 - pr) as f64 * 1.5;
            }

            // Lookahead coupling: if the next item exactly fits the leftover,
            // strongly reward; if next item leaves a harmonic remainder, mildly reward.
            if next_item_size > 0 {
                if next_item_size == pr {
                    score -= 60.0;
                } else if next_item_size < pr {
                    let nr = pr - next_item_size;
                    if nr % 10 == 0 { score -= 8.0; }
                    if nr % 5 == 0 { score -= 4.0; }
                    if nr < 10 { score += 5.0; }
                } else {
                    // Next item cannot follow in this bin; slight penalty if
                    // this placement was the only option anyway.
                    if fitting_bins_count == 1 {
                        score -= 20.0; // last chance: still prefer using it
                    } else {
                        score += 10.0;
                    }
                }
            }

            // Integer-division thresholds on post_residual: classify leftover
            // size into coarse bands; mid-size leftovers are most reusable.
            let band = pr / 10; // 0..10
            match band {
                0 => score += 6.0,           // tiny scraps: near-waste
                1 => score -= 1.0,
                2 => score -= 4.0,
                3 => score -= 5.0,           // sweet spot ~30-39
                4 => score -= 5.0,
                5 => score -= 3.0,
                6 => score -= 1.0,
                7 | 8 => score += 2.0,       // large leftover: bin still flexible
                _ => score += 0.0,
            }
        }
    }

    // Tie-break with global state: prefer tighter-than-average bins.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Late in the stream, consolidate: discourage opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open-bin count and progress.
        score += 15.0 + 5.0 * progress + (open_bins_count as f64).sqrt() * 2.0;
        // But if no open bin fits well, allow opening (handled by relative score).
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else if fitting_bins_count == 1 {
        // This is the only bin that fits: strong reward to avoid a new bin.
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (min item size 1..100, but typical small items ~10)
    // are unusable dead space. Penalize hard when post_residual is a
    // tiny unusable gap.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward perfect / near-perfect fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward residual that exactly matches the lookahead item (k=2).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 8.0;
    }
    // Penalize when post_residual cannot hold the lookahead item but is close.
    if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Open-bin pressure: discourage spreading across many open bins
    // when the fit is mediocre; encourage using existing bins when
    // few are open (avoid opening bins unnecessarily).
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let bin_pressure = (open_bins_count as f64).powf(0.5) * (1.0 + progress);
    score += bin_pressure * 0.15;

    // Last-chance bonus: if this is the only bin that fits, strongly
    // prefer it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 30.0;
        if post_residual < 10 {
            score += 35.0; // but not if it creates dead space
        }
    }

    // New-bin candidate handling: an empty bin has huge residual.
    // Make it less attractive than a decent fit in an existing bin,
    // but attractive when all existing fits create dead space.
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin
        score += 55.0;
        // early in the stream, opening bins is cheaper (more items to come
        // can fill them); late in the stream, prefer consolidation.
        score -= 45.0 * (1.0 - progress);
        // if many bins already open, opening another is expensive
        score += (open_bins_count as f64) * 2.0;
    }

    // Deviation from mean residual: prefer bins whose residual is
    // large (bigger residual = more room left, less fragmentation risk)
    // relative to the fleet average.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.05 * dev;

    // Tightness reward: fraction of the bin that the item fills.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward (subtract heavily).
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward when post_residual matches next item size.
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        // Exact match with next item: excellent chain placement.
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual > next_item_size {
            // Next item fits here afterwards: mild reward proportional to closeness.
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Dead space relative to next item: penalize.
            score += 25.0 * (gap / bin_capacity as f64);
        }
    }

    // Coupling with mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Penalize new-bin candidate unless residuals of open bins are all tiny.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 2.0;
        // If item is large relative to capacity, opening fresh bin is more attractive.
        score -= item_size as f64 * 0.2;
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that can't hold the next item
    if next_item_size > 0 && post_residual > 0 {
        if (post_residual as u32) < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        } else {
            // residual can host next item: reward proportional to how snugly
            let snug = 1.0 - (post_residual - next_item_size) as f64 / (bin_capacity as f64);
            score -= 8.0 * snug;
        }
    }

    // Last-chance bin pressure: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Prefer bins below mean residual (balance across bins)
    score += 0.15 * ((bin_residual as f64) - mean_residual);

    // Time horizon: early in stream, opening new bins is cheaper (many items left to fill them);
    // late in stream, avoid opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses
        score += 10.0 + 40.0 * progress;
        // If no open bin fits well, opening new bin early is fine
        if fitting_bins_count == 1 && progress < 0.5 {
            score -= 12.0 * (1.0 - progress);
        }
    } else if post_residual == 0 {
        // Perfect fill: big reward
        score -= 20.0;
    }

    // Discourage leaving residuals in the awkward 1..=9 zone (unusable dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Mild preference for fuller bins overall
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    // Exploration term: slight coupling between open bins count and lookahead
    if open_bins_count > 3 && next_item_size > 0 {
        let pair_fit = (post_residual as u32) >= next_item_size;
        if pair_fit {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with smooth polynomial shaping.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Non-linear coupling of post-residual with stream progress:
    // early on, tolerate slack; later, penalize dead space more strongly.
    let progress_weight = 0.5 + 2.0 * progress * progress;
    score += progress_weight * norm_pr * pr;

    // Reward tight fits smoothly via item_size / residual ratio.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    } else {
        // Smooth penalty when many bins compete (spread usage).
        score += 0.3 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        let fits_next = if (post_residual as u32) >= next_item_size { 1.0 } else { 0.0 };
        let tightness = 1.0 - ((post_residual as i64 - next_item_size as i64).abs() as f64 / cap);
        score -= 8.0 * fits_next * tightness.max(0.0);
    } else {
        // Last item: strongly minimize residual.
        score -= 20.0 * norm_pr;
    }

    // Mean-residual coupling: penalize bins far from mean residual (smooth quadratic).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Slight preference for consolidating into fewer bins when many are open.
    score -= 0.05 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: mildly discourage opening a new bin unless residual is large.
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: bins whose leftover falls into
    // "small" residue classes (0..=10, or just above half of small items) are
    // more likely to be filled later, so reward them.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 10 {
        score -= 25.0;
    } else if pr >= 10 && pr < 20 && pr % 10 <= 2 {
        score -= 8.0; // near-class boundaries
    }

    // Dead-space penalty grows super-linearly for residuals that no typical
    // item (>= 10) can ever use.
    if pr < 10 && pr > 0 {
        score += 30.0; // unusable sliver
    }

    // Integer-division threshold: residuals that are multiples of common item
    // sizes are "harmonic" and likely reusable.
    if pr > 0 {
        let harmonic = (pr % 10 == 0) || (pr % 20 == 0) || (pr % 25 == 0) || (pr % 50 == 0);
        if harmonic { score -= 12.0; }
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly prefer this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            score -= 10.0;
        } else {
            // next item cannot use this bin's leftover: mild penalty scaled by gap
            score += ((next_item_size - pr) as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive early in
    // the stream or when mean residual across open bins is very low.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_r = mean_residual;
        // If open bins are mostly full (low mean residual), new bin is fine.
        score = 55.0 + progress * 10.0 - mean_r * 0.6;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // a fresh bin always fits the next item
            score -= 5.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        if progress > 0.8 {
            score += 15.0;
        }
    }

    // Mild pressure to keep the number of open bins from exploding.
    score += (open_bins_count as f64) * 0.05;

    // Slight tie-break: prefer bins whose residual fraction is closest to a
    // simple capacity fraction (1/2, 1/4) after placement.
    let frac = post_residual as f64 / bin_capacity as f64;
    if (frac - 0.5).abs() < 0.05 || (frac - 0.25).abs() < 0.05 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are worst when next item can't use them.
    if post_residual > 0 {
        let dead = next_item_size == 0 || (next_item_size as u32) > post_residual;
        if dead {
            // smaller dead gap = worse (more wasted); penalize inversely
            score += 40.0 / (post_residual as f64);
            // absolute dead space also penalized
            score += (post_residual as f64) * 0.5;
        } else {
            // next item fits exactly-ish: reward tight chains
            score -= 6.0 + (post_residual as f64) * 0.2;
        }
    } else {
        // perfect fit: strong reward
        score -= 25.0;
    }

    // Tightness reward: prefer bins where item fills a large fraction of residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open bins pressure: with many open bins, discourage spreading; with few, encourage filling
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.6 * (1.0 - progress);

    // Mean residual coupling: prefer bins below mean residual (tighter bins) when many bins open
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: only attractive when current item is large relative to mean residual
    // or no open bin is a good fit
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0 || (mean_residual > 0.0 && item_size as f64 > mean_residual * 0.9);
        if poor_fit {
            score -= 12.0; // opening a fresh bin is fine
        } else {
            score += 30.0; // discourage opening when good fits exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-item closure: bin fully packed by the next item.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits; reward tightness of the leftover chain.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - slack * 0.5;
        } else {
            // Next item cannot fit here: penalize dead space relative to next item.
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Relative-to-mean coupling: bins tighter than average are better targets.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.3;
    } else {
        score += (residual_f - mean_residual) * 0.15;
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when item is huge or no good fit exists.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.8 {
            score -= 30.0; // huge item: fresh bin is fine
        } else {
            score += 35.0 * (1.0 - fill_ratio); // penalize wasting a fresh bin
        }
    }

    // Early in stream: slight preference to consolidate into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more strongly than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: prefer bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 6.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
        // Bonus if post residual matches next item exactly.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly, but allow it when mean residual is fragmented
    // or the fit is poor.
    if bin_residual == bin_capacity {
        score += 14.0;
        if mean_residual < 12.0 && open_bins_count > 0 {
            score -= 10.0; // open bins nearly full; new bin is fine
        }
        if post_residual as f64 > mean_residual + 20.0 {
            score += 10.0;
        }
    }

    // Global fragmentation pressure: many open bins with high mean residual
    // favors consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let fragmentation = mean_residual * (open_bins_count as f64).ln();
    score += 0.05 * fragmentation * (1.0 - progress);

    // Small time-dependent tilt: later in stream, prefer tighter packing.
    score -= 6.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: reward tight packing via cubic in normalized post residual
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Smooth progress coupling: later in stream, tolerate less residual slack
    let progress_coupling = 1.0 + 1.5 * progress * (1.0 - progress) + 2.0 * progress * progress;
    score *= progress_coupling;

    // Penalize dead space relative to mean residual of open bins
    score += 0.3 * (post - mean_residual).abs();

    // Lookahead: if next item fits snugly into this post-residual, reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let snug = 1.0 - (post - nxt).abs() / cap;
        if snug > 0.0 {
            score -= 6.0 * snug * snug;
        }
        // Penalize leaving residual just below next item (blocking)
        if post >= nxt && post - nxt < 10.0 {
            score += 4.0;
        }
    } else {
        // Last item: strongly prefer filling bins tightly
        score -= 3.0 * norm_post;
    }

    // Last-chance bin before opening a new one: reward strongly
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a bin when progress is low or many bins open
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
        score += 15.0 + 2.0 * pressure - 10.0 * (1.0 - progress);
        // But if no existing bin fits well, allow new bin
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Mild penalty for too many open bins
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space mod capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Penalize residual in "wasted" harmonic classes: (0,10] is nearly unusable
    if post_residual <= 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        score += 25.0;
    } else if post_residual <= 30 {
        score += 8.0;
    }

    // Reward residual that is a good harmonic multiple (divisible classes)
    let class = post_residual / 10;
    if class % 3 == 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Tight fit reward: item fills most of the bin
    let tight = item_size as f64 / bin_residual as f64;
    if tight > 0.9 {
        score -= 40.0;
    } else if tight > 0.7 {
        score -= 15.0;
    }

    // Lookahead coupling: can next item fit in post_residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 0.2 * (next_item_size as f64);
        } else {
            score += 12.0;
            // If next item also can't fit anywhere else, waste matters more
            if next_item_size > bin_capacity / 2 && post_residual < 20 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bins attractive only when open
    // bins are crowded (high mean residual) or this is a poor fit
    if bin_residual == bin_capacity {
        let crowded = mean_residual / cap;
        // Opening a new bin is good when existing residuals are small (crowded)
        score = 0.5 * cap - 80.0 * (1.0 - crowded) - 0.3 * open_bins_count as f64;
        if post_residual == cap {
            // empty bin: prefer it when mean residual low and many bins open
            if mean_residual < 0.35 * cap {
                score -= 20.0 + 0.5 * open_bins_count as f64;
            }
        }
        // If item is large, fresh bin is fine
        if item_size > bin_capacity / 2 {
            score -= 25.0;
        }
    }

    // Stream progression: late in stream, consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Any post_residual that is too small to hold even the smallest future item
    // (1..=100 unknown distribution, so treat < 10 as near-dead) is heavily penalized.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }
    // Dead space relative to the lookahead item: if the next item cannot fit here,
    // this residual is likely wasted; penalize proportionally.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.6 * (next_item_size - post_residual) as f64;
    }

    // --- Reward tight fits ---
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // --- Last-chance bin pressure ---
    if fitting_bins_count == 1 {
        // If this is the only bin that fits, strongly prefer using it over opening a new bin.
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Mild diversity bonus: keep several viable bins alive.
        score -= 1.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // --- Open-bin pressure: discourage proliferation of open bins ---
    score += 0.35 * open_bins_count as f64;

    // --- New-bin candidate handling (bin_residual == bin_capacity) ---
    if bin_residual == bin_capacity {
        // Baseline cost of opening a fresh bin: large constant penalty.
        let mut new_bin_score = 85.0 + 0.35 * open_bins_count as f64;
        // Opening a new bin is attractive when existing residuals are fragmented
        // (high mean residual spread) and many bins are open.
        new_bin_score -= 0.15 * mean_residual;
        // Late in the stream, prefer consolidation into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += 20.0 * progress;
        // If next item is huge, a fresh bin with full capacity is valuable.
        if next_item_size > 60 {
            new_bin_score -= 15.0;
        }
        // Last-chance override: never open a new bin if it's the only option.
        if fitting_bins_count == 1 {
            new_bin_score += 200.0;
        }
        score = new_bin_score;
    }

    // --- Lookahead synergy: reward leaving residual exactly consumable by next item ---
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
        if post_residual == next_item_size {
            score -= 10.0; // perfect chain: bin becomes exactly filled by next item
        }
    }

    // --- Mean residual coupling: prefer bins below mean residual (tighter bins first) ---
    score -= 0.2 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0; // chain of perfect fits
        } else if next_item_size <= post_residual {
            // next fits: reward proportionally to how tight the chain is
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 300.0 * tightness;
        } else {
            // next item does NOT fit: post_residual becomes dead space for the lookahead
            let waste = (next_item_size - post_residual) as f64;
            score += 0.6 * waste.min(80.0);
        }
    }

    // Penalize small unusable leftovers (dead space) relative to item size granularity
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New empty bin candidate: penalize unless open bins are all bad fits
    if bin_residual == bin_capacity {
        score += 400.0;
        // if few fitting bins, opening new bin is less bad
        if fitting_bins_count <= 1 {
            score -= 350.0;
        }
    }

    // Mild preference for bins tighter than average (better space utilization)
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.3 * (res - mean_residual);
    }

    // Progress pressure: later in stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness * tightness;

    // Penalize leaving dead space that cannot fit the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            let dead = (next_item_size - post_residual) as f64;
            score += 0.6 * dead;
        } else {
            // Reward bins that can also host the next item (pairing bonus).
            score -= 4.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Prefer bins below the mean residual (balance load / avoid fragmenting full bins).
    score += 0.15 * ((bin_residual as f64) - mean_residual);

    // Late in the stream, favor compacting into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (item_size as f64) / (bin_capacity as f64);

    // Many open bins: discourage opening new ones unless it's the fresh-bin candidate.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 10.0 + 0.5 * (open_bins_count as f64);
        // But a new bin is attractive for very large items or when no bin fits well.
        if post_residual == 0 || (item_size > 60 && fitting_bins_count == 0) {
            score -= 15.0;
        }
    }

    // Slight penalty for exact-fill waste asymmetry: prefer post_residual in {0, >=10}.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Non-linear coupling: post_residual polynomial interacting with stream progress.
    // Early in the stream, prefer tight fits moderately; late in the stream, strongly prefer
    // small post_residual (dead space becomes costlier).
    let tightness = 1.0 - norm_pr; // 1.0 = perfect fit
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * (0.5 + 1.5 * progress * progress);
    score += 20.0 * poly;

    // Reward tight fits more as stream progresses (smooth interaction with progress).
    score -= (15.0 + 25.0 * progress) * tightness * tightness;

    // Last-chance bonus: strongly prefer using the only fitting bin (avoid opening new bins late).
    if fitting_bins_count == 1 {
        score -= 12.0 + 18.0 * progress;
    } else {
        // Mild penalty when many bins fit, to encourage consolidating into fuller bins.
        score += (fitting_bins_count as f64).ln().max(0.0) * 3.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits into the post-residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack_after_next = pr - nxt;
            // Reward leaving a usable space for the next item, scaled by progress.
            score -= (8.0 + 10.0 * progress) * (1.0 - (slack_after_next / cap).min(1.0));
        } else {
            // Penalize blocking the next item slightly.
            score += 4.0 * (1.0 - progress);
        }
    }

    // Mean-residual coupling: bins far below mean residual are less attractive early on
    // (spread items), more attractive late (consolidate).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * (6.0 - 12.0 * progress);

    // Discourage proliferation of open bins when few remain fitting.
    let open_f = open_bins_count as f64;
    score += (open_f / (open_f + 5.0)) * 5.0 * (1.0 - progress);

    // New-bin candidate handling: an empty bin gets a baseline penalty so it is only
    // chosen when all open bins score poorly (poor fits).
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: classify dead space by
    // integer division and modulo against capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional class of post_residual relative to capacity
    let frac = pr / cap;
    if frac < 0.10 {
        // Excellent fit: near-perfect packing, strong reward
        score -= 30.0 + 200.0 * (0.10 - frac);
    } else if frac < 0.20 {
        score -= 12.0;
    } else if frac < 0.30 {
        score -= 4.0;
    } else if frac > 0.90 {
        // Nearly empty bin used for a small item: wasteful unless last chance
        score += 25.0;
    }

    // Modulo arithmetic on post_residual: residuals divisible by common
    // size classes (multiples of 10, 25, 50) are more reusable.
    let pri = post_residual;
    if pri > 0 {
        if pri % 10 == 0 { score -= 6.0; }
        if pri % 25 == 0 { score -= 4.0; }
        if pri % 50 == 0 { score -= 4.0; }
        // Harmonic class via integer division: which "size band" the leftover fits
        let band = pri / 10; // bands 0..10
        score -= (band as f64) * 0.5; // larger usable band slightly preferred
        // Penalize awkward residuals in (1..10) and (11..20) style slivers
        if pri < 10 { score += 8.0; }
    } else {
        // Perfect fill
        score -= 40.0;
    }

    // Lookahead coupling: does post_residual harmonically admit next item?
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if post_residual >= next_item_size {
            // Next item fits exactly or into a harmonic class of the residual
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0;
            if (post_residual - next_item_size) % 10 == 0 { score -= 6.0; }
            if slack < 10.0 { score -= 8.0; } // near-exact chain fit
        } else {
            // Next item won't fit here; residual becomes dead space
            score += 5.0 + (ni - pr).min(30.0) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins: prefer consolidating into existing bins over opening new
    let progress = step_index as f64 / (total_items.max(1) as f64).max(1.0);
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: open a fresh bin only when mean residual is tight
    // (existing bins are nearly full) and this bin is pristine.
    if bin_residual == bin_capacity {
        if mean_residual < 12.0 {
            score -= 15.0; // worth opening a new bin
        } else {
            score += 18.0 + mean_residual * 0.2; // reuse partial bins instead
        }
    }

    // Mild preference toward tighter existing bins (smaller residual before fit)
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 35 {
        score += 6.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill_ratio;

    // Open-bin pressure: discourage scattering across many bins slightly.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item cannot fit post-residual but post-residual is dead space, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 10.0;
    }

    // New-bin candidate handling: neutral-ish baseline, only attractive when
    // current bins are fragmented or many bins are already open.
    if bin_residual == bin_capacity {
        score = 45.0 + 0.8 * open_bins_count as f64 - 20.0 * (mean_residual / bin_capacity as f64);
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a new bin
        }
    }

    // Mild stream-progression tightening: early on prefer consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead: post_residual exactly matches next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item fits with small leftover
    else if next_item_size > 0 && post_residual > next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - gap / 40.0).max(0.0);
    }
    // Next item does NOT fit this bin: penalize if we waste the residual
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
        // Extra penalty when residual becomes unusable dead space
        if post_residual < 10 {
            score += 20.0;
        }
    }

    // Tight fits are good: small post_residual relative to item size
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += 5.0 * tightness.min(3.0);

    // Compare against mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin before opening a new bin: strong reward
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize moderately so it only wins when fits are bad
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if next item is large and current fit is loose, opening new bin is fine
        if next_item_size > 0 && post_residual as f64 > next_item_size as f64 + 20.0 {
            score -= 20.0;
        }
    }

    // Early in stream: encourage consolidation
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress);

