}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly
    score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Penalize dead space that cannot fit typical future items
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        score += 8.0 * dead * dead;
    }

    // Last-resort bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 4.0;
        }
    }

    // New-bin candidate handling: only attractive when current fit is bad
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64 / bin_capacity as f64; // = 1 - item/C
        let pressure = mean_residual / bin_capacity as f64;
        let horizon = step_index as f64 / (total_items.max(1) as f64);
        // Open new bin late in stream or when open bins are fragmented
        score += 25.0 - 18.0 * horizon - 10.0 * pressure - 15.0 * (1.0 - fit_quality);
        score += (open_bins_count as f64).sqrt() * 2.0;
    }

    // Mild preference for bins below mean residual (consolidate emptier bins)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: normalized post-residual, with non-linear polynomial shaping
    let mut score = pr_norm * (1.0 + 0.6 * pr_norm - 0.8 * pr_norm * pr_norm);

    // Stream-progress coupling: penalize residual more as stream advances
    score += 0.9 * pr_norm * pr_norm * progress;

    // Dead-space quadratic penalty: residuals too small to fit typical items
    let dead = (pr_norm - 0.15).max(0.0);
    score += 1.4 * dead * dead;

    // Mean-residual coupling: prefer bins near the mean residual (balanced packing)
    let mr_norm = mean_residual / cap;
    score += 0.5 * (pr_norm - mr_norm) * (pr_norm - mr_norm);

    // Lookahead: reward if next item fits in post-residual
    if next_item_size > 0 {
        let fits_next = if (pr as u32) >= next_item_size { 1.0 } else { 0.0 };
        score -= 0.7 * fits_next * (1.0 - progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 1.2;
    }

    // New-bin candidate: penalize opening new bins, more so early/mid stream
    if bin_residual == bin_capacity {
        score += 1.5 + 0.8 * progress;
    }

    // Slight reward for tighter fits (large item relative to residual)
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 0.4 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 create "dead space" classes.
    let pr = post_residual;
    let residue = pr % 10;
    // Residues 1..9 (esp. small nonzero) are hard to fill: penalize.
    if pr > 0 && pr < 10 {
        score += 25.0; // tiny unusable sliver
    } else if residue != 0 {
        score += (residue as f64) * 0.8;
    } else {
        score -= 4.0; // residue 0: perfectly harmonic
    }

    // Quotient classes: post_residual in [50,100] keeps room for a medium item.
    if pr >= 50 {
        score -= 6.0;
    } else if pr >= 25 {
        score -= 2.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            score -= (next_item_size as f64) * 0.35;
        } else {
            // next item cannot use this residual: penalize large leftover
            score += ((pr + 5) / 10) as f64 * 2.0;
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: mild penalty so we prefer existing bins unless fit is bad.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Opening a new bin is fine early / when many items remain.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
    }

    // Prefer bins tighter than the mean residual (concentrate fill).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Modulo harmony between item and residual (co-divisibility reward).
    if bin_residual % item_size.max(1) == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any item are toxic.
    if post_residual < 10 {
        score += 60.0; // unusable dead space, but also a "perfect" fill... balance below
    }
    if post_residual == 0 {
        score -= 100.0; // perfect fill is the best outcome
    } else if post_residual < 10 {
        // small but nonzero gap: heavily penalize relative to its uselessness
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    } else {
        // usable gap: mild penalty scaled by how much slack remains
        score += 0.15 * post_residual as f64;
    }

    // Reward tight fits (fill fraction of the consumed space)
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill * fill;

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is great
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean residual coupling: prefer bins with residual below mean (compact them)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Lookahead: if next item fits the post residual exactly, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    } else if next_item_size > post_residual && post_residual < 10 {
        score += 20.0; // this gap can never serve the next item either
    }

    // New-bin candidate: neutral-ish baseline, opened only when open bins are bad
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect match with the lookahead item (aggressive 2-step lookahead).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match: strong bonus.
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            score += gap * 0.8;
            // If next item fits exactly into post_residual region, mild reward.
            if next_item_size <= post_residual {
                score -= 10.0 * (1.0 - gap / (bin_capacity as f64));
            } else {
                // Next item won't fit: penalize proportionally to wasted potential.
                score += gap * 0.3;
            }
        }
    } else {
        // Last item: minimize post residual hard.
        score += post_residual as f64 * 0.5;
    }

    // Relative-to-mean coupling: bins with residual far below mean are "tight" -> prefer them.
    let rel = post_residual as f64 - mean_residual;
    score += rel * 0.35;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize creating tiny unusable dead space (dead zone below minimum item size 1..10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Prefer filling fuller bins as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (bin_capacity - post_residual) as f64 * 0.1 * (0.5 + progress);

    // Mild penalty when many bins are open: encourage consolidation.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, prefer it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post residual can't host next item: penalize proportional to wasted potential.
        score += 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Global state coupling: many open bins with high mean residual -> encourage consolidation.
    let pressure = mean_residual / bin_capacity as f64;
    score += 10.0 * pressure * (open_bins_count as f64).ln().max(1.0);

    // Time horizon: early in stream, opening new bins is cheap; late, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus discount early, surcharge late.
        score = bin_capacity as f64 - 40.0 * (1.0 - progress) + 55.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0;
        }
    } else {
        score -= 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);
    score -= 40.0 * poly * (0.5 + progress);

    // Penalize tight-but-wasteful residuals as stream progresses
    score += 12.0 * progress * norm_pr * norm_pr * cap;

    // Reward near-exact fits
    let fit_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_frac * fit_frac * (1.0 - progress);

    // Last-chance bonus: only one fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 20.0 * (1.0 - norm_pr);
    }

    // Lookahead: favor bins whose post_residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 10.0 * (1.0 - slack) * (1.0 - progress);
        } else {
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Mild pressure toward consolidation when many bins are open
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // Prefer bins with residuals near the mean (balance)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: penalize opening a new bin, more so early on
    if bin_residual == bin_capacity {
        score += 30.0 + 60.0 * (1.0 - progress) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in "dead zones"
    // (very small remainders that nothing can use) are penalized via modulo classes.
    let pr = post_residual;
    let class = pr % 10;
    // Dead-zone classes: 1..=3 are nearly unusable -> heavy penalty.
    if class >= 1 && class <= 3 {
        score += 12.0;
    } else if class == 0 {
        // Perfect harmonic alignment: remainder divisible by 10 is reusable.
        score -= 6.0;
    } else if class >= 7 {
        score -= 2.0;
    }

    // Integer-division threshold: exact halving of capacity is a harmonic sweet spot.
    let half = bin_capacity / 2;
    if pr == half {
        score -= 8.0;
    } else if pr < half && pr >= half / 2 {
        score -= 3.0;
    }

    // Coupling with next item (lookahead harmonic match):
    if next_item_size > 0 {
        if pr == next_item_size {
            // Perfect fit for the next item: excellent.
            score -= 15.0;
        } else if pr > next_item_size && (pr - next_item_size) % 10 == 0 {
            // Next item leaves a harmonic remainder.
            score -= 7.0;
        } else if next_item_size > pr {
            // Next item cannot fit here anyway; mildly neutral.
            score += 1.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins more when many bins are open and stream is late.
        let congestion = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score += 25.0 * congestion + 10.0 * progress;
        // But if the item is large relative to capacity, a fresh bin is fine.
        score -= (item_size as f64 / cap) * 12.0;
        // If mean residual is large (bins are empty-ish), opening new is wasteful.
        score += (mean_residual / cap).max(0.0) * 15.0;
    }

    // Prefer tight fits overall: small post_residual relative to item size.
    score += (item_size as f64 / cap) * 4.0;

    // Slight preference for bins with below-average residual (denser bins).
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
