    // New-bin candidate: penalize opening a new bin unless current bins are bad.
    if bin_residual == bin_capacity {
        score += 40.0 + 5.0 * open_bins_count as f64;
        // But if next item is huge and gaps are small, new bin is attractive.
        if next_item_size > 70 {
            score -= 50.0;
        }
    }

    // Open-bin pressure: mildly discourage scattering across many bins.
    score += 0.3 * open_bins_count as f64;

    // Prefer bins tighter than the mean (packing concentrated bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
