        score -= 30.0;
    }

    // Time horizon: early in stream, prefer compacting into existing bins;
    // late in stream, waste tolerance matters less, keep bonus milder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 12.0 * (1.0 - progress); // early compaction bonus

    // Global state: many open bins with slack -> prefer filling slack bins.
    if open_bins_count > 2 {
        score += 0.5 * open_bins_count as f64 * (1.0 - (bin_residual as f64 / bin_capacity as f64));
    }

    // Mean residual coupling: prefer bins close to mean residual (balanced packing).
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate handling: only attractive when nothing fits well.
    if bin_residual == bin_capacity && bin_capacity == 100 {
        let base = score + 55.0;
        if next_item_size > 0 && next_item_size <= bin_residual {
            return base - 10.0;
        }
        return base;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * norm_pr);

    // Non-linear penalty for dead space that is too small to be useful later
    let dead = 1.0 - (pr / 10.0).min(1.0);
    score += 25.0 * dead * dead * (0.5 + progress);

    // Reward tight fits
    let tight = (item_size as f64) / cap;
    score -= 12.0 * tight * tight * (1.0 - progress * 0.5);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Prefer bins with residuals deviating from mean (consolidate waste)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Lookahead: reward if next item fits in post_residual
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 6.0 + 8.0 * (next_item_size as f64 / cap);
    }

    // Mild penalty for spreading across many open bins early
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (class 0) are heavily rewarded.
    let class = post_residual % 10;
    if post_residual == 0 {
        score -= 1000.0; // exact fit
    } else if class == 0 {
        score -= 30.0; // multiple-of-10 residual stays usable for typical items
    } else if class >= 5 {
        score -= 10.0; // half-class residual still decent
    } else {
        score += (5 - class) as f64 * 4.0; // odd small residual = dead space penalty
    }

    // Harmonic coupling: can next_item_size land exactly in post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // chains into a perfect fit next step
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            score -= 20.0 - (gap % 10) as f64 * 1.5;
        } else {
            score += 15.0; // next item can't reuse this residual
        }
    }

    // Integer-division thresholds on residual fraction.
    let frac = post_residual as f64 / bin_capacity as f64;
    let band = (frac * 10.0).floor() as i32;
    score -= band as f64 * 2.0;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Mild pressure against proliferating bins when residual is already small.
    score += open_bins_count as f64 * 0.05 * (1.0 - frac);

    // Early stream: be slightly greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (bin_residual - post_residual) as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest plausible item (<= 10) are pure waste; penalize hard.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        score += 25.0;
    } else if post_residual <= 35 {
        score += 8.0;
    } else {
        // Larger residuals are valuable storage; reward keeping them.
        score -= (post_residual as f64) * 0.35;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over opening new bins; add pressure to the new-bin candidate.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * (open_bins_count as f64);
    } else {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin; reward it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // this placement is excellent.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score += 12.0; // would strand a tiny gap for the next item
        }
    }

    // Early in the stream, be slightly more willing to keep bins tidy;
    // late in the stream, prioritize closing bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: next item exactly fills this bin's post-residual (perfect 2-step match).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0;
        } else {
            let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
            // Penalize mismatch scaled by gap; small gaps still mildly favored.
            score += gap * 0.5;
            // Reward if next item still fits in post-residual (soft lookahead feasibility).
            if post_residual >= next_item_size {
                score -= 20.0;
            } else {
                // Dead space: post_residual can't host next item.
                score += (post_residual as f64 - mean_residual).abs() * 0.3;
            }
        }
    }

    // Prefer tighter fits relative to mean residual across open bins.
    score += (post_residual as f64 - mean_residual) * 0.2;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New empty bin candidate: penalize so it's only chosen when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 200.0;
        // But if next item is large and current item small, new bin keeps flexibility.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 220.0;
        }
    }

    // Mild penalty for opening many bins late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space non-linearly; small residuals are precious.
    if post_residual > 0 {
        score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 40.0;
    }

    // Reward tight fits: exact or near-exact packing.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: bonus if the next item can fit into the post residual (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + (next_item_size as f64 / bin_capacity as f64) * 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize stranding: post residual too small for the next item.
        score += 6.0;
    }

    // Time horizon: early in the stream, be conservative with new bins;
    // late in the stream, prefer filling existing bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.25 * progress;

    // Global state coupling: many open bins with high mean residual -> discourage
    // opening new bins; prefer consolidating into bins above mean residual.
    if bin_residual as f64 > mean_residual && open_bins_count > 1 {
        score -= 5.0;
    }
    if open_bins_count > 4 {
        score += (open_bins_count as f64).ln() * 2.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let urgency = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 35.0 * urgency + 8.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // new bin useful for chaining large items
        }
    }

    // Prefer bins whose residual is close to the item (best-fit flavor).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Base: strongly prefer tight fits (quadratic in normalized post-residual)
    let norm_pr = pr / cap;
    score += 40.0 * norm_pr * norm_pr;
    score -= 25.0 * norm_pr * (1.0 - norm_pr);

    // Stream-progress coupling: late in the stream, be greedier about tight fits
    let tight_bias = 30.0 * progress * (1.0 - norm_pr);
    score -= tight_bias;

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let nx = next_item_size as f64;
        let fill_ratio = nx / cap;
        score -= 18.0 * (1.0 - progress) * fill_ratio * (1.0 - norm_pr);
    } else if next_item_size > 0 {
        // dead space relative to next item: penalize smoothly
        let waste = (next_item_size as f64 - pr) / cap;
        score += 12.0 * waste * (0.5 + 0.5 * progress);
    }

    // Last-chance bin: reward using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // New-bin candidate: penalize opening a new bin, more so when open bins exist and fit
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64 / (1.0 + open_bins_count as f64)).sqrt();
        score += 35.0 + 20.0 * open_pressure * (1.0 - progress)
            - 10.0 * (item_size as f64 / cap) * progress;
    }

    // Mild preference for bins tighter than the mean residual (balance consolidation)
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0) * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls on
    // "nice" residue classes (multiples of small integers) are more
    // likely to be reusable by future items -> reward them.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        else if pr % 5 == 0 { score -= 3.0; }
        else if pr % 2 == 0 { score -= 1.0; }
        else { score += 2.5; } // odd residual is harder to pair
    } else {
        // Perfect fit: best possible outcome.
        score -= 40.0;
    }

    // Dead-space penalty: residuals below the smallest item class (<=10)
    // are unusable; penalize quadratically in that zone.
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * (10 - pr) as f64 * 0.6;
    }

    // Integer-division threshold: residual in [20, 30) is a sweet spot
    // for mid-size items; residual in [1, 19) is risky.
    let band = pr / 20; // 0,1,2,3,4
    score += match band {
        0 => 8.0,
        1 => 0.0,
        2 => -2.0,
        3 => -1.0,
        _ => 0.5,
    } as f64;

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward; if it nearly fits, mild penalty for fragmentation.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 5.0 - slack.min(15.0) * 0.25;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin when mean residual
    // across open bins is still substantial, but allow it late in the
    // stream or when open-bin pool is fragmented.
    if bin_residual == bin_capacity {
        score += 18.0;
        score -= mean_residual * 0.15;
        if open_bins_count > 6 {
            score -= 6.0;
        }
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 4.0;
    }

    // Mild global pressure: prefer filling bins with low residual overall.
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    if !is_new_bin {
        // Strict dead-space avoidance: small non-zero gaps are likely unusable
        if post_residual > 0 && post_residual < 12 {
            score += (12.0 - post) * (2.0 + progress);
        }
        // Lookahead (k=2): reward bins that stay usable for the next item
        if next_item_size > 0 {
            if (next_item_size as f64) <= post {
                score -= 6.0 + 4.0 * (next_item_size as f64) / cap;
            } else if post_residual > 0 {
                // next item won't fit: gap becomes dead space for lookahead
                score += ((next_item_size as f64) - post).min(20.0) * 0.8;
            }
        }
        // Last-chance pressure: if this is the only bin that fits, use it
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
        // Mild open-bin pressure: mildly discourage spreading across many bins
        score += open_bins_count as f64 * 0.05;
    } else {
        // New-bin candidate: attractive when existing bins are nearly full
        score -= (cap / 2.0 - mean_residual).max(0.0) * 1.5;
        // Pressure against opening yet another bin when many are open
        score += open_bins_count as f64 * 1.2;
        // Late in the stream, prefer consolidating into existing bins
        score += progress * 10.0;
        // Penalize a new bin that immediately can't host the next item
        if next_item_size > 0 && (next_item_size as f64) > post {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect two-item fill
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.3; // penalize leftover after lookahead placement
            if slack <= 10.0 {
                score -= 8.0; // near-perfect chain
            }
        } else {
            // next item cannot fit here; dead space penalty scaled by gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.4;
        }
    } else {
        // last item: prefer tightest fill
        score -= 5.0;
    }

    // Reward bins with residual below mean (tight bins), penalize loose bins
    score += (mean_residual - post_residual as f64) * 0.15;

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Penalize opening new bins when many open bins exist with room
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
    }

    // Late in stream: consolidate, favor existing bins more strongly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly favored: reward low post_residual non-linearly.
    if post_residual < 10 {
        score -= 60.0;
    } else if post_residual < 20 {
        score -= 30.0;
    } else if post_residual < 30 {
        score -= 12.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // this placement chains nicely; reward it.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    }
    // If next item cannot use post_residual, penalize wasted dead space a bit.
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0 * (post_residual as f64 / 100.0);
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many open bins: discourage spreading; prefer bins below mean residual
    // (filling emptier bins balances residual distribution).
    if open_bins_count > 3 {
        let diff = mean_residual - bin_residual as f64;
        score += 0.3 * diff;
    }

    // Late in the stream, be more aggressive about consolidating:
    // reward using existing bins more heavily as step progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 15.0 * progress;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // if this is a large item that would leave poor fits elsewhere, or
    // late in the stream with few bins. Otherwise penalize.
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = fitting_bins_count > 0
            && open_bins_count > 0
            && (bin_residual as f64 - item_size as f64) < mean_residual * 0.5;
        if poor_fit_elsewhere && item_size >= 50 {
            score -= 10.0; // large item, fresh bin may be reasonable
        } else {
            score += 35.0 + 10.0 * (1.0 - progress); // default: prefer existing bins
        }
        if item_size >= 70 {
            score -= 20.0; // huge items pair well with fresh bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer small post residual, with non-linear sharpening
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, tight fits matter more
    let progress_coupling = (0.5 + progress) * norm_post * (1.0 - norm_post);
    score -= 6.0 * progress_coupling;

    // Penalize dead space quadratically as stream advances
    score += 4.0 * progress * norm_post * norm_post * cap;

    // Reward filling bins deeply when few alternatives exist
    if fitting_bins_count == 1 {
        score -= 3.0 * norm_item;
    }

    // Lookahead: keep room for next item when it fits nicely
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        if nx <= norm_post {
            score -= 2.0 * (nx / (norm_post + 0.05));
        } else {
            score += 1.5 * (nx - norm_post);
        }
    }

    // Mild preference for consolidating into fewer bins
    score -= 0.05 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: discourage unless residual spread is large
    if bin_residual == bin_capacity {
        score += 2.0 + 3.0 * progress + 0.5 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into modulo buckets.
    // Small post_residuals (< 10) are nearly perfect fits -> strong reward.
    if post_residual == 0 {
        score -= 500.0; // perfect fit
    } else if post_residual < 10 {
        score -= 120.0; // near-perfect, dead space unusable by min item anyway
    } else {
        // Modulo-10 harmonic class: post_residual % 10 tells how "round" the leftover is.
        let class = (post_residual % 10) as f64;
        score -= (10.0 - class) * 2.0; // favor leftovers close to a multiple of 10
    }

    // Integer-division thresholds: leftover divisible by common small item sizes
    // (items >= 1..100, so leftovers divisible by 5 or 25 are reusable).
    if post_residual >= 10 {
        if post_residual % 25 == 0 { score -= 40.0; }
        else if post_residual % 5 == 0 { score -= 15.0; }
        if post_residual % 7 == 0 { score -= 5.0; }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 + slack * 0.5;
        // exact match is ideal
        if slack == 0.0 { score -= 80.0; }
    } else if next_item_size > 0 {
        // next item cannot use this leftover; penalize proportionally to wasted capacity
        score += (next_item_size as f64) * 0.15;
    }

    // Capacity fraction thresholds: reward filling past 50%, 75%, 90% of capacity.
    let fill = 1.0 - (post_residual as f64) / cap;
    if fill >= 0.9 { score -= 70.0; }
    else if fill >= 0.75 { score -= 35.0; }
    else if fill >= 0.5 { score -= 10.0; }
    else { score += 15.0; } // light fills are wasteful

    // Last-chance bin: only one bin can fit this item -> strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 90.0;
    }

    // New-bin candidate handling: an empty bin has no scarcity; only choose it
    // when open bins are congested (few fitting bins, high mean residual spread).
    if bin_residual == bin_capacity {
        let congestion = (fitting_bins_count as f64).max(1.0);
        score += 45.0 / congestion; // penalty shrinks when few bins fit
        // early in stream, opening bins is cheap; late, prefer consolidation
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 30.0;
        // if mean residual of open bins is large, opening a new bin is fine
        score -= (mean_residual - 50.0).max(0.0) * 0.6;
    }

    // Mild preference to balance across bins: prefer bins below mean residual
    // (consolidation into emptier bins keeps large gaps intact).
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.3;

    // Tie-break: very slight noise-free deterministic jitter via step parity classes.
    score += ((step_index % 3) as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual as i32) as f64;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits (high fill ratio).
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill;

    // Penalize creating gaps that the lookahead item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Open-bins pressure: mildly discourage spreading across many bins.
    score += 0.15 * open_bins_count as f64;

    // Last-chance bin: strong bonus to use it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score = 45.0 + 40.0 * pressure + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && item_size <= next_item_size {
            score -= 10.0; // new bin pairs well with the next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: tight fit reward
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: reward bins whose post_residual matches the next item well
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let match_gap = post_residual as f64 - nxt;
            score -= 25.0 * (1.0 - match_gap / bin_capacity as f64);
        } else {
            // next item can't fit here; penalize wasted residual more strongly
            score += 0.5 * post_residual as f64;
        }
        // perfect chain: item then next item fills bin nearly exactly
        let chain_waste = bin_residual as f64 - item_size as f64 - nxt;
        if chain_waste >= 0.0 {
            score -= 20.0 * (1.0 - chain_waste / bin_capacity as f64);
        }
    }

    // Relative to mean residual: prefer bins already below mean (consolidate small residuals)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strong bonus to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: mildly penalize opening new bins unless residuals are tight
    if bin_residual == bin_capacity {
        let avg_tightness = mean_residual / bin_capacity as f64;
        score += 15.0 + 30.0 * avg_tightness;
        // but if next item is huge and nothing fits well, allow new bin
        if next_item_size >= 70 && post_residual as f64 >= next_item_size as f64 {
            score -= 20.0;
        }
    }

    // Late in stream: be more conservative, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on wasted space.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit is a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 5 {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size {
            let chain_waste = post_residual - next_item_size;
            score += 0.15 * chain_waste as f64;
        } else {
            // Next item won't fit here; slight penalty proportional to leftover.
            score += 0.05 * post_residual as f64;
        }
    }

    // Prefer filling already-open bins when many bins are open (bin count pressure).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 0.4 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Compare against mean residual: bins with residual near mean are neutral;
    // placing into bins with much larger residual wastes their flexibility.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.10 * dev;
    } else {
        score += 0.05 * dev; // small reward for tighter-than-average bins
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity or few bins are open.
    if bin_residual == bin_capacity {
        let size_ratio = item_size as f64 / bin_capacity as f64;
        let openness = open_bins_count as f64 / (1.0 + open_bins_count as f64);
        score += 30.0 - 25.0 * size_ratio - 10.0 * openness * progress;
    }

    // Mild time-horizon shaping: late in the stream, consolidate aggressively.
    score -= 6.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_norm = pr / cap;

    // Base: prefer tight fits (small post_residual), with smooth polynomial shaping.
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, larger residuals are tolerated; later, dead space is penalized harder.
    let prog_sq = progress * progress;
    let dead_weight = 0.5 + 2.5 * prog_sq;
    score += dead_weight * fit_norm * fit_norm * cap * 0.1;

    // Reward bins whose residual becomes small enough to be "sealed" (near-full).
    let seal = (1.0 - fit_norm).powi(3);
    score -= 12.0 * seal * (0.5 + progress);

    // Perfect fit bonus: smooth quadratic reward as post_residual -> 0.
    score -= (1.0 - fit_norm).powi(2) * 8.0;

    // Lookahead coupling: if next item fits the post-residual, reward this placement smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let snug = 1.0 - ((pr - nxt) / cap).abs();
            score -= 10.0 * snug * snug;
        } else {
            // Penalize placements that leave residual just barely too small for next item.
            let gap = (nxt - pr) / cap;
            score += 15.0 * gap * (1.0 - gap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mean-residual coupling: placing in a bin with residual near the mean keeps balance,
    // penalize extreme outliers smoothly (quadratic deviation).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // Many open bins: gently discourage spreading, favor consolidation.
    score += 0.15 * open_bins_count as f64 * fit_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "friendly"
    // residue classes (multiples of common item sizes) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        let friendly = (pr % 10 == 0) as i32
            + (pr % 20 == 0) as i32
            + (pr % 25 == 0) as i32
            + (pr % 50 == 0) as i32;
        score -= 6.0 * friendly as f64;
        // Dead space: leftover too small for the smallest plausible item (1..100
        // unknown, so use item_size as proxy for the regime) is penalized hard.
        if pr < 10 {
            score += 40.0;
        } else if pr < 20 {
            score += 15.0;
        }
        // Integer-division thresholds: post_residual / item_size ratio — how many
        // more copies of the current item could fit later.
        let copies = pr / item_size.max(1);
        score -= 3.0 * copies as f64;
    } else {
        // Perfect fill is the ideal outcome.
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // strongly reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual >= next_item_size {
            score -= 12.0;
            // harmonic match on (post_residual - next_item_size)
            let d = post_residual - next_item_size;
            if d % 10 == 0 { score -= 8.0; }
        } else {
            // next item cannot use this bin's leftover: mild penalty scaled by waste
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening fresh bins mildly, but allow it when
    // the item is large relative to residual (poor fits elsewhere).
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score += 30.0 - 20.0 * tightness;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Spread-aware term: prefer bins whose residual deviates from the mean in a
    // way that reduces dispersion (place into below-mean-residual bins).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Modulo harmonic bonus on bin_residual class (quantized capacity fractions).
    let q = bin_residual / (bin_capacity / 4).max(1);
    score -= match q {
        0 => 10.0,
        1 => 6.0,
        2 => 3.0,
        _ => 0.0,
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals too small for the smallest item (1..100 range, min item 1)
    // Treat post_residual < 10 as near-dead space (below typical small item sizes).
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 20.0;
    }

    // Reward tight fits: small post_residual relative to bin capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 40.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure from number of open bins: discourage spreading when many bins are open
    score += open_bins_count as f64 * 1.5;

    // Lookahead: if next item fits exactly into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // next item won't fit in this bin's leftover; penalize if leftover is large-ish dead space
        if post_residual < next_item_size {
            score += 8.0;
        }
    }

    // New-bin candidate: neutral baseline with slight penalty so we prefer existing bins
    // unless the fit is terrible; compare against typical open-bin scores.
    if bin_residual == bin_capacity {
        score += 30.0;
        // If mean residual across open bins is small (bins nearly full), a new bin is reasonable
        score -= mean_residual.min(100.0) * 0.2;
    }

    // Slight progression term: later in the stream, prefer consolidating
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward when next item fits into post_residual exactly-ish.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            let gap = post_residual as f64 - nxt;
            // Perfect 2-step fill is heavily rewarded
            score -= 45.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 30.0; // exact two-item completion
            }
        } else {
            // next item cannot follow here: penalize leftover dead space
            score += 0.5 * post_residual as f64;
        }
    }

    // Relative residual vs mean: prefer tighter-than-average bins
    score += 0.35 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it moderately unattractive unless current bin fit is terrible
    if bin_residual == bin_capacity {
        score += 18.0 + 0.2 * (post_residual as f64);
    }

    // Prefer filling bins with large residual relative to capacity (avoid many slightly-used bins)
    score += 0.15 * (bin_residual as f64 / bin_capacity as f64) * (bin_capacity - post_residual) as f64;

    // Early stream: be slightly more willing to open bins (spread risk)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post residual).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Penalize dead space that is too small to hold typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits in the post residual,
    // reward this bin; otherwise penalize slightly.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 8.0 + 0.05 * next_item_size as f64;
        } else {
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Time horizon: early in the stream, prefer opening new bins less
    // (consolidate); late, tolerate more bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Global state: many open bins -> penalize new-bin-like high residuals;
    // few open bins -> allow looser packing.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Compare against mean residual: bins with residual far above mean
    // (wasteful large gaps) get penalized.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.05;

    // New-bin candidate handling: empty bin gets a mild baseline penalty so
    // it only wins when open bins are genuinely poor fits.
    if bin_residual == bin_capacity {
        score += 12.0 - progress * 6.0;
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Exact-fill reward.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: penalize wasted space, with non-linear (quadratic) growth
    let mut score = pr as f64 * (1.0 + 0.8 * x * x);

    // Stream-progress coupling: later in the stream, tight fits matter more;
    // polynomial interaction of progress with normalized residual
    let t = progress;
    score += 12.0 * t * x * (1.0 - x) * (1.0 - x);
    score -= 20.0 * t * t * x * x; // reward very tight fits as stream matures

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * t;
    }

    // Lookahead coupling: reward residual that matches the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let diff = x - nx;
        score -= 8.0 * (-diff * diff * 10.0).exp();
        // penalize leaving residual slightly above next item (dead space)
        if x > nx && x - nx < 0.1 {
            score += 6.0 * (0.1 - (x - nx)) * 10.0;
        }
    }

    // Spread penalty: bins far from mean residual create fragmentation
    let dev = (pr - mean_residual).abs() / cap;
    score += 5.0 * dev * dev;

    // Mild penalty for opening a new bin when others fit
    if bin_residual == bin_capacity && open_bins_count > 0 && fitting_bins_count > 0 {
        score += 8.0 + 10.0 * x * (1.0 - t);
    }

    // Reward filling bins nearly completely, especially early
    score -= 6.0 * (1.0 - t) * (1.0 - x) * (1.0 - x);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which fraction-of-capacity band it falls in.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post = post_residual;

    // Dead-space penalty: residuals below the smallest item size are unusable.
    if post < 10 && post > 0 {
        score += 60.0;
    }
    // Perfect fit reward.
    if post == 0 {
        score -= 45.0;
    }

    // Harmonic bands: prefer landing on residual values that are multiples of
    // common divisors (highly composite residuals are easier to fill later).
    if post % 50 == 0 && post > 0 {
        score -= 25.0;
    } else if post % 25 == 0 && post > 0 {
        score -= 15.0;
    } else if post % 10 == 0 && post > 0 {
        score -= 8.0;
    } else if post % 5 == 0 && post > 0 {
        score -= 3.0;
    }

    // Band-based shaping: residual in (0, 1/8 C] is nearly dead space.
    if post > 0 && post <= eighth {
        score += 30.0;
    } else if post <= quarter {
        score += 12.0;
    } else if post <= 2 * quarter {
        score -= 6.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 55.0;
        } else if next_item_size <= post {
            let n = next_item_size as f64;
            // Reward smooth continuation, penalize leaving awkward gaps.
            let gap = (post - next_item_size) as f64;
            score += gap * 0.35;
            if gap < 10.0 {
                score += 20.0;
            }
        } else {
            // Next item won't fit here: slight penalty unless residual is small.
            score += 5.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid forcing a bad fit.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 3 {
        // Many alternatives: be picky, demand tighter fits.
        score += 4.0;
    }

    // New-bin candidate: only attractive when open bins are mostly full
    // (mean residual low) or the item is large.
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        let openness = (mean_r / cap).clamp(0.0, 1.0);
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / cap;
        // Base cost of opening a new bin, discounted when open bins are crowded.
        score = cap * 0.62 - openness * 30.0 + item_frac * 20.0 + progress * 8.0;
        if post_residual == bin_capacity {
            // Large item in a fresh bin is fine.
            score -= 10.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.35;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are worse than moderate gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Post-residual that cannot fit the smallest possible item is dead space.
    if post_residual > 0 && post_residual < 1 {
        score += 30.0;
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when the item is large relative to
    // capacity or open-bin pressure is low; penalize default new bins otherwise.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64).ln().max(1.0);
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 15.0 + 20.0 * (1.0 - fill_ratio) + 10.0 * progress - 5.0 * pressure;
        // If next item is small, a fresh bin is more valuable.
        if next_item_size > 0 && (next_item_size as f64) <= mean_residual {
            score -= 10.0;
        }
    } else {
        // Prefer bins whose residual is close to mean (balanced packing),
        // slight preference for tighter bins.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
    }

    // Lookahead: if post-residual can exactly fit the next item, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // If post-residual can't fit next item but bin could have, penalize mildly.
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Open-bin pressure: more open bins -> favor filling existing ones.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a snug fit: item nearly fills the bin.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness;

    // 2-step lookahead: if the next item fits exactly into post_residual,
    // this bin becomes perfectly packed over two steps.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let next_waste = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - next_waste / (bin_capacity as f64));
        } else {
            // Next item cannot use this residual: penalize large leftover space
            // proportionally to how unusable it is.
            let unusable = (next_item_size - post_residual) as f64;
            score += 0.3 * unusable.min(50.0);
        }
    }

    // Compare against mean residual: bins tighter than average are good targets.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Early in the stream, be more willing to use open bins rather than spawn
    // many half-empty bins; late in the stream, tight fits dominate anyway.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - progress);

    // Mild penalty for leaving a residual that is too small for any plausible
    // item (dead space below the minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Prefer denser packing when many bins are open (consolidation pressure).
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: relative fill of the bin.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 60.0 * fill * fill;

    // Penalize creating tiny unusable dead space (waste pockets).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: bonus if next item fits the post-residual exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 30.0 * chain;
    } else if next_item_size > post_residual && next_item_size > 0 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current fit is bad or bins are few.
    if bin_residual == bin_capacity {
        let bad_fit = fill < 0.5;
        if bad_fit || open_bins_count == 0 {
            score -= 20.0;
        } else {
            score += 35.0 + 0.5 * open_bins_count as f64;
        }
    }

    // Time horizon: early on, consolidate; late, keep flexibility.
    let t = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - t) * mean_residual * 0.15;
    score += t * post_residual as f64 * 0.1;

    // Mildly prefer bins below mean residual (balance load).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.35 * progress * progress);

    // Penalize large wasted space quadratically, amplified late in the stream
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) with a cubic decay term
    score -= 20.0 * (1.0 - norm_pr).powi(3) * (1.0 - norm_item);

    // Lookahead coupling: reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs() / cap;
        score -= 8.0 * (1.0 - gap).powi(2);
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mild penalty for proliferation of open bins early on
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Deviation from mean residual: prefer bins near the mean (smooth coupling)
    score += 0.1 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "nice"
    // residue classes (multiples of small denominators) are more reusable.
    let post = post_residual;
    if post > 0 {
        let class_bonus: f64 = if post % 10 == 0 {
            -12.0
        } else if post % 5 == 0 {
            -6.0
        } else if post % 25 == 0 {
            -15.0
        } else if post % 2 == 0 {
            -2.0
        } else {
            4.0 // odd residuals tend to be dead space
        };
        score += class_bonus;
    } else {
        // Perfect fill is ideal
        score -= 30.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item
    if post > 0 && post < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item fits the post residual,
    // penalize modulo mismatch between next_item_size and post_residual.
    if next_item_size > 0 {
        if next_item_size <= post {
            score -= 10.0;
            if post % next_item_size == 0 {
                score -= 8.0; // next item tiles the residual exactly
            }
        } else {
            let gap = next_item_size - post;
            score += (gap as f64) * 0.3; // near-miss residual is wasteful
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when current bin would
    // leave an awkward residual relative to capacity fractions.
    if bin_residual == bin_capacity {
        // Fresh bin baseline: slightly worse than a good fit, better than bad fit
        score += 15.0;
        // Late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // If many open bins already, discourage opening more
        score += open_bins_count as f64 * 0.5;
    }

    // Prefer bins tighter than the mean residual (better packing)
    score -= (mean_residual - bin_residual as f64) * 0.15;

    // Integer-division threshold: residual in [item_size, item_size+9] is a
    // "same decade" fit, slightly favored.
    if post < 10 && bin_residual >= item_size {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for any future item (min item size assumed ~1..100 unknown, but small
    // gaps < 12 are practically dead) get a heavy penalty.
    if post_residual > 0 && post_residual < 12 {
        score += (12 - post_residual) as f64 * 40.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to residual (small waste fraction).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 25.0;

    // Open-bin pressure: with many open bins, prefer reusing existing bins.
    score += open_bins_count as f64 * 3.0;

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly
    // (large waste) or the next item would benefit from a fresh bin.
    if bin_residual == bin_capacity {
        score += 45.0;
        if post_residual >= next_item_size as u32 && next_item_size > 0 {
            score -= 55.0; // fresh bin can host the next item too
        }
        if fit_ratio > 0.7 {
            score += 30.0; // current fit was already good, keep it
        }
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 15.0; // dead space relative to lookahead item
    }

    // Mild mean-residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Late-stream tightening: waste matters more as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact 2-step lookahead match: post_residual equals next item size -> perfect packing.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match: next item still fits into the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let tightness = (post_residual - next_item_size) as f64;
        score -= 25.0 - tightness * 0.5; // closer match => bigger reward
    }
    // Post residual too small for the lookahead item: dead space penalty.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Compare against mean residual: leaving more than average is wasteful.
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += (pr - mean_residual) * 0.6;
    } else {
        score -= (mean_residual - pr) * 0.4;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when open bins fit well (post residual >= next item).
    if bin_residual == bin_capacity {
        let mut penalty = 30.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            penalty += 50.0; // an open bin already gives a good 2-step fit
        }
        if fitting_bins_count > 0 {
            penalty += 15.0;
        }
        // Late in the stream, new bins are less worthwhile.
        let progress = step_index as f64 / total_items.max(1) as f64;
        penalty += progress * 20.0;
        score += penalty;
    }

    // Slight preference for tighter residual usage overall.
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fill_ratio;

    // Penalize large dead space after placement (unusable for typical items).
    if post_residual > 0 && post_residual < 10 {
        score -= 4.0; // small gap is fine
    } else if post_residual >= 10 {
        score += 0.05 * (post_residual as f64 - 9.0);
    }

    // Lookahead: reward if next item fits the post residual (chain packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 5.0 + 0.05 * next_item_size as f64;
        } else if next_item_size > post_residual {
            score += 1.5 * (next_item_size - post_residual) as f64 / 20.0;
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    } else if fitting_bins_count > 1 {
        score += 0.5 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: only attractive when item barely fits nothing well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_if_open = (bin_residual - item_size) as f64;
        // Open a new bin when the item is large (would leave tiny gap) or late in stream.
        score = 20.0 + waste_if_open - 6.0 * (item_size as f64 / 100.0) - 4.0 * progress;
        if fitting_bins_count == 0 {
            score -= 30.0; // no open bin fits; must open new bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 3.0; // room for lookahead in fresh bin
        }
    }

    // Global state coupling: many open bins with high mean residual -> discourage
    // spreading; prefer filling existing bins.
    if bin_residual < bin_capacity {
        score += 0.02 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    }

    // Mild time-horizon scaling: early in stream, be slightly conservative about
    // tiny residuals (more items coming), late in stream prefer exact fits more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.02 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: prefer tight fits via smooth polynomial shaping of post-residual.
    let mut score = pr * (1.0 + 0.8 * x * x) - 30.0 * (1.0 - x) * (1.0 - x) * (1.0 - x);

    // Stream-progress coupling: early on, tolerate loose fits (favor spreading);
    // later, penalize waste more strongly.
    score += 40.0 * progress * x * (1.0 - progress + 0.25);

    // Dead-space penalty for residuals too small to fit typical future items.
    let dead = (1.0 - x).max(0.0) * (x.max(0.0)) * 4.0; // peaks near x=0.5
    score += 20.0 * dead * (0.5 + progress);

    // Lookahead: reward leaving room for the next item (smooth interaction).
    let nxs = next_item_size as f64;
    if nxs > 0.0 {
        let diff = (pr - nxs) / cap;
        score -= 25.0 * (-diff * diff * 8.0).exp();
        // Penalize if next item barely fits (creates near-dead bin).
        let tight = (pr - nxs).max(0.0) / cap;
        score += 15.0 * tight * (1.0 - tight) * progress;
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0 * (1.0 - 0.5 * progress);
    }

    // Mean residual context: if this bin is far from mean, mild penalty.
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate: keep it competitive only when open bins are poor fits.
    let is_new = (bin_residual as f64 - cap).abs() < 1e-6 && post_residual == bin_residual;
    if is_new {
        score += 5.0 + 45.0 * progress * (1.0 - progress);
        if fitting_bins_count <= 1 {
            score -= 60.0;
        }
    }

    // Slight preference for reusing bins when many are open.
    score += 0.05 * open_bins_count as f64 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover is "usable" (large or
    // exactly divisible into common item sizes) are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual;

    // Reward post_residuals divisible by 10 (harmonic with typical item sizes)
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 3.0;
    }

    // Penalize dead space: residuals too small for the smallest plausible item
    if pr > 0 && pr < 10 {
        score += 15.0;
    }

    // Perfect fit is ideal
    if pr == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            // next fits: leftover class after next placement
            let pr2 = pr - next_item_size;
            if pr2 % 10 == 0 {
                score -= 8.0;
            }
            score += pr2 as f64 * 0.3;
        } else {
            // next item won't fit here: mild penalty proportional to overshoot class
            let gap = (next_item_size - pr) % 20;
            score += 2.0 + gap as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current residuals are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - (mean_residual % 10.0)) / cap;
        score = cap * 0.55 + fragmentation * 20.0 - progress * 5.0;
        if fitting_bins_count <= 1 {
            score += 30.0; // no real alternative anyway; keep open-bin preference
        }
    }

    // Tightness reward: prefer bins that become nearly full
    let fill = 1.0 - (post_residual as f64) / cap;
    score -= fill * 8.0;

    // Mild penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is smaller than the smallest plausible item (1..100 stream),
    // treat gaps < 12 as nearly worthless, and gaps < 25 as partially wasted.
    if post_residual > 0 {
        if post_residual < 12 {
            score += 60.0; // pure dead space
        } else if post_residual < 25 {
            score += 25.0; // mostly wasted
        } else if post_residual < 40 {
            score += 8.0;  // mildly awkward
        }
    }

    // Reward tight fits (post_residual small relative to item_size).
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 30.0 * tightness;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage proliferating bins late in the stream.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += 0.8 * open_bins_count as f64 * (0.5 + progress);

    // Last chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current item
    // is large and the stream is early (future items can share the fresh bin).
    if bin_residual == bin_capacity {
        let early_bonus = 1.0 - progress;
        let large_item = item_size as f64 >= 0.6 * bin_capacity as f64;
        if !large_item {
            score += 45.0; // don't open new bins for small items
        } else {
            score += 10.0 - 20.0 * early_bonus; // early large items justify fresh bins
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_tight = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - next_tight / (bin_capacity as f64));
    }
    // If next item would be stranded by the post residual, penalize.
    if next_item_size > post_residual && next_item_size > 0 && post_residual < 12 {
        score += 15.0;
    }

    // Mean residual coupling: prefer bins whose residual is below average (more filled).
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact-ish fits (low post residual) more aggressively.
    let fit_quality = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * fit_quality * fit_quality;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        let lookahead_match = 1.0 - (gap / bin_capacity as f64).min(1.0);
        score -= 30.0 * lookahead_match * lookahead_match;

        // Perfect chain: next item exactly fills this bin afterwards.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving residuals that are too small for the next item (dead space).
        if post_residual > 0 && post_residual < next_item_size {
            score += 15.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score -= 30.0 * fit_quality;
    }

    // Relative to mean residual: prefer bins that are already tighter than average.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins fit poorly.
    if bin_residual == bin_capacity {
        score += 35.0;
        // More open bins already -> slightly cheaper to reuse them.
        score += open_bins_count as f64 * 0.5;
        // If the next item is large, a fresh bin gives flexibility.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Late in stream: consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fit_quality;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize dead space: residuals too small to hold typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // nearly unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Lookahead: bonus if the next item still fits after this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward proportionally to how much room remains for the next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here afterwards; mild penalty scaled by gap.
            score += 8.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: empty bin gets a base cost so it's only
    // chosen when open bins would waste too much space.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Opening early in the stream is cheaper (more future items to fill it).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 * progress;
        // More open bins already => new bin less attractive.
        score += 2.0 * open_bins_count as f64;
    }

    // Global state coupling: prefer bins whose residual is close to the mean
    // (keeps residuals balanced) but reward using larger-than-average bins.
    let diff = bin_residual as f64 - mean_residual;
    score -= 0.15 * diff; // favor fuller-than-average bins
    score += 0.05 * diff.abs(); // slight penalty for extremes

    // Encourage filling bins as the stream progresses (less time to open many bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: prefer small post-residual, with a smooth non-linear penalty
    // on mid-range waste (dead space that is neither tight nor empty).
    let mut score = pr as f64 * (1.0 + 0.8 * x * (1.0 - x) * 4.0);

    // Smooth stream-progress coupling: late in the stream, tight packing
    // matters more; early on, spreading load across bins is fine.
    let tightness = 0.5 + 0.9 * progress;
    score *= (1.0 + tightness * x * x);

    // Reward near-perfect fits via a smooth Gaussian-like term.
    score -= 12.0 * (-(x * x) / 0.02).exp();

    // Last-chance bin: strong smooth reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - x);
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr as f64 {
            let slack = (pr - nx) / cap;
            score -= 8.0 * (1.0 - slack) * (1.0 - progress * 0.5);
        } else {
            // Penalize leaving a residual that the next item cannot use,
            // scaled by how close the next item is to fitting (smooth).
            let gap = (nx - pr) / cap;
            score += 6.0 * (-gap * 20.0).exp();
        }
    }

    // Mild penalty when this bin is far below the mean residual (unbalanced use),
    // smoothed by open-bin count pressure.
    let mean_gap = (mean_residual - pr) / cap;
    score += 2.0 * mean_gap * mean_gap * (open_bins_count as f64).ln();

    // Slight preference for consolidating into fewer bins early on.
    score += 0.5 * open_bins_count as f64 * progress;

    // New-bin candidate: keep it competitive only when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: multiples of 10 are "harmonic" slots
    // that many item sizes (drawn from a 1..100 grid) can still fill.
    let post = post_residual;
    let harmonic = post % 10 == 0;
    let small_dead = post > 0 && post < 10;

    if harmonic {
        score -= 6.0 * (post as f64 / 10.0).min(5.0);
    } else {
        // non-harmonic residual is harder to fill: penalize proportionally
        score += 3.0 * ((10 - post % 10) as f64) / 10.0;
    }
    if small_dead {
        score += 12.0; // dead space < 10 is nearly unusable
    }

    // Integer-division thresholds: can next item land in post residual?
    if next_item_size > 0 {
        if next_item_size <= post {
            // good chaining: reward more if post is a multiple of next size class
            let class = post / next_item_size.max(1);
            score -= 4.0 + 0.5 * class as f64;
            if post % next_item_size.max(1) == 0 {
                score -= 3.0; // perfect modular chain
            }
        } else {
            score += 2.0; // lookahead won't fit here
        }
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless residuals everywhere are bad
    if bin_residual == bin_capacity {
        let mean_frac = mean_residual / bin_capacity as f64;
        if mean_frac > 0.35 {
            score += 15.0;
        } else {
            score += 4.0;
        }
        // early stream: opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * (1.0 - progress);
    }

    // Prefer tighter fits overall
    score -= 2.0 * (1.0 - (item_size as f64 / bin_residual.max(1) as f64));

    // Many open bins: encourage consolidation
    if open_bins_count > 4 {
        score -= 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps harshly.
    // Gaps below the minimum item size are pure waste.
    if post_residual < 10 {
        score += 200.0;
    } else if post_residual <= 20 {
        score += 60.0;
    } else if post_residual <= 35 {
        score += 15.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Dead space is worse late in the stream (fewer chances to fill it).
    let progress = step_index as f64 / total_items as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 150.0 * progress;
    }

    // Open-bin pressure: favor consolidating into existing bins when many are open.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 30.0;
    }
    // If next item cannot fit in the gap, the gap is more likely to become dead space.
    if next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual > 0 {
        score += 20.0;
    }

    // New-bin candidate should only win when it offers a clean slate versus bad fits.
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 0.3;
    }

    // Slight preference to fill bins with larger residual (tighter packing).
    score += (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: if the next item can exactly fill the post-residual, huge reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        }
        // If post_residual cannot fit the next item, penalize (dead space risk)
        // unless it's small (tight fit is fine).
        if post_residual > 0 && post_residual < next_item_size {
            score -= 50.0; // small dead space, acceptable
        } else if post_residual >= next_item_size && post_residual > 0 {
            // post-residual can host next item: mild reward
            score -= 100.0;
        }
    } else {
        // Last item: prefer zero residual strongly (already covered) else small residual
        score += 0.0;
    }

    // Penalize large leftover relative to mean residual (fragmentation).
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && post_residual as f64 <= score {
        score -= 300.0;
    }

    // New-bin candidate: make it moderately expensive unless item is large relative
    // to residual (poor fit into open bins).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 120.0;
        // If item nearly fills the bin, opening is good.
        if item_size * 2 >= bin_capacity {
            score -= 150.0;
        }
        // Early in stream, new bins are cheaper (build inventory of bins).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 80.0 * (1.0 - progress);
    }

    // Slight preference for tighter fits overall.
    score += (bin_residual - item_size) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits: reward near-perfect packing via a nonlinear dead-space penalty.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio > 0.85 {
        score -= 18.0 * fit_ratio;
    } else if fit_ratio > 0.6 {
        score -= 6.0 * fit_ratio;
    }

    // Penalize leaving awkward small dead space that few items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: favor bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Even better: next item would fill this bin nearly exactly afterwards.
        let second_post = post_residual - next_item_size;
        if second_post <= 5 {
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space that the next item cannot use.
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Crowding: with many open bins, prefer filling existing ones; with few,
    // spreading is less harmful.
    let crowd = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += crowd * (post_residual as f64 - mean_residual) * 0.5;

    // Time horizon: early in the stream, keep residual flexibility (spread out);
    // late in the stream, pack tight and close bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= t * 10.0 * fit_ratio;
    score += (1.0 - t) * (post_residual as f64 / bin_capacity as f64) * 5.0;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Baseline new-bin cost scales with how many bins could fit the item.
        let fallback = 55.0 + 8.0 * fitting_bins_count as f64;
        // Late in the stream, opening a fresh bin is cheaper than scattering.
        score = fallback - t * 20.0;
        // If the item is huge relative to capacity, a fresh bin is more natural.
        if item_size as f64 / bin_capacity as f64 > 0.7 {
            score -= 15.0;
        }
        // If next item also large, fresh bin gives room.
        if next_item_size >= 40 && item_size + next_item_size > 100 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let next_norm = next_item_size as f64 / cap;

    // Base: prefer small post-residual, with non-linear emphasis on tight fits
    let mut score = norm_pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Smooth coupling: waste penalized more as stream progresses
    score += 3.0 * progress * norm_pr * norm_pr;

    // Reward filling a bin well when it's the last fitting bin
    if fitting_bins_count == 1 {
        score -= 1.5 + 2.0 * norm_item;
    }

    // Penalize leaving dead space that next item cannot use
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0) / cap;
        score += 2.5 * gap * gap;
        // Reward post-residual close to next item size (perfect lookahead fit)
        let fit_err = (pr - next_item_size as f64).abs() / cap;
        score -= 1.2 * (1.0 - fit_err.min(1.0)) * (1.0 - fit_err.min(1.0));
    } else {
        // Last item: strongly prefer zero post-residual
        score += 4.0 * norm_pr * norm_pr;
    }

    // Mild pressure toward consolidating among many open bins
    score += 0.3 * open_bins_count as f64 / (total_items.max(1) as f64).sqrt() * (1.0 - norm_item);

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let bad_fit = (mean_residual - norm_item * cap).abs() / cap;
        score = 2.0 + 3.0 * (1.0 - bad_fit.min(1.0)) - 1.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = (post_residual as f64).powf(1.25);

    // Harmonic class of post_residual: dead space in coarse residue classes.
    let residue_class = post_residual % 10;
    score += match residue_class {
        0 => -3.0,                       // perfectly divisible leftover: reusable
        1..=5 => 1.5,                    // awkward sliver
        6..=9 => 0.5,
        _ => 0.0,
    };

    // Lookahead: reward bins that can also host the next item (chained fit).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + (next_item_size as f64) * 0.05;
        } else {
            // next item won't fit here: penalize proportionally to the gap
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin before opening a new one: strong reward.
    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New empty bin candidate: penalize opening a bin when open bins
    // still carry usable residual capacity.
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.30 + (open_bins_count as f64) * 0.5;
        // If nothing else fits, opening is inevitable: soften penalty.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        // Early in the stream, having fresh bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 5.0;
    }

    // Mild preference for fuller bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_capacity - post_residual) as f64 * 0.02 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }
    // Reward good fits (small post_residual relative to item)
    let fit_ratio = post_residual as f64 / (item_size as f64 + 1.0);
    score -= 40.0 / (1.0 + fit_ratio);

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0;
    }
    // Open bin pressure: discourage opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 2.0;
    } else {
        score -= 5.0;
    }

    // Mean residual coupling: prefer bins near mean residual
    score += ((bin_residual as f64 - mean_residual) / 10.0).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter fit (smaller post_residual) is better.
    // Normalize dead space relative to capacity.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let dead_frac = post / cap;

    // Strong penalty for large unusable dead space (nonlinear).
    score += 40.0 * dead_frac * dead_frac;

    // Aggressive 2-step lookahead: reward if the NEXT item fits exactly
    // into the post-residual (perfect chain), penalize near-miss chains.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = post - next;
        if diff == 0.0 {
            // Perfect match: chain the next item exactly.
            score -= 60.0;
        } else if diff > 0.0 && diff <= 10.0 {
            // Next item fits with small slack: good chain.
            score -= 30.0 - 2.0 * diff;
        } else if diff > 0.0 {
            // Next item fits but leaves slack: mild reward decaying with slack.
            score -= (20.0_f64 * (-diff / 30.0).exp()).max(0.0);
        } else {
            // Next item does NOT fit in this bin after placement:
            // penalize proportionally to how badly it misses (creates dead space).
            score += (-diff).min(40.0) * 0.8;
        }
    } else {
        // Last item: just minimize post_residual.
        score -= 10.0;
    }

    // Relative-to-mean-residual coupling: prefer bins whose residual is
    // below average (tighter bins), so loose bins get consumed first.
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.3;

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it moderately attractive so we open fresh
    // bins when no open bin offers a decent fit, but not so attractive
    // that we fragment needlessly.
    if bin_residual == bin_capacity {
        score = post_residual as f64 + 15.0;
        if next_item_size > 0 {
            let next = next_item_size as f64;
            if (next - post).abs() <= 1.0 {
                score -= 50.0; // fresh bin perfectly sized for next item too
            }
        }
        // Early in the stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post-residual gets nonlinear bonus).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space that cannot fit the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Perfect fit gets a huge reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size {
            score -= 8.0;
        } else {
            // Next item won't fit here; penalize if we leave awkward remainder.
            score += 6.0;
        }
    }

    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    if open_bins_count > 2 {
        let fill_pressure = mean_residual / bin_capacity as f64;
        score -= 10.0 * fill_pressure;
    }

    // Time horizon: early in stream, be more willing to open new bins (keep options open);
    // late in stream, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 15.0 * progress;
        // But early on, a fresh bin is attractive for large items.
        if item_size > 60 {
            score -= 10.0 * (1.0 - progress);
        }
    } else {
        // Existing bins favored more late in the stream.
        score -= 12.0 * progress;
    }

    // Mild penalty for very large item in nearly full bin causing fragmentation risk.
    if item_size as f64 > 0.7 * bin_residual as f64 && post_residual > 0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: post-residual, with smooth non-linear polynomial coupling to progress
    let mut score = pr;

    // Polynomial decay of residual value as stream progresses:
    // late in the stream, tight fits matter more; dead space penalized super-linearly
    let tightness = 1.0 - norm_pr * norm_pr;
    score += (2.0 + 6.0 * progress) * (norm_pr * norm_pr) * cap;

    // Reward near-perfect fits smoothly (quartic bump around small residual)
    score -= 12.0 * tightness * tightness * (1.0 - progress);

    // Coupling with mean residual: prefer bins below mean (tighter than average)
    score += 1.5 * (mean_residual - pr) / cap * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, reward strongly, smoothly scaled
    let last_chance = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
    score -= 8.0 * last_chance * (0.5 + 0.5 * progress);

    // Lookahead: reward if next item fits into post-residual, penalize near-miss waste
    if next_item_size > 0 {
        let fits_next = (pr >= next_item_size as f64) as i32 as f64;
        let gap = (pr - norm_next * cap).abs() / cap;
        score -= 6.0 * fits_next * (1.0 - gap * gap) * (1.0 - progress);
        score += 3.0 * (1.0 - fits_next) * norm_next * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins early
    score += 0.3 * open_bins_count as f64 / (1.0 + total_items as f64 * 0.01) * (1.0 - progress);

    // New-bin candidate: only attractive when item is large relative to capacity
    let is_new = (bin_residual == bin_capacity) as i32 as f64;
    score += is_new * (5.0 + 10.0 * (1.0 - norm_item)) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "reusable"
    // residue classes (multiples of 10 / 25) are favored.
    let pr = post_residual;
    if pr > 0 {
        let cls = pr % 10;
        match cls {
            0 => score -= 8.0,
            5 => score -= 3.0,
            2 | 8 => score -= 1.0,
            1 | 9 => score += 4.0,
            _ => score += 2.0,
        }
        // Dead-space penalty: tiny leftovers are nearly useless.
        if pr < 10 {
            score += 6.0 * (10 - pr) as f64 / 10.0;
        }
    } else {
        // Perfect fit is ideal.
        score -= 20.0;
    }

    // Integer-division threshold on post_residual: leftovers >= half capacity
    // are excellent hosts for future items.
    if pr >= bin_capacity / 2 {
        score -= 10.0;
    } else if pr >= bin_capacity / 4 {
        score -= 4.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0;
        } else if next_item_size <= pr {
            let fit_q = pr / next_item_size.max(1);
            score -= 3.0 * fit_q.min(3) as f64;
            // Harmonic pairing: next item leaves a multiple-of-10 residue too.
            if (pr - next_item_size) % 10 == 0 {
                score -= 4.0;
            }
        } else {
            // Next item won't fit here; slight penalty if this is the last fitting bin.
            if fitting_bins_count == 1 {
                score += 5.0;
            }
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 7.0;
    }

    // New-bin candidate: penalize opening fresh bins early / when decent fits exist,
    // reward it late in the stream or when residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 12.0 - 10.0 * progress;
        if mean_residual < cap * 0.25 {
            score -= 5.0; // fragmented state: fresh bin is fine
        }
        if post_residual == pr && pr == bin_capacity {
            // empty-bin base score: keep near mean residual reference
            score += mean_residual * 0.1;
        }
    }

    // Mild tie-break toward concentrating load in fewer bins.
    score += open_bins_count as f64 * 0.05;

    // Progress-aware waste scaling: waste matters more as stream continues.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest item are pure waste.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // exact fill is perfect, but guard against negative-ish weirdness
    }
    if post_residual > 0 && post_residual < min_item.max(1) {
        score += 500.0;
    }
    // Small leftover gaps (< 10) are dead space; penalize proportionally to how dead they are.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    // Mid-range gaps (10..30) are semi-usable: mild penalty scaled by tightness.
    if post_residual >= 10 && post_residual < 30 {
        score += (30 - post_residual) as f64 * 0.8;
    }
    // Perfect or near-perfect fits get strong rewards.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits in the post residual, reward keeping this bin viable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual can't host the next item: penalize dead space relative to next need.
        score += 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, discourage new bins and tight fills less.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, reduced when few bins are open or stream is early.
        score = score.max(0.0) + 30.0 + 5.0 * open_bins_count as f64 * (1.0 - progress);
        // If no existing bin fits well (this call only happens as candidate), keep it costly
        // unless the item is large relative to capacity.
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    } else {
        // Slight preference for bins with residual close to mean (balanced packing).
        score += 0.05 * ((bin_residual as f64 - mean_residual).abs());
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item can still fit with small slack
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / 100.0);
    }
    // Next item cannot fit: dead space penalty grows with unusable gap
    else if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += 12.0 * (gap / 100.0);
    }

    // Reward tight fits relative to current item
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness;

    // Penalize creating small unusable residuals (< 10, min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New empty bin candidate: penalize unless current open bins are crowded
    if bin_residual == bin_capacity {
        let crowded = if open_bins_count == 0 { 0.0 } else { mean_residual / bin_capacity as f64 };
        score += 25.0 - 30.0 * crowded;
    }

    // Compare against mean residual: bins with residual far from mean are less flexible
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 3.0 * (dev / 100.0);

    // Late in stream: consolidate more aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with mild nonlinearity.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tight * tight;

    // Dead-space penalty: post_residual too small for the smallest future item is wasted.
    if post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0;
        }
        // Bonus if after placing current item, next item fits snugly.
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score += 0.15 * gap;
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when the item is large and
    // existing residuals are fragmented.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fragmentation = mean_residual / (bin_capacity as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Open a new bin if item is big and mean residual is small (poor fits elsewhere).
        let open_bonus = 60.0 * item_frac - 80.0 * fragmentation;
        score += 20.0 - open_bonus;
        // Late in the stream, avoid opening new bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
    }

    // Global state: many open bins -> consolidate into existing ones.
    let open_pressure = (open_bins_count as f64).ln() * 4.0;
    if !is_new_bin {
        score -= open_pressure * (1.0 - tight);
    }

    // Prefer bins whose residual deviates favorably from the mean (tighter than average).
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.2 * dev;

    // Mild time horizon modulation: early stream, be greedy for tight fits;
    // late stream, prioritize keeping bins usable.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * tight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1)

    // Base: minimize waste, with a non-linear (quartic) penalty on dead space
    let mut score = pr as f64;
    score += 40.0 * (1.0 - x) * x * x * x * cap; // penalize small unusable residuals smoothly

    // Smooth interaction: waste penalty grows with stream progress
    score += 30.0 * progress * (x - 0.5) * (x - 0.5) * cap;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= 20.0 * progress * (1.0 - x) * (1.0 - x) * item_size as f64;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0 + 40.0 * progress;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this bin
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 * (1.0 - gap / cap) * (1.0 - gap / cap);
    }

    // Prefer bins with residual below the mean (consolidate waste) via smooth coupling
    score += 0.15 * (bin_residual as f64 - mean_residual) * (0.5 + progress);

    // Mild penalty on many open bins to discourage fragmentation
    score += 0.5 * open_bins_count as f64 * x;

    // New-bin candidate: neutral-ish baseline, penalized slightly when good fits exist
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod small divisors reveal
    // "usable" dead-space classes. Residuals in classes like mod 10 == 0
    // are more likely reusable by future items.
    let cap_frac = post_residual as f64 / bin_capacity as f64;

    // Penalize residuals that fall into awkward harmonic classes.
    let r = post_residual;
    if r > 0 {
        if r % 10 == 0 {
            score -= 12.0; // perfectly reusable class
        } else if r % 5 == 0 {
            score -= 6.0;
        } else if r % 3 == 0 {
            score -= 2.0;
        } else {
            score += 4.0; // prime-ish / awkward residual
        }
        // Integer-division thresholds: tiny residuals are dead space.
        if r / 10 == 0 {
            score += 20.0;
        } else if r / 20 == 0 && r > 10 {
            score += 5.0;
        }
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic match reward, stronger when it's an exact class match.
            let gap = post_residual - next_item_size;
            if gap % 10 == 0 {
                score -= 18.0;
            } else {
                score -= 9.0;
            }
        } else if next_item_size <= bin_residual {
            // Next item would have fit better before this placement.
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Fractional capacity coupling: prefer filling bins past half capacity.
    if cap_frac < 0.25 && post_residual > 0 {
        score += 6.0 * (0.25 - cap_frac);
    } else if cap_frac >= 0.25 && cap_frac < 0.5 {
        score -= 4.0;
    }

    // Progress-aware new-bin logic: early in the stream, an empty new bin
    // (post_residual == capacity) is mildly penalized; late, less so.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * progress;
        // But if no open bin fits well, allow new bin when item is large.
        if item_size > bin_capacity / 2 && fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Mean residual context: if this bin is far below mean residual, it is
    // already fragmented; deprioritize.
    score += ((mean_residual - post_residual as f64) * 0.3).max(-10.0).min(10.0);

    // Prefer denser packing when many bins are open.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Reward using bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 25.0 * tightness;

    // Pressure from number of open bins: discourage spreading across many bins.
    score += 0.8 * open_bins_count as f64;

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item could fit in the post-residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Mean residual coupling: prefer bins below mean residual (fill emptier bins first).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: only attractive when item is huge relative to residuals
    // or no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 + 3.0 * progress;
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
