pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity as f64 - post_residual as f64) * (0.6 + 0.8 * progress);

    // Penalize dead space: very small post_residual that is still unusable is fine,
    // but medium leftovers (e.g. 20-40) waste capacity.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 0.0 } else { post_residual as f64 };
        score += dead * 0.35;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Many open bins: encourage consolidation into existing bins.
    score += open_bins_count as f64 * 1.5;

    // Lookahead: if the next item fits the post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // chain fit quality
            score -= (post_residual - next_item_size) as f64 * 0.1;
        } else if next_item_size <= bin_residual && post_residual < next_item_size {
            // this placement blocks the next item from reusing this bin
            score += 6.0;
        }
    }

    // Global residual alignment: prefer bins whose residual is near the mean
    // (keeps residual distribution homogeneous, easier future packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New-bin candidate: penalize opening a new bin unless current item is large
    // relative to capacity and no tight option exists.
    if bin_residual == bin_capacity {
        let large = item_size as f64 / bin_capacity as f64;
        score += 30.0 - 25.0 * large + 10.0 * progress;
        // If next item is small, a fresh bin is more attractive.
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_frac = item_size as f64 / cap;
    let pr_norm = pr / cap;

    // base: penalize wasted residual, non-linearly
    let mut score = pr * (1.0 + 0.8 * pr_norm * pr_norm);

    // tight-fit reward: smooth quadratic coupling of fit fraction with progress
    let tight = 1.0 - (fit_frac - 0.5) * (fit_frac - 0.5) * 4.0; // peaks at 50% fill
    score -= 12.0 * tight * (0.5 + progress);

    // dead-space penalty grows late in stream
    let dead = (pr_norm - 0.15).max(0.0);
    score += 20.0 * dead * dead * (0.3 + 0.7 * progress);

    // lookahead coupling: reward leaving room for the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let diff = pr_norm - ns / cap;
        let cover = 1.0 / (1.0 + (diff.abs() * 8.0).powi(2));
        score -= 8.0 * cover * (1.0 - progress * 0.5);
        // penalize if post-residual just misses next item
        if pr < ns {
            score += 6.0 * (ns - pr) / cap;
        }
    }

    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 5.0 * (1.0 - pr_norm);
    }

    // mild pressure to consolidate when many bins open
    score += open_bins_count as f64 * 0.15 * (1.0 - progress);

    // new-bin candidate: penalize opening a fresh bin unless residual is large
    if (bin_residual as f64 - cap).abs() < 0.5 {
        score += 10.0 + 15.0 * (1.0 - fit_frac) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "small" or
    // that fall into reusable residue classes (mod 10 granularity).
    let post = post_residual;
    let class = post % 10;
    // Residuals that are multiples of 10 are more likely to be exactly filled
    // by future items (item sizes 1..100, but 10-aligned classes are common).
    if post > 0 && class == 0 {
        score -= 6.0;
    }
    // Penalize dead-space bands: residuals too small for most items.
    if post > 0 && post < 10 {
        score += 25.0;
    } else if post > 0 && post < 20 {
        score += 8.0;
    }

    // Integer-division threshold: how many "half-capacity" chunks remain.
    let half_chunks = post / (bin_capacity / 2);
    score -= 4.0 * half_chunks as f64;

    // Coupling with next item: if next item fits exactly into post_residual,
    // this is a perfect pairing -> strong reward.
    if next_item_size > 0 && next_item_size == post {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post {
        let leftover = post - next_item_size;
        // Reward chain fits whose second-order leftover is again a small class.
        score -= 10.0 - (leftover as f64) * 0.15;
        if leftover % 10 == 0 && leftover > 0 {
            score -= 5.0;
        }
        if leftover < 10 {
            score += 6.0; // creates dead space after the chain
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are all poor fits (high mean residual waste signal).
    if bin_residual == bin_capacity {
        // Base penalty so new bins are used only when justified.
        score += 35.0;
        // If the current bin leaves a harmonically bad residual, new bin gains appeal.
        if post % 10 != 0 && post > 0 {
            score -= 10.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // Many open bins with small mean residual: reuse them.
        score += 2.0 * open_bins_count as f64 * (1.0 - mean_residual / bin_capacity as f64);
    }

    // Mild preference for tighter bins overall (best-fit flavor) modulated by
    // the residual class so exact-fill classes win ties.
    score += (bin_residual as f64) * 0.05;
    if bin_residual % 10 == 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A post_residual below ~10 is nearly worthless (min item size is 1, but
    // typical items are much larger), so push such bins far down the ranking.
    let pr = post_residual as f64;
    if post_residual > 0 {
        // dead-space zone: penalize quadratically as gap shrinks below 10
        if post_residual < 10 {
            score += 60.0 * (10.0 - pr);
        } else if post_residual < 20 {
            score += 15.0 * (20.0 - pr);
        }
    }

    // Reward tight fits: the closer post_residual is to 0 (but still usable),
    // the better. Subtract a bonus proportional to fill ratio.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin for a mediocre fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin's score is (capacity - item).
    // Make opening a new bin attractive only when the item is large (a big
    // item in a fresh bin leaves a large, reusable residual) and when open
    // bin pressure is low. Otherwise discourage proliferation of bins.
    if bin_residual == bin_capacity {
        // prefer new bin for large items: post_residual = 100 - item is small
        // for large items, so add mild penalty modulated by open bin pressure.
        score += 8.0 * (open_bins_count as f64).min(12.0);
        // early in the stream, opening bins is cheap and useful
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Open-bin pressure: many open bins with scattered residual -> prefer
    // consolidating into existing bins rather than opening more.
    score += 0.5 * open_bins_count as f64;

    // Lookahead: if the next item fits comfortably in the resulting residual,
    // reward this placement (keeps bins "compatible" with the near future).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }
    // If next item would be blocked by the residual, mild penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // Mean-residual coupling: bins far below the mean residual are poor
    // consolidation targets; bins near/above mean residual absorb slack well.
    score += 0.15 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64 - next).abs() < 1.0 {
            score -= 60.0;
        } else if post_residual as f64 >= next {
            score -= 20.0 * (next / post_residual as f64);
        } else {
            // next item won't fit here; penalize dead space relative to next size
            score += 0.3 * (next - post_residual as f64).min(50.0);
        }
    }

    // Relative to mean residual: prefer bins below-average residual (tighter bins).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when many bins are already open with slack.
    if bin_residual == bin_capacity {
        score += 40.0
            + 0.2 * open_bins_count as f64
            + 20.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // Mild penalty for leaving tiny unusable slivers.
    if post_residual > 0 && post_residual < 5 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio for dynamic time horizon.
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // ---- Core tightness preference ----
    // Reward near-perfect fits: residual 0 is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Small residuals get a nonlinear bonus (dead space penalty avoidance).
        let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 20.0 * tight * tight;
    }

    // ---- Lookahead coupling (k=2) ----
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // The next item can also fit here: strong reward for chaining.
            let chain_slack = (post_residual - next_item_size) as f64;
            score -= 15.0 + 10.0 * (1.0 - chain_slack / bin_capacity as f64);
        } else if next_item_size <= bin_residual {
            // Next item fits this bin only if we place something smaller now —
            // mild penalty for wasting space the future needs.
            score += 5.0;
        }
    }

    // ---- Last-chance bin bonus ----
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        // This is the only open bin that fits; avoid opening a new bin.
        score -= 25.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Empty bin: penalize mildly so it's used only when open bins fit badly.
        score += 12.0;
        // But if the item is large, a fresh bin is fine (big items pair well later).
        if item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
        // Late in the stream, avoid proliferating bins.
        if progress > 0.7 {
            score += 10.0 * progress;
        }
        // If many bins are open and mean residual is large, prefer filling them.
        if open_bins_count > 2 && mean_residual > item_size as f64 * 1.5 {
            score += 8.0;
        }
    }

    // ---- Global-state modulation ----
    // Prefer bins whose residual is close to the mean (balanced packing),
    // penalize outliers that hoard space.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild preference for fuller bins when many bins are open.
    if open_bins_count > 4 {
        score += 0.1 * (post_residual as f64 - mean_residual);
    }

    // ---- Small-item guard: don't burn a nearly-full bin on a tiny item ----
    if item_size <= 20 && post_residual > 40 && bin_residual < bin_capacity {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = item_size as f64 / cap;
    let nz = next_item_size as f64 / cap;
    let tight = 1.0 - pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let prog_term = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score -= 6.0 * prog_term * tight * tight * fit;
    score += 2.5 * pr * pr / (cap * cap);

    // Reward tight fits more strongly as stream progresses (smooth cubic coupling)
    score -= 8.0 * progress * progress * progress * (pr as f64).powi(2) / cap;

    // Lookahead: reward leaving room for the next item, smoothly
    if next_item_size > 0 && nz <= pr / cap {
        score -= 4.0 * nz * (1.0 - progress) * tight;
    } else if next_item_size > 0 {
        score += 3.0 * (nz - pr / cap) * (0.5 + progress);
    }

    // Last-chance bonus: smooth reward when few fitting bins
    if fitting_bins_count <= 1 {
        score -= 5.0 * (1.0 + progress);
    }

    // Mean-residual dispersion penalty (smooth quadratic)
    score += 0.05 * (pr - mean_residual).abs().powi(2) / cap;

    // New-bin candidate: mildly penalize unless post_residual is very small relative to capacity
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * (1.0 - fit) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual modulo capacity/10 buckets.
    let class = post_residual % 10;
    // Dead-space penalty: residuals in awkward harmonic classes (1..9 small slivers)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable sliver
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic coupling: post_residual divisible by next_item_size -> next item nests perfectly
    if next_item_size > 0 && post_residual > 0 {
        if post_residual % next_item_size == 0 {
            score -= 25.0;
        } else if post_residual < next_item_size {
            // next item cannot go here; penalize residual smaller than lookahead
            score += 10.0;
        }
        // modulo distance to next multiple of next_item_size
        let m = post_residual % next_item_size;
        score += (m as f64) * 0.5;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Empty-bin candidate: only attractive when current bin fits are poor
    if bin_residual == bin_capacity {
        // new bin has huge residual but opening costs; add fixed opening penalty
        score += 60.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open anyway
        }
        // open a new bin if mean residual across open bins is small relative to item
        if mean_residual < item_size as f64 {
            score -= 40.0;
        }
    }

    // Fraction-of-capacity tightness reward: prefer bins that become >80% full
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    if fill_frac >= 0.8 {
        score -= 15.0 * (fill_frac - 0.8) * 5.0;
    }

    // Integer-division threshold on post_residual: prefer residuals >= 20 (usable for typical items)
    if post_residual >= 20 {
        score -= 5.0;
    }

    // Stream progression: late in stream, be more conservative with new bins
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity && progress > 0.9 {
            score += 30.0 * progress;
        }
    }

    // Penalize spreading when many bins already open
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable
    // (items are >= 10 in classic streams; treat gaps < 10 as dead space).
    let dead_threshold = 10.0f64;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_threshold {
        score += (dead_threshold - pr) * 12.0; // heavy penalty for dead space
    }
    // Penalize gaps that cannot fit the lookahead item either (double dead space risk)
    if next_item_size > 0 && pr > 0.0 && (pr as u32) < next_item_size {
        score += pr * 0.8;
    }

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= tightness * 6.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bins pressure: discourage proliferating bins, but allow opening
    // a new bin when existing bins would create dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mild attraction toward bins with residual near mean (spread waste evenly)
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    // New-bin candidate: baseline preference so it's chosen only when
    // existing bins would be badly fragmented.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact / near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space super-linearly, scaled by capacity.
        let frac = post_residual as f64 / bin_capacity as f64;
        score += frac * frac * 120.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        // Match quality: how snugly the next item fits afterwards.
        let slack_after_next = post_residual - next_item_size;
        let next_frac = slack_after_next as f64 / bin_capacity as f64;
        score -= 60.0 * (1.0 - next_frac);
        // Bonus for chaining well: post_residual close to next_item_size.
        score -= 25.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > 0 {
        // Penalize leaving a residual that the next item cannot use,
        // especially if the wasted gap is small (worst dead space).
        let gap = post_residual as f64;
        let waste = gap.min(next_item_size as f64);
        score += 1.5 * waste;
    }

    // Relative-to-mean coupling: bins with residual far below mean are scarce
    // space; using them for tight fits is valuable.
    let rel = (bin_residual as f64) - mean_residual;
    if rel < 0.0 {
        score += 0.4 * rel; // small bins: slightly discourage unless tight fit
    } else {
        score -= 0.15 * rel.min(50.0); // roomy bins absorb loose fits
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Late in the stream, consolidate: prefer filling existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and many bins are open.
        score += 40.0 + 60.0 * progress + 0.5 * open_bins_count as f64;
        // Opening a new bin is attractive only if the item is large relative to capacity.
        score -= 30.0 * (item_size as f64 / bin_capacity as f64);
    } else if open_bins_count > 0 {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less dead space is better.
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Partial reward proportional to how well next item uses remaining space.
            let waste = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - waste / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty scaled by leftover size.
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize bins whose residual deviates far below the mean (avoid fragmenting good bins
    // when other bins have similar slack).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Time horizon: early in the stream, keep bins flexible (prefer larger post_residual);
    // late in the stream, prioritize closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * (post_residual as f64) * 0.1;
    score -= progress * 5.0;

    // New-bin candidate: acceptable early or when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted as stream progresses or when
        // many bins are open (packing pressure).
        let discount = 1.0 - 0.3 * progress;
        score = (bin_capacity as f64) * discount
            + if next_item_size > 0 && next_item_size <= bin_capacity { 0.0 } else { 10.0 };
        // If this is the only fitting option anyway, new bin is fine.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Mild bonus for using bins that are already quite full (small residual before placement).
    if bin_residual < bin_capacity {
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: prefer low post-residual, with non-linear shaping
    let mut score = r;

    // Smooth polynomial coupling of post-residual with stream progress:
    // early on, moderate residuals are tolerable; late, punish waste quadratically.
    let poly = 1.0 + 3.0 * progress * progress + 2.0 * progress * rn * rn;
    score *= poly;

    // Interaction: penalize residuals that cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if r >= nx {
            // reward residual that still fits next item, scaled by progress
            score -= (1.0 + progress) * (rn * cap - nx).min(nx) * 0.5;
        } else {
            // dead space relative to next item
            score += (nx - r) * (1.0 + 2.0 * progress) * 0.75;
        }
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0 * (1.0 + progress);
    }

    // Penalize opening new bins when many bins are open and mean residual is large
    score += (open_bins_count as f64).ln().max(0.0) * rn * 10.0 * (1.0 - progress);

    // Slight bias toward filling bins whose residual deviates from mean
    score += (rn - mean_residual / cap).abs() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual modulo 10 defines
    // "compatibility classes" with the 10..80 item granularity.
    let class = post_residual % 10;
    // Residuals in class 0 (10,20,...) are most reusable; odd/waste classes penalized.
    score += (class as f64) * 1.5;

    // Strongly prefer exact fits: post_residual == 0 is perfect packing.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        // Dead space below the minimum item size is permanently unusable.
        score += 25.0 + (10 - post_residual) as f64;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + (next_item_size as f64) * 0.25;
        } else {
            // Creating a residual the next item cannot use wastes this bin's slack.
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // offers a good (low-waste) fit. Give it a mild penalty so tight fits in
    // existing bins win, but let it win over bins with large unusable residuals.
    if bin_residual == bin_capacity {
        score += 15.0;
    } else {
        // Prefer fuller bins: tighter residual (relative) gets rewarded.
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill_ratio * 10.0;
    }

    // Late in the stream, consolidation matters more: penalize spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 1 {
        score += progress * 5.0;
    }

    // Prefer bins below the mean residual (closer to being filled up),
    // keeping a spread of usable residuals across bins.
    let dev = mean_residual - post_residual as f64;
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 35 {
        score += 5.0;
    }

    // Reward tight fits (small waste relative to bin).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins,
    // making the new-bin candidate less attractive.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64 / total_items.max(1) as f64);
    score += 2.0 * pressure;

    // New-bin candidate handling: only attractive when the item barely fits nothing well
    // or the stream is early and consolidation is not yet valuable.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // An open bin can fit: make new bin costly unless all fits are terrible.
            score += 35.0 + mean_residual * 0.3;
            if post_residual < 10 && bin_residual - item_size >= 40 {
                // current bin would leave a big usable gap but a fresh bin fits perfectly later
                score -= 5.0;
            }
        } else {
            score -= 10.0;
        }
        // Late in the stream, avoid spawning bins unless really needed.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Lookahead: if the next item exactly matches this bin's post-residual, big bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item size exactly or closely.
    if next_item_size > 0 {
        let match_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain match: strong bonus
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            // Next item fits here afterwards: reward proportionally to closeness
            score -= 18.0 * (1.0 - match_gap / bin_capacity as f64);
        } else {
            // Next item would NOT fit after this placement: penalize dead space
            score += 8.0 + match_gap * 0.15;
        }
    } else {
        // Last item: pure tightness
        score -= 5.0;
    }

    // Penalize creating tiny unusable residuals (< 10, min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: if this is the only bin that fits, favor using it
    // (avoid opening a new bin) unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 + 0.1 * (bin_residual as f64 - post_residual as f64);
    }

    // Brand-new empty bin candidate: penalize mildly so we only open new bins
    // when no open bin offers a decent fit; the lookahead bonuses can overcome it.
    if bin_residual == bin_capacity {
        score += 15.0;
    } else {
        // Reuse bonus scaled against mean residual: prefer bins tighter than average
        score += (bin_residual as f64 - mean_residual) * 0.2;
    }

    // Late in stream: consolidation matters more; discourage opening new bins
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that becomes unusable: post_residual smaller than
    // the minimum plausible item size (1) is fine, but small leftovers in
    // (0, ~15) range are typically wasted.
    if post_residual > 0 && post_residual < 15 {
        score += 12.0 * (1.0 - post_residual as f64 / 15.0);
    }

    // Lookahead coupling: bonus if the next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / 40.0);
        } else {
            // Next item won't fit here anyway; mild bonus for larger leftover.
            score += 3.0;
        }
    } else {
        // Last item: strongly prefer filling a bin as fully as possible.
        score -= 20.0 * tightness;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer bins whose residual is below the mean (consolidate emptier space).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Early stream: keep bins compact to preserve flexibility; late stream:
    // aggressively close out bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * progress * tightness;

    // Many open bins: discourage spreading across bins, favor filling existing ones.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to what open bins would leave behind.
    if bin_residual == bin_capacity {
        score += 18.0;
        if item_size >= 70 {
            score -= 20.0; // big items start fresh bins well
        }
        if post_residual < 10 {
            score -= 10.0; // near-perfect fresh placement
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let prn = pr / cap; // normalized post residual in [0,1]
    let w = 0.6 + 1.6 * progress * progress; // tighter fits matter more later
    score += w * (prn * prn) * cap;

    // Penalize residual that is dead space: too small for the smallest plausible item.
    let dead = (prn - (next_item_size.max(1) as f64 / cap)).max(0.0);
    score += 8.0 * dead * dead * cap;

    // Reward last-chance bins (avoid opening a new bin unnecessarily).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 + 20.0 * progress;
    }

    // Lookahead: bonus if next item fits exactly into post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    } else if next_item_size > post_residual && next_item_size > 0 {
        score += 2.0;
    }

    // Mild penalty for deviating from mean residual (keeps bin pool homogeneous).
    score += 0.05 * (mean_residual - pr).abs();

    // Slight preference for filling existing bins over opening new ones.
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 50.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Harmonic classes: dead space is only "usable" if a future item (sizes 1..100)
    // could fill it. Classify post_residual by divisibility / threshold classes.
    let pr = post_residual;
    let dead = if pr == 0 {
        0.0
    } else if pr < 10 {
        // Almost always dead space (items >= 1 exist, but tiny leftovers rarely used).
        0.9
    } else if pr <= 20 {
        0.6
    } else if pr <= 35 {
        0.35
    } else if pr <= 60 {
        0.15
    } else {
        0.05
    };
    // Modulo classes: residuals that are multiples of 10 are more likely reusable
    // under typical size quantization; penalize odd/awkward residues slightly.
    let mod_penalty = match pr % 10 {
        0 => 0.0,
        5 => 2.0,
        _ => 4.0,
    };
    score += dead * pr as f64 + mod_penalty;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 120.0 * (1.0 - slack as f64 / 10.0);
            } else {
                score += 0.1 * slack as f64;
            }
        } else {
            // Next item cannot use this bin's leftover: leftover is more likely dead.
            score += 8.0;
        }
    }

    // Last chance: if this is the only bin that fits, strongly prefer it over
    // opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0 + 0.5 * (bin_residual - item_size) as f64;
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // offer bad fits. Penalize opening a new bin mildly; escalate when many
    // bins are open and mean residual is still healthy.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 30.0 + 20.0 * open_pressure + 15.0 * (mean_residual / bin_capacity as f64) + 10.0 * progress;
    }

    // Mild preference to fill bins with larger residual (first-fit-ish tie-break
    // already via post_residual); discourage scattering across many bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    } else if post_residual >= 20 && post_residual < 35 {
        score -= 3.0; // moderately useful gap, slight reward
    }

    // Penalize bins whose residual deviates below the mean (fragmentation).
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score += 0.35 * (mean_residual - residual_f);
    } else {
        score -= 0.10 * (residual_f - mean_residual);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so it only wins when open bins are bad.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Early in the stream, new bins are cheaper; later, avoid spreading.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Open-bin pressure: many open bins -> discourage spreading further.
    score += 0.6 * open_bins_count as f64;

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual matches next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Exact match is ideal; penalize slack quadratically.
            score -= 40.0 - 0.02 * slack * slack;
            // Perfect fill chain: post_residual == next_item_size exactly
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            // Next item cannot fit here; penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize creating tiny dead space (< 10) that nothing can use,
    // unless it perfectly fills with the next item.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Slight preference for fuller bins overall.
    score -= 0.1 * (item_size as f64 / bin_capacity as f64) * 100.0;

    // Late in the stream, be more conservative: prefer compacting into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress;

    // New-bin candidate: make empty bins less attractive unless current bins are poor fits.
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // empty bin still useful for a two-item chain
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 20.0;

    // Penalize leaving medium dead space (unusable for typical items).
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // nearly perfect fit
    } else if post_residual >= 10 && post_residual < 30 {
        score += 5.0; // awkward dead zone
    }

    // Last-chance bin: if this is the only bin that fits, favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Lookahead: reward if the next item fits into the post residual (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + (next_item_size as f64 / 100.0) * 4.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize blocking the next item with leftover crumbs.
        score += (post_residual as f64) * 0.3;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins fit poorly (large mean residual dispersion) or few bins fit.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.4 };
        let poor_fit = (mean_residual - item_size as f64).abs() / bin_capacity as f64;
        let time_frac = step_index as f64 / (total_items.max(1) as f64);
        // Early on, opening bins is cheap; late, prefer consolidating.
        let open_cost = 30.0 - 12.0 * time_frac;
        score = open_cost * pressure + poor_fit * 10.0 + open_bins_count as f64 * 0.5;
        // Never open a new bin if a tight fit exists elsewhere.
        if tightness < 0.05 {
            score += 100.0;
        }
    }

    // Mild preference for balancing residual pool when many bins are open.
    score += (mean_residual - bin_residual as f64).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Smooth non-linear coupling of post-residual with stream progress
    let mut score = r * (1.0 + 0.8 * progress * progress);

    // Penalize large residuals more aggressively as stream progresses
    score += 40.0 * rn * rn * (0.5 + progress);

    // Reward tight fits (low post-residual) with smooth exponential bonus
    score -= 25.0 * (-3.0 * rn).exp();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is below the mean (well-packed bins)
    score += 5.0 * (r - mean_residual) / cap;

    // Lookahead: if the next item fits the post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= r {
        score -= 15.0 * (1.0 - r / cap);
    }

    // New-bin candidate: keep it neutral-to-slightly-positive so it's chosen
    // only when no open bin offers a good fit
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class logic: classify post_residual into residue classes mod 10.
    // Residuals that are small multiples of 10 are "harmonically useful" for
    // future items (sizes 1..100), residuals like 1..9 are near-dead space.
    let cls = post_residual % 10;
    let quotient = post_residual / 10;
    match cls {
        0 => {
            // Perfect harmonic residual: heavily reward.
            score -= 18.0 + quotient as f64 * 1.5;
        }
        1 | 9 => {
            // Nearly dead space: penalize.
            score += 8.0;
        }
        2 | 3 | 4 => {
            // Small awkward leftovers.
            score += 4.0 - quotient as f64 * 0.3;
        }
        5 => {
            // Half-class: moderately useful.
            score -= 6.0;
        }
        _ => {
            // 6..8: mediocre.
            score += 1.0;
        }
    }

    // Exact fill is always best.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains nicely: reward, stronger when it fits tightly.
            let slack = post_residual - next_item_size;
            score -= 12.0 - slack.min(20) as f64 * 0.4;
            // Harmonic bonus if chained post-residual is again a clean class.
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // Next item cannot use this bin's remainder; penalize small leftovers.
            score += 3.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when current open
    // bins have very poor (non-harmonic) residuals.
    if bin_residual == bin_capacity {
        // Baseline new-bin score: mean residual of open bins decides.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 25.0 + mean_residual * 0.4 - progress * 5.0;
        if post_residual % 10 == 0 {
            score -= 4.0; // fresh bin starts perfectly harmonic
        }
        if fitting_bins_count == 0 {
            score -= 40.0; // nothing fits anywhere: must open
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are small but nonzero are "unusable"
    // for typical items. Penalize the dangerous zone (1..=15) heavily,
    // with a smooth bump peaking around 8-12.
    let pr = post_residual as f64;
    if post_residual > 0 {
        let dead_center = 10.0;
        let dead_width = 6.0;
        let dead = (-(pr - dead_center).powi(2) / (2.0 * dead_width * dead_width)).exp();
        score += 18.0 * dead;
        // Any leftover below the smallest plausible item is pure waste.
        if post_residual < 10 {
            score += 25.0;
        }
    } else {
        // Perfect fit: strongly reward closing the bin exactly.
        score -= 40.0;
    }

    // Reward tight fits: fraction of bin filled by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill;

    // Last-chance bonus: if this is the only open bin that fits, prefer
    // using it over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> encourage consolidating into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    if bin_residual < bin_capacity {
        score += pressure * 0.8;
    } else {
        // New-bin candidate: base cost plus pressure; allow opening only
        // when the current item is large and no tight fit exists.
        score += 20.0 + pressure * 1.5;
        if item_size >= 60 && fitting_bins_count <= 2 {
            score -= 10.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post_residual,
    // reward this placement strongly (sequencing gain).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Mild alignment with mean residual: prefer bins whose residual is
    // already below average (they are the "small" bins to top off).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: perfect 2-step lookahead match (next item exactly fills bin)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Partial reward: next item fits into the post-residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
        // Extra reward for tight fit of next item
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 / (1.0 + slack);
    }
    // Penalize post-residual that is too small for the next item (dead space risk)
    if next_item_size > post_residual {
        let waste = (next_item_size - post_residual) as f64;
        score += 0.25 * waste;
    }

    // Penalize leaving unusable small dead space relative to typical item scale
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits of the current item (small post_residual)
    score -= 30.0 / (1.0 + post_residual as f64 / item_size.max(1) as f64);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: keep it neutral-to-slightly-averse unless
    // all open bins are poor fits (high mean residual spread).
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // Prefer a new bin when existing residuals are large (poor fits everywhere)
        score += 40.0 - 25.0 * pressure;
        // Late in the stream, discourage bin proliferation
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Mild penalty for bins far below mean residual (keeps residual distribution tight)
    score += 0.10 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post_residual is good, but punish tiny unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // dead space sliver
    }

    // Lookahead: if next item fits into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0;
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item won't chain here; mild penalty for wasting residual
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer fuller bins relative to current mean residual.
    score -= 0.3 * ((bin_residual as f64) - mean_residual);

    // Time horizon: early in stream, be pickier (keep bins flexible);
    // late in stream, prefer closing bins tightly.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += 6.0 * t * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 3 {
        score += 0.8 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: penalize so it's chosen only when fits are terrible.
    if bin_residual == bin_capacity {
        score += 40.0 + 0.5 * item_size as f64;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (0.5 + 0.5 * progress);

    let mut score = pr * (1.0 + poly);

    // Penalize dead space more as stream progresses (less time to reuse it).
    score += 8.0 * progress * norm_pr * norm_pr * cap;

    // Reward tight fits (small post residual), especially when lookahead matches.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 4.0 + 6.0 * progress;
    } else if next_item_size > post_residual {
        score += 2.0 * progress * norm_pr * cap;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0 + 10.0 * progress;
    }

    // Mild penalty proportional to crowding of open bins.
    score += 0.05 * open_bins_count as f64;

    // Prefer bins whose residual is below the mean (consolidating space).
    score -= 0.5 * (mean_residual - pr) / cap;

    // New-bin candidate: neutral baseline with slight progress-dependent cost.
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.4 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue mod 10 as a small penalty
    // (residuals in "nice" classes are easier to fill later).
    let r = post_residual % 10;
    score += match r { 0 => -6.0, 1 | 9 => 2.0, 2 | 8 => 1.0, 5 => -2.0, _ => 0.0 };

    // Fraction of capacity wasted: heavy penalty for tiny dead space bands
    let frac = post_residual as f64 / cap_f;
    if frac < 0.05 { score += 25.0; }        // unusable sliver
    else if frac < 0.10 { score += 10.0; }
    else if frac > 0.5 { score -= 4.0; }     // lots of room left is fine

    // Integer-division threshold: post_residual / item_size ratio
    let ratio = post_residual as f64 / (item_size.max(1) as f64);
    if ratio >= 2.0 { score -= 3.0; }        // bin could hold another similar item

    // Lookahead coupling: can next item fit in post_residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // harmonic bonus if next item exactly consumes a class boundary
            if (post_residual - next_item_size) % 10 == 0 { score -= 4.0; }
        } else {
            score += 6.0; // next item won't fit here -> dead space risk
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no good open fit exists
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 || frac_penalty_proxy(mean_residual) > 0.5 {
            score -= 5.0;
        } else {
            score += 20.0; // prefer existing bins generally
        }
    }

    // Stream progression: late in stream, consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0 * (mean_residual / cap_f);

    // Penalize bins far from mean residual (fragmentation control)
    score += ((post_residual as f64 - mean_residual).abs()) * 0.15;

    score
}

#[inline]
fn frac_penalty_proxy(mean_residual: f64) -> f64 {
    // high mean residual among open bins -> poor overall packing so far
    (mean_residual / 100.0).clamp(0.0, 1.0)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: any small nonzero gap is wasted space.
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 40.0 + (20 - post_residual.min(20)) as f64 * 3.0;
    }

    // Perfect fit is highly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Gap large enough for the lookahead item is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap cannot host next item: mild dead-space penalty.
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 6.0;
        // New bins are more tolerable early in the stream.
        score -= (step_index as f64 / total_items.max(1) as f64) * 30.0;
    } else {
        // Reward filling existing bins, more so when many bins are open.
        score -= open_bins_count as f64 * 1.5;
    }

    // Prefer bins tighter than the mean residual (denser bins).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fits (dead-space elimination)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0 + (10 - post_residual) as f64 * 10.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // next item can follow directly: reward tight coupling
            score -= (bin_capacity as f64 - gap) * 0.5;
        } else {
            // next item would not fit: penalize proportionally to the leftover gap
            score += gap * 0.8;
        }
        // extra bonus when post_residual exactly equals next item size
        if post_residual == next_item_size {
            score -= 150.0;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fit is poor
    if bin_residual == bin_capacity {
        score += 60.0;
        // allow new bin late in the stream when few bins fit
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 20.0;
    }

    // Mild penalty for many open bins (encourage consolidation)
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fit strongly.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Lookahead: penalize dead space that cannot host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0 + 0.3 * next_item_size as f64;
        } else {
            score += 0.6 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a brand-new bin unless the item leaves very little waste there
    // or existing residuals are poor fits.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score += 40.0 + 0.5 * waste;
        if mean_residual > item_size as f64 {
            score += 20.0; // existing bins have room; opening new bin is wasteful
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
    }

    // Prefer bins with tight residual relative to item (best-fit flavor).
    score += 0.2 * (bin_residual as f64 - item_size as f64).abs();

    // Slight time decay: early on, be more conservative about fragmenting bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // smooth non-linear coupling: post residual shaped by progress
    let mut score = pr * (1.0 + 0.6 * progress * (1.0 - x) * (1.0 - x));

    // penalize large dead space non-linearly
    score += 30.0 * x * x * x * (0.5 + progress);

    // reward tight fits (small post residual) more strongly as stream progresses
    score -= 20.0 * (1.0 - x) * (1.0 - x) * (1.0 - x) * progress;

    // last-chance bonus: only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // lookahead: penalize if next item fits well in post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let diff = x - nx;
        score -= 10.0 * (-diff * diff * 20.0).exp();
    }

    // mild penalty for opening new bins when many open
    if bin_residual == bin_capacity {
        score += 5.0 + 0.1 * open_bins_count as f64;
    }

    // relative residual context
    score += 0.3 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: small leftovers are dead space.
    // Class 0: post_residual == 0 (perfect fill) -> strong reward.
    // Class 1: post_residual in 1..=10 (tiny dead space) -> mild penalty.
    // Class 2: post_residual in 11..=25 (medium) -> neutral-ish.
    // Class 3: post_residual in 26..=49 (large) -> penalize (wasteful bin use).
    let class = if post_residual == 0 {
        0u8
    } else if post_residual <= 10 {
        1
    } else if post_residual <= 25 {
        2
    } else {
        3
    };

    match class {
        0 => score -= 60.0,
        1 => score += 12.0,
        2 => score -= 4.0,
        _ => score += 18.0,
    }

    // Integer-division thresholds: reward placements leaving residuals that
    // common small item sizes (1..=25) can still exactly divide into.
    let usable = (1..=25u32).filter(|&s| post_residual % s == 0 && post_residual > 0).count();
    score -= 6.0 * usable as f64;

    // Modulo coupling with capacity: residuals that are clean fractions of
    // capacity (C/4, C/2, 3C/4) are structurally useful.
    if post_residual == bin_capacity / 4
        || post_residual == bin_capacity / 2
        || post_residual == (3 * bin_capacity) / 4
    {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Next item cannot follow in this bin: mild penalty proportional
            // to how much of the bin the current item consumed.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening fresh bins unless current residual
    // is badly fragmented relative to the item.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 30.0 + fragmentation * 0.2;
        // But if the item is huge, a fresh bin is fine.
        if item_size > bin_capacity / 2 {
            score -= 35.0;
        }
    }

    // Late in the stream, tighten packing (avoid spreading over open bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Dead-space penalty: residuals too small to hold even the smallest
    // plausible item (assume items >= 1..100 unknown; treat < 25 as likely dead)
    if post_residual > 0 && post_residual < 25 {
        score += (25.0 - post_residual as f64) * 3.0; // unusable sliver
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tight fit reward: post_residual small relative to item size.
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score -= 2.0 * (1.0 - tightness.min(1.0));
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 10.0 - (slack as f64).min(10.0);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Next item cannot use this residual: dead space for lookahead.
        score += 5.0 + (post_residual as f64) * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many bins open, prefer filling existing ones.
    score += open_bins_count as f64 * 1.5 * (0.5 + progress);

    // Prefer bins below mean residual (pack fuller bins first).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: penalize opening a new bin, more so later in stream
    // and when other bins fit; but allow it when the residual would be large.
    if bin_residual == bin_capacity {
        let escape = if fitting_bins_count > 0 { 20.0 + fitting_bins_count as f64 * 5.0 } else { 0.0 };
        score += 40.0 + escape + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit bonus: reward small post_residual relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 40.0;

    // 2-step lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 600.0;
        } else if next_item_size <= post_residual {
            // next item fits, but penalize leftover waste after both placements
            let double_waste = (post_residual - next_item_size) as f64;
            score += double_waste * 0.8;
        } else {
            // next item cannot follow: penalize proportionally to gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Last chance: only fitting bin — encourage using it to avoid a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Compare against mean residual: bins tighter than mean are better targets
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 80.0;
        // allow new bin if lookahead matches empty capacity well for future items
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 20.0;
        }
    }

    // Early stream: be slightly conservative about fragmenting bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 100.0;
    }

    // Lookahead: reward if the next item fits into the post-residual of this bin
    // (keeps a chain of placements in one bin); penalize if it almost fits,
    // which creates tempting dead space.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual && next_item_size - post_residual <= 5 {
            score += 40.0; // near-miss: this bin will strand space the next item wants
        }
    }

    // Last-chance bonus: if this is the only open bin that fits, using it
    // avoids opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Penalize bins whose residual is far below the mean residual (they are
    // already "wasted" relative to the fleet); prefer placing into bins with
    // residuals near the mean to balance the pool.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Dynamic time horizon: early in the stream, keep residuals large and
    // flexible (mild penalty on very small residuals); late in the stream,
    // pack aggressively (reward small residuals).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 0.5 * post_residual as f64;

    // New-bin candidate handling: an empty bin is attractive when existing
    // bins fit poorly (large post_residual would be wasted) or when the item
    // is large and the fleet is fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted late in the stream.
        score = 40.0 - 20.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0; // fresh bin can also host the next item
        }
        // If no open bin gives a good fit, opening a new bin is cheap.
        if post_residual_worst_guess(fitting_bins_count) == 0 && fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Fragmentation guard: many open bins with small residuals suggests
    // fragmentation; prefer consolidating into bins that will be emptied out.
    if open_bins_count > 4 && post_residual <= 10 {
        score -= 15.0;
    }

    score
}

fn post_residual_worst_guess(_fitting: usize) -> u32 { 0 }

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits, with a non-linear (quadratic) dead-space penalty
    let mut score = post + 30.0 * norm_post * norm_post;

    // Smooth interaction: dead space matters more as the stream progresses
    score += 40.0 * progress * norm_post * (1.0 - norm_post);

    // Penalize post-residual that cannot host the lookahead item (smoothly)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            let gap = (nxt - post) / cap;
            score += 25.0 * gap * gap;
        } else {
            // reward bins whose leftover can still serve the next item
            let slack = (post - nxt) / cap;
            score -= 15.0 * (-slack * 3.0).exp();
        }
    }

    // Last-chance bonus: this is the only bin that fits the item
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize mildly, less so early in the stream or when
    // open bins are heavily fragmented (high mean residual)
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap).clamp(0.0, 1.0);
        score = cap + 20.0 - 25.0 * (1.0 - progress) - 15.0 * frag;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: capacity fraction classes via integer division of post_residual
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class of post_residual in capacity-eighths (harmonic partition of capacity)
    let class = (post_residual * 8) / bin_capacity; // 0..8 integer class
    let class_bonus: f64 = match class {
        0 => 40.0,          // perfectly full -> best
        1 => 30.0,          // tiny sliver, near-dead space
        2 => 22.0,
        3 => 15.0,
        4 => 10.0,          // half capacity residual: highly reusable
        5 => 14.0,
        6 => 18.0,
        7 => 24.0,
        _ => 0.0,           // untouched bin
    };
    score -= class_bonus;

    // Modulo-10 alignment: residuals matching common item-size multiples are reusable
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 {
        score -= 4.0;
    }

    // Perfect lookahead fit: next item exactly fills post residual
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    }
    // Next item fits into post residual (chain packing)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (post_residual - next_item_size) as f64 * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Penalize creating dead space smaller than the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Relative residual term: prefer bins whose post residual is small fraction of capacity
    score += 0.15 * post;

    // New-bin candidate: only attractive when existing bins are crowded or fit is poor
    if bin_residual == bin_capacity {
        let crowded = mean_residual / cap;
        let poor_fit = (bin_residual - item_size) as f64;
        // penalize opening new bin mildly; escalate as stream progresses and bins are few
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 20.0 * progress - 10.0 * crowded - 0.05 * poor_fit;
    }

    // Tie-break toward consolidating among many open bins
    score -= 0.02 * (post_residual as f64) * (open_bins_count as f64).ln().max(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - (post_residual as f64) / 10.0);
    }

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // If the next item could use the post residual, reward leaving a useful gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.25 * next_item_size as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open,
    // scaled by how much slack the stream has already consumed.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_penalty = 25.0 + 30.0 * progress + 2.0 * open_bins_count as f64;
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
    } else {
        score -= 5.0;
    }

    // Prefer bins whose residual is below the mean (tighter packing).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 40.0 + 0.5 * next_item_size as f64;
        } else {
            // penalize leaving a gap that just misses the next item
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
        // reward near-perfect two-item fills (post_residual ~ next_item_size)
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        score -= 30.0 * f64::exp(-(gap as f64) / 8.0);
    } else {
        // last item: prefer tightest fit
        score += 10.0 * (post_residual as f64) / bin_capacity as f64;
    }

    // Dead-space penalty: small unusable residuals are bad.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Compare residual against mean residual: prefer tighter-than-average bins early,
    // but late in the stream prefer bins with more room to consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (0.5 - progress) * (post_residual as f64 - mean_residual);

    // Slight penalty for very full bins when many bins are open (keep flexibility).
    if open_bins_count > 4 && post_residual == 0 {
        score += 5.0;
    }

    // New-bin candidate: make it moderately unattractive unless residuals are all poor.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.2 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more than linearly.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space: residuals too small to be useful later.
    let dead = if post_residual < 10 { post_residual as f64 } else { 0.0 };
    score += 25.0 * dead / 10.0;

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / (bin_capacity as f64);
        }
    } else {
        // last item: prefer exact fill
        score -= 20.0 * tight;
    }

    // Last-chance bonus: this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Global pressure: many open bins -> prefer reusing existing bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.15 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tight;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins with residual close to mean (balanced usage) early on.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (1.0 - progress);

    // New-bin candidate: only open a new bin if current fit is terrible.
    if bin_residual == bin_capacity {
        score += 18.0 + 10.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let prn = pr / cap; // normalized post-residual in [0,1]
    let t = progress.clamp(0.0, 1.0);
    let coupling = prn * prn * (1.0 - t) + prn * t * t;
    score += 12.0 * coupling;

    // Reward tight fits, more strongly late in the stream (waste compounds).
    let tightness = 1.0 - prn;
    score -= 18.0 * tightness * tightness * (0.5 + t);

    // Lookahead: penalize if post-residual can't fit the next item (dead space),
    // reward if it can exactly seed the next placement.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let leftover = pr - ni;
            score -= 6.0 * (1.0 - leftover / cap);
        } else {
            score += 5.0 * (ni - pr) / cap;
        }
    } else {
        // Last item: minimize waste absolutely.
        score += 10.0 * prn;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: neutral residual equals capacity; penalize mildly,
    // but relax the penalty when open bins are nearly full on average.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        let crowded = (mean_residual / cap).min(1.0);
        score += 8.0 * (1.0 - crowded) * (1.0 - crowded) + 4.0 * (1.0 - t);
    }

    // Mild penalty for many open bins relative to progress (encourage consolidation).
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: dead space in "waste-prone" classes
    // (small odd remainders that few item sizes can fill) is penalized.
    let pr = post_residual;
    let class = pr % 10;
    let class_penalty = match class {
        0 => -8.0,          // perfectly divisible residual is highly reusable
        5 => -4.0,          // half-class, many items fit
        2 | 4 | 6 | 8 => -2.0, // even class
        1 | 3 | 7 | 9 => 3.0,  // odd class: harder to fill exactly
        _ => 0.0,
    };
    score += class_penalty;

    // Integer-division threshold: residual that can still host a medium item
    // is valuable; residual below the minimum item size is pure dead space.
    if pr < 10 && pr > 0 {
        score += 25.0; // unusable sliver
    } else if pr >= 50 {
        score -= 5.0; // roomy residual stays flexible
    }

    // Exact-fill reward: placing the item perfectly closes the bin.
    if pr == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly reward this placement (harmonic chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            score -= 10.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            // next item cannot follow here; residual becomes stranded
            score += 6.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // or the stream is early and we want many bins for future flexibility.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 18.0 };
        score += desperation + 10.0 * (1.0 - progress) + mean_residual * 0.05;
    }

    // Mild preference for bins tighter than the current average residual
    // (best-fit flavor with harmonic scaling).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Modulo coupling between item and capacity: items in coarse size classes
    // (multiples of 25) pack best into matching residual classes.
    if bin_residual % 25 == 0 && item_size % 25 == 0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps are unusable, penalize hard.
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 3.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Reward filling most of the bin (tight fit).
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 15.0;

    // Last chance: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (the new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 4.0;
        // but a new bin is fine if the item is large and nothing fits well
        if item_size > bin_capacity * 3 / 4 {
            score -= 20.0;
        }
    }

    // Lookahead coupling: if the next item fits in the post-residual,
    // reward leaving that room; otherwise penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else if next_item_size > post_residual && post_residual > 0 && next_item_size <= bin_residual {
            score += 5.0;
        }
    }

    // Mild preference toward bins with low residual relative to mean.
    score += (mean_residual - post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (low post_residual)
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_ratio = post / cap; // 0 = perfect fit, 1 = empty bin

    // Penalize large dead space non-linearly (quadratic waste)
    score += 30.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: reward when next item fits into post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            // Next item chains perfectly: reward proportionally to how snug the chain is
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - chain_waste / cap);
            // Extra bonus if chain leaves a near-perfect residual
            if chain_waste <= 5.0 {
                score -= 15.0;
            }
        } else {
            // Next item won't fit here: penalize leaving a residual that is
            // "almost but not quite" big enough (unusable dead space)
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 10.0 {
                score += 20.0 * (1.0 - gap / 10.0); // near-miss is worst
            }
        }
    } else {
        // Last item: minimize post_residual aggressively
        score -= 10.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are "precious" tight bins
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev; // prefer bins tighter than average (lower residual -> lower score)

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin should only win if no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin; grows with number of open bins already
        score += 35.0 + 2.0 * open_bins_count as f64;
        // Late in the stream, opening new bins is cheaper than fragmenting
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * progress;
        // If next item is large, a fresh bin keeps flexibility
        if next_item_size >= 50 {
            score -= 10.0;
        }
    } else {
        // Using an existing bin saves a bin: constant reward
        score -= 20.0;
        // Reward consolidation when many bins are open (reduce bin count pressure)
        if open_bins_count > 3 {
            score -= 1.0 * (open_bins_count as f64).ln();
        }
    }

    // Slight preference to fill bins earlier in the stream (keep fresh bins for later)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
