    }

    // New-bin candidate handling: empty bin should win only when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 55.0 + 25.0 * (1.0 - progress);
        // If no open bin fits, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
        // If the item perfectly splits a fresh bin (e.g. size 50), encourage it.
        if item_size * 2 == bin_capacity {
            score -= 45.0;
        }
