pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: smooth non-linear penalty on post-residual (dead space grows super-linearly)
    let mut score = pr as f64 * (1.0 + 0.8 * x * x) * (1.0 + 0.5 * progress);

    // Coupling with mean residual: prefer bins whose residual deviates favorably from mean
    score += 0.35 * (pr as f64 - mean_residual).abs() * (0.5 + progress);

    // Perfect fit reward (smooth)
    if post_residual == 0 {
        score -= 25.0;
    } else {
        score -= 20.0 * (1.0 - x).exp();
    }

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr as f64 {
            score -= 10.0 * (1.0 - nx / cap);
        } else {
            score += 5.0 * (nx - pr as f64) / cap;
        }
    }

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate: neutral-ish baseline, penalized when good fits exist elsewhere
    if bin_residual == bin_capacity {
        score = cap * (1.0 + progress) - 15.0 * (1.0 - x).exp();
        if fitting_bins_count == 1 {
            score += 40.0;
        }
        if next_item_size > 0 && (next_item_size as f64) <= cap {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" the leftover space is.
    // Class 0: post_residual == 0 (perfect fit, huge reward)
    // Class 1: post_residual <= 5 (near-perfect)
    // Class 2: post_residual divisible by small harmonics (10, 20, 25, 50) -> likely reusable
    // Class 3: awkward leftover (1..9 gap, non-harmonic) -> penalize
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else {
        let harmonic = (post_residual % 10 == 0) || (post_residual % 25 == 0) || (post_residual % 50 == 0);
        if harmonic {
            score -= 10.0;
        } else {
            score += 8.0 + (post_residual % 10) as f64;
        }
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual,
    // penalize if next item would strand this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 5.0 {
                score -= 15.0;
            } else {
                score += slack * 0.15;
            }
        } else {
            // next item cannot use this bin's leftover; leftover is dead weight
            score += post_residual as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins are crowded or the fit would create large dead space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        // penalize new bins generally, less so when open bins are full-ish
        score += 45.0 - crowd * 2.0 - progress * 10.0;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 20.0; // big item coming, fresh bin is fine
        }
    } else {
        // Mild bonus for filling existing bins deeply (low residual relative to capacity)
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill * 5.0;
    }

    // Mean-residual context: when average slack is small, conserve bins harder.
    score -= (mean_residual / 20.0).min(10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 40.0 * (11.0 - post_residual as f64);
        } else if post_residual < 20 {
            score += 15.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Tight fits (small but still usable remainder) get a mild reward.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 8.0 * tightness;

    // Lookahead: if the next item fits into the post residual, reward it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        let nxt_tight = next_item_size as f64 / post_residual as f64;
        score -= 6.0 * nxt_tight;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use the leftover: penalize waste proportionally.
        score += 4.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 30.0;
        } else {
            // Slight penalty so decent existing bins are preferred.
            score += 5.0 + 0.5 * open_bins_count as f64;
        }
    }

    // Late-stream consolidation: as the stream progresses, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // 2-step lookahead: reward if next item fits into post_residual (chained fill).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + (next_item_size as f64) * 0.3;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize dead space the next item cannot use.
        score += (post_residual as f64) * 0.25;
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably.
    score -= (mean_residual - post_residual as f64) * 0.1;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize slightly unless current fits are terrible.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But if next item chains perfectly into a fresh bin, soften penalty.
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 10.0;
        }
    }

    // Late-stream urgency: close out bins tightly as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity as f64 - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Penalize dead space: post_residual that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item cannot use the leftover; slight penalty proportional to waste.
            score += 0.05 * post_residual as f64;
        }
    }

    // Prefer filling already-open bins when many bins are open (reduce fragmentation).
    score -= 3.0 * (open_bins_count as f64).ln().max(0.0);

    // Global state: if mean residual is large, prefer consolidating into fuller bins.
    score += 0.1 * (mean_residual - post_residual as f64);

    // Time horizon: early in the stream, be more selective (penalize mediocre fits);
    // late in the stream, just pack greedily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * tightness;

    // New-bin candidate: penalize opening a new bin unless current fits are poor.
    if bin_residual == bin_capacity {
        score += 20.0 + 5.0 * (fitting_bins_count as f64);
        // But if the item is large and mean residual is low, a fresh bin is attractive.
        score -= 0.15 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // smooth polynomial coupling: dead-space penalty grows with stream progress
    let dead = norm_pr * norm_pr;
    score += 40.0 * progress * dead;
    // reward tight fits more strongly late in the stream
    score -= 25.0 * (1.0 - progress) * (1.0 - norm_pr) * (norm_pr);
    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 15.0 + 20.0 * progress;
    }
    // lookahead: residual that fits next item is valuable
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 8.0 * (next_item_size as f64 / cap) * norm_pr;
    }
    // prefer bins below mean residual slightly (balance)
    score += 3.0 * ((bin_residual as f64 - mean_residual) / cap);
    // new-bin candidate: penalize mildly unless residual would be wasted
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * progress - 5.0 * norm_pr;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into
    // "usable" size classes for typical small items.
    let pr = post_residual;
    if pr > 0 {
        // class by integer division into deciles of capacity
        let class = pr / 10;
        match class {
            0 => score -= 30.0,               // near-perfect fit (0-9)
            1 => score -= 22.0,               // excellent (10-19)
            2 => score -= 14.0,               // good (20-29)
            3 => score -= 7.0,                // decent (30-39)
            4 | 5 => score -= 2.0,            // average (40-59)
            _ => {}                            // large leftover: no reward
        }
        // modulo-5 harmonic bonus: residuals divisible by 5 pair well
        if pr % 5 == 0 { score -= 4.0; }
        if pr % 10 == 0 { score -= 4.0; }
    } else {
        score -= 60.0; // perfect closure
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = pr - next_item_size;
        score -= 12.0 + 0.3 * slack as f64;
        // harmonic match: next item leaves a divisible-by-5 residual
        if slack % 5 == 0 { score -= 5.0; }
    } else if next_item_size > 0 {
        // next item cannot use the residual: penalize dead space mildly
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive if all open bins are tight
    // or the item is huge relative to mean residual.
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64) / mean_residual.max(1.0);
        if pressure > 0.85 || open_bins_count == 0 {
            score -= 25.0; // open a fresh bin
        } else {
            score += 20.0; // prefer existing bins otherwise
        }
    }

    // Stream progression: early on, keep bins flexible (large residual good);
    // later, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.15;

    // Penalize bins far below mean residual (fragmenting the pool).
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 { score += 0.1 * dev; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold the smallest item are wasted.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0 - 6.0 * post_residual as f64;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Favor bins whose residual tightly matches the item (small slack relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 40.0;
        } else if gap <= 10 {
            score -= 15.0;
        }
    }
    // Penalize leaving a gap that the next item cannot use at all.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones over new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (0.5 + 0.5 * progress);

    // New-bin candidate handling: make empty bins less attractive unless open bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 30.0 + 5.0 * (open_bins_count as f64).sqrt() - fragmentation.min(20.0);
    }

    // Mild preference for bins close to the mean residual (balanced filling).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: exact fill leaves no dead space.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post-residual,
    // strongly prefer this bin (chain a perfect fill).
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            // Next item fits: reward proportional to how well it fills remainder.
            let fill_ratio = next_item_size as f64 / post_residual as f64;
            score -= 300.0 * fill_ratio;
            // Two-step chain leaves near-zero final waste.
            let chain_waste = post_residual - next_item_size;
            if chain_waste <= 5 {
                score -= 200.0;
            }
        } else {
            // Next item cannot fit: penalize small unusable post-residuals
            // (dead space that likely never gets filled).
            if post_residual < 10 {
                score += 150.0;
            } else if post_residual < 20 {
                score += 60.0;
            }
        }
    }

    // Penalize creating dead space relative to the smallest possible item (1).
    // Small post-residuals (< 10) are hard to fill given unknown distribution.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Compare post_residual against mean residual: prefer bins that stay
    // above-average full (post_residual below mean residual).
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.25 * (mean_residual - post_residual as f64);
    }

    // New-bin candidate handling: an empty bin has high residual; make it
    // less attractive than good fits, but attractive when open bins would
    // leave tiny dead space.
    if bin_residual == bin_capacity {
        score += 250.0;
        // Late in the stream, opening fresh bins is fine (future demand unknown).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 100.0 * progress;
        // If the next item is large, a fresh bin is valuable.
        if next_item_size > 50 {
            score -= 80.0;
        }
    }

    // Slight preference for filling bins when many are open (consolidation).
    score -= 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: small post-residuals that can't hold typical items are bad.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead coupling: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.1 * next_item_size as f64;
        } else if post_residual > 0 {
            score += 5.0; // stranded sliver relative to lookahead
        }
    }

    // Last-chance logic: if this is the only fitting bin, use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = mean_residual / bin_capacity as f64;
        let mut new_bin_score = 40.0;
        // Opening a bin is cheaper when many bins exist late in the stream? No—prefer consolidation early.
        new_bin_score += 30.0 * (1.0 - progress);
        // If mean residual is high, open bins have room; penalize new bin.
        new_bin_score += 25.0 * crowding;
        // If no open bin fits well (large item), new bin becomes attractive.
        if fit_ratio < 0.5 {
            new_bin_score -= 20.0;
        }
        if open_bins_count == 0 {
            new_bin_score = -100.0;
        }
        score = score.min(new_bin_score + 1000.0);
        return new_bin_score;
    }

    // Mild penalty for spreading across many open bins when they are mostly full.
    score += 0.05 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Time-based exploration: early in the stream, tolerate looser fits to keep options open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress) * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let coupling = norm_pr * norm_pr * (1.0 + 2.0 * p2) - norm_pr * (0.5 + p3);
    score += 30.0 * coupling;

    // Reward tight fits more aggressively as the stream progresses
    score -= 40.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.3 + 0.7 * p2);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual > 0 {
        let dead = norm_next - norm_pr;
        score += 25.0 * dead * (1.0 + p2) * (1.0 + p2);
    }

    // Reward post-residual that still accommodates the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0 * (norm_pr - norm_next) * (1.0 + progress);
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + 2.0 * p2);
    }

    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // Deviation from mean residual: prefer bins with less residual (denser bins)
    score += 3.0 * (mean_residual - pr) / cap * (1.0 + p3);

    // New-bin candidate: penalize mildly so it only wins when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 8.0 + 12.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which "capacity fraction" band it lands in.
    // Classes: (0..=10] tiny, (10..=25] small, (25..=50] medium, (50..=100] large.
    let post_class: u32 = match post_residual {
        0 => 0,
        1..=10 => 1,
        11..=25 => 2,
        26..=50 => 3,
        _ => 4,
    };

    // Perfect fit is overwhelmingly preferred.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Modulo-arithmetic harmony: does post_residual divide cleanly relative to
    // typical item granularity? Residuals that are multiples of common small
    // classes (divisible by 10 or 25) are more reusable.
    let harmonic_bonus = if post_residual % 10 == 0 {
        12.0
    } else if post_residual % 5 == 0 {
        6.0
    } else if post_residual % 25 == 0 {
        10.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Integer-division coupling: if the next item fits exactly into post_residual,
    // strongly reward this bin (chain fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 40.0;
        } else {
            // Reward proportionally to how well next item nests.
            let nest = (post_residual / next_item_size) as f64;
            score -= 8.0 * nest.min(3.0);
        }
    } else if next_item_size > 0 {
        // Next item cannot use the residual at all: penalize dead space,
        // scaled by how small the dead band is (class 1 residuals are worst).
        let dead_penalty = match post_class {
            1 => 25.0,
            2 => 12.0,
            3 => 5.0,
            _ => 0.0,
        };
        score += dead_penalty;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        if post_residual <= 10 {
            score -= 20.0;
        }
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // offer bad fits. Penalize the fresh bin mildly, more when open bins are sparse.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let scarcity = (fitting_bins_count == 0) as i32;
        score += 15.0 + 20.0 * (1.0 - progress) + 35.0 * scarcity as f64;
        // A new bin is attractive if the current residual would be badly fragmented.
        if post_residual > 0 && post_residual < 10 && bin_residual != bin_capacity {
            score -= 0.0; // unreachable for empty bin, kept for symmetry
        }
    }

    // Prefer filling bins with residuals close to the mean (balance exploitation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for bins whose residual is just above item size (snug fit).
    let snug = (bin_residual as f64 - item_size as f64);
    if snug < 15.0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to ever be useful
    // (below the minimum plausible item size) are heavily penalized.
    let min_item = 1.0f64;
    if post_residual > 0 && (post_residual as f64) < min_item + 9.0 {
        score += 40.0 + (10.0 - post_residual as f64) * 6.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits relative to residual (small waste ratio).
    if bin_residual > 0 {
        let waste_ratio = post_residual as f64 / bin_residual as f64;
        score += waste_ratio * 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins slightly,
    // but encourage using existing bins when many are open.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item would be blocked by the post residual, mild penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below mean
    // (concentrate filling in the fullest bins).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Penalize opening a new bin, but relax the
    // penalty late in the stream or when the fit into open bins is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 55.0 * (1.0 - 0.3 * progress);
        // If current item leaves a large residual in this fresh bin, it is
        // attractive for future items; scale by item size.
        new_bin_penalty -= (item_size as f64) * 0.15;
        score += new_bin_penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post residual).
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward when the leftover exactly matches
    // or can host the next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if post >= next {
            // Slack that exactly fits the next item is highly desirable.
            let slack = post - next;
            score -= 40.0 * (next / 100.0);
            score += 0.3 * slack; // mild penalty for excess slack beyond next item
        } else {
            // Leftover too small for the next item: penalize dead space,
            // especially tiny unusable slivers.
            score += 10.0 + 0.5 * (next - post);
        }
        // Perfect exact match bonus.
        if post == next {
            score -= 25.0;
        }
    } else {
        // Last item: just minimize post residual strongly.
        score += 5.0;
    }

    // Compare post_residual against the mean residual of open bins:
    // leaving less than average waste is good.
    score -= 0.4 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        if post_residual <= 10 {
            score -= 20.0; // near-perfect packing opportunity
        }
    }

    // New-bin candidate handling: an empty bin has huge residual, so its raw
    // score is high already. Discourage opening a new bin when a reasonable
    // fit exists among open bins, but allow it when open bins would waste a lot.
    if bin_residual == bin_capacity {
        // Empty bin baseline: its post_residual = capacity - item_size.
        // Add a fixed opening cost, discounted late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 45.0 - 15.0 * progress;
        // If next item is large, an empty bin gives flexibility.
        if next_item_size >= item_size {
            score -= 10.0;
        }
    } else {
        // Penalize leaving very small unusable fragments in open bins.
        if post_residual > 0 && post_residual < 10 {
            score += 12.0;
        }
    }

    // Slight preference to fill bins with more content already (fewer open bins
    // relative to mean residual implies consolidation is working).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) nonlinearly.
    score += (post_residual as f64).powi(2) / 20.0;

    // Penalize leaving dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here: mild penalty for creating stranded space
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance bonus: only one bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer bins with below-mean residual (fill emptier bins less aggressively).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // New-bin candidate: only attractive when no good fit exists (residual of best fit would be large).
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64;
        // Early in stream: opening new bins is cheap; later: expensive.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 + openness * 2.0 + progress * 20.0;
        // But if item is huge, a fresh bin guarantees fit; soften penalty.
        if item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Slight preference for bins whose fill ratio is already high.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * 8.0;

    // Reward near-exact residual usage.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += waste_ratio * 12.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with smooth non-linear coupling to stream progress.
    // Later in the stream, dead space matters more -> amplify via polynomial.
    let mut score = pr * (1.0 + 0.9 * progress * progress);

    // Strongly reward tight fits (small post_residual) with a convex penalty
    // on normalized residual, weighted by progress.
    score += 25.0 * norm_pr * norm_pr * (0.5 + progress);

    // Penalize very large post residuals (wasted space) super-linearly.
    if norm_pr > 0.5 {
        score += 30.0 * (norm_pr - 0.5) * (norm_pr - 0.5);
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (1.0 - (next_item_size as f64) / cap);
    } else if next_item_size > 0 {
        // Next item cannot follow -> mild penalty, growing with progress.
        score += 6.0 * (0.3 + progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Scarcity pressure: fewer fitting bins -> favor this one.
    if fitting_bins_count > 0 {
        score -= 4.0 / fitting_bins_count as f64;
    }

    // Mean-residual coupling: placing into a bin below mean residual keeps
    // the residual distribution balanced; penalize bins far above mean.
    score += 0.15 * (pr - mean_residual).abs();

    // New-bin candidate handling: empty bin gets a smooth, progress-dependent
    // handicap so it is only chosen when open bins would waste much space.
    if bin_residual == bin_capacity {
        score += 20.0 + 25.0 * (1.0 - progress) - 0.05 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal: strongly reward exact fill.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Dead space analysis: small nonzero residuals are wasteful.
    if post_residual <= 10 {
        score += 60.0; // tiny sliver, likely unusable
    } else if post_residual <= 20 {
        score += 30.0;
    }

    // Harmonic class logic: classify post_residual by residue modulo 10
    // (smallest item size class). Residuals divisible by 10 align with
    // item size classes and are more reusable.
    let class = (post_residual % 10) as f64;
    score += class * 2.0;

    // Integer-division thresholds: how many "unit classes" of 10 fit.
    let usable_units = post_residual / 10;
    score -= usable_units as f64 * 3.0;

    // Lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward residuals that can host the next item,
            // especially tight fits (harmonic match on modulo class).
            score -= 25.0;
            if post_residual % next_item_size == 0 {
                score -= 15.0;
            }
        } else {
            // Residual too small for next item: penalize more as it shrinks.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive if item is large
    // relative to capacity (poor fit elsewhere) or many bins already open.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64 / bin_capacity as f64) > 0.5;
        if large_item || open_bins_count > 6 {
            score -= 20.0;
        } else {
            score += 40.0; // discourage opening new bins for small items
        }
    }

    // Mild global pressure: prefer filling existing bins when mean
    // residual is high (bins are loose overall).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += mean_residual * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no future item (min size 1, but
    // realistically >= 10 in typical streams) can use are heavily penalized.
    if post_residual > 0 {
        // Absolute dead space: too small for the smallest plausible item.
        if post_residual < 10 {
            score += 60.0 * (10.0 - post_residual as f64);
        }
        // Gap smaller than the lookahead item: likely unusable next step.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
        }
        // Non-linear dead-space pressure: quadratic growth of waste for mid gaps.
        let pr = post_residual as f64;
        score += 0.05 * pr * pr / (1.0 + pr / 30.0);
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits (low relative waste).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - waste_ratio);

    // Open-bin pressure: discourage spreading across many bins; encourage
    // filling existing bins when many are open, but allow new bins when few.
    let obp = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when enough open bins exist; relax
        // pressure late in the stream or when bins are crowded.
        score += 35.0 + 2.5 * obp;
        // If the only fitting bin is this new one, opening is fine.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Late stream: prefer consolidation, keep new bins expensive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    } else {
        // Existing bin: reward more when many bins are open (consolidation).
        score -= 1.2 * obp;
        // Last-chance bin: strong bonus to avoid opening a new bin needlessly.
        if fitting_bins_count == 1 {
            score -= 45.0;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean
    // (place into bins with less remaining space than average => tighter packing).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Lookahead synergy: if the next item exactly fits the post-residual,
    // strongly favor this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: leaving exactly the next item's size is ideal.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // 2-step lookahead coupling: how well does the next item match the post residual?
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.6;
        // Next item fits inside post_residual -> strong chain reward.
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // Next item would need a new bin; penalize leaving a large unusable gap.
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
    } else {
        // Last item: minimize leftover as tightly as possible.
        score += (post_residual as f64) * 0.5;
    }

    // Relative-to-mean dead-space penalty.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.4;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Slight preference for packing into existing bins over opening new ones,
    // but allow opening a new bin when post_residual would be tiny dead space.
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive only if it would end up near-full.
        let fill = item_size as f64 / bin_capacity as f64;
        score += 30.0 * (1.0 - fill);
        if item_size >= 50 {
            score -= 20.0;
        }
    }

    // Late in stream: be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;
    score += (post_residual as f64 / bin_capacity as f64) * progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream (dynamic time horizon).
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of this placement: fraction of bin consumed by the item.
    let fill = item_size as f64 / bin_capacity as f64;

    // Reward tight fits: subtract more when post_residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * bin_capacity as f64 * 0.1;

    // Penalize large dead space if it cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward leaving room for the lookahead item.
            let slack_fit = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 1.5 * slack_fit;
        } else {
            // Dead space: post_residual too small for next item.
            let waste = post_residual as f64 / next_item_size as f64;
            score += 4.0 * waste;
        }
    } else {
        // Last item: just minimize post_residual aggressively.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0 + 2.0 * fill;
    }

    // New-bin candidate handling: opening a new bin should be penalized mildly,
    // but becomes attractive when the item fits poorly everywhere (large post_residual
    // in tight bins) or many bins are open with high mean residual fragmentation.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying over time so late stream
        // consolidation is favored.
        score += 2.0 * (1.0 - 0.5 * t);
        // Attractive when mean residual is fragmented (many small holes).
        if mean_residual < item_size as f64 + 5.0 {
            score -= 1.0;
        }
        // Very attractive when item is large and would leave big holes elsewhere.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 1.5;
        }
    } else {
        // Mild penalty for using an existing bin when open bins are few
        // (encourage packing density early).
        if open_bins_count > 3 {
            score -= 0.3 * (open_bins_count as f64).ln().max(0.0) * 0.1;
        }
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // penalize outliers that create skewed residual distributions.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Non-linear bonus for exact-ish fills (post_residual in a "hard to fill" zone).
    if post_residual > 0 && post_residual < 10 {
        score += 2.0; // tiny unusable slivers are wasted capacity
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;

    let mut score = pr + 40.0 * poly;

    // Reward tight fits (small post residual) more strongly as stream progresses
    score -= (1.0 - norm_pr).powf(3.0) * (10.0 + 30.0 * progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size as f64 - pr) * (0.5 + progress);
    }

    // Reward when next item fits exactly into post residual
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0 + 20.0 * progress;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate: prefer opening only when existing fits are poor
    if bin_residual == bin_capacity {
        score = pr + 25.0 - 20.0 * progress;
        if fitting_bins_count > 0 {
            score += 30.0 * (1.0 - norm_pr);
        }
    }

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).ln().max(0.0) * (mean_residual - pr).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
