    // Harmonic class: how well post_residual decomposes into capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Penalize residuals that are awkward harmonic classes (not nice fractions of C)
    // Nice classes: 0, 1/4, 1/2, 3/4 of capacity
    let nice = [0.0f64, 0.25, 0.5, 0.75, 1.0];
    let mut min_dist = f64::INFINITY;
    for n in nice.iter() {
        let d = (frac - n).abs();
        if d < min_dist {
            min_dist = d;
        }
    }
    score += min_dist * 30.0;

    // Integer division threshold: small dead space (< 10) is unusable
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Modulo arithmetic on post_residual: residuals divisible by 10 are more reusable
    if post_residual % 10 == 0 {
        score -= 8.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            let leftover = post_residual - next_item_size;
            score += (leftover as f64) * 0.5;
            if leftover == 0 {
                score -= 100.0;
            }
        } else {
            // next item cannot fit here; slight penalty for wasting tight space
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only attractive when current fit is terrible
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 60.0;
        // if the item is large relative to capacity, a fresh bin is fine
        if item_size as f64 > 0.7 * cap {
            score -= 40.0;
        }
        // if many open bins with lots of residual, discourage new bin
        score += mean_residual * 0.3;
        // early in stream, prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 20.0;
    }

    // Prefer fuller bins: penalize bins with large residual slightly
    score += (bin_residual as f64) * 0.05;

    // Mean-residual coupling: if this bin is much emptier than average, deprioritize
    let diff = (bin_residual as f64) - mean_residual;
    score += diff.max(0.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1,9] are nearly unusable
    // (min item size is 1..100 unknown, but small gaps waste capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual == 0 {
        // Perfect fit is ideal: strongly reward.
        score -= 60.0;
    }

    // Penalize tight-but-not-perfect fits that leave mid-size gaps.
    if post_residual >= 10 && post_residual < 25 {
        score += 6.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // current fit is poor (large dead space) or no good fit exists.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, modulated by open-bin pressure.
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 8.0);
        score += 30.0 + 20.0 * pressure;
        // If lookahead item is large, a fresh bin is more valuable.
        if next_item_size > 50 {
            score -= 15.0;
        }
        // Late in the stream, opening new bins is less useful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    } else {
        // Favor bins whose residual is close to the item (efficient packing).
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 12.0 * tightness;

        // Lookahead synergy: reward leaving a gap that fits the next item exactly.
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 30.0;
            } else if post_residual >= next_item_size {
                score -= 4.0;
            } else {
                // Next item cannot use this bin's leftover: mild penalty.
                score += 3.0;
            }
        }

        // Open-bin pressure: when many bins are open, prefer consolidating
        // into tight fits rather than spreading.
        score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

        // Prefer bins below mean residual (fill the emptier bins) mildly.
        if (bin_residual as f64) > mean_residual {
            score += 2.0;
        } else {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item can still fit here: good chain
            score -= 0.5 * (post_residual as f64 - next_item_size as f64).min(50.0);
        } else {
            // next item won't fit: penalize dead space relative to next item
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin bonus: only fitting bin, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Penalize creating very small unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: make empty bins less attractive unless nothing fits well
    if bin_residual == bin_capacity {
        score += 80.0;
        // but if lookahead suggests a fresh bin chains better, soften slightly
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
    }

    // Late in stream: consolidate, prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0 * (fitting_bins_count as f64).recip().min(1.0);

    // Prefer opening new bins when many bins are open and fit is poor
    if post_residual > 0 && post_residual < item_size {
        score += 0.2 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward (irreversible waste avoided).
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Small dead space is fine; large dead space penalized super-linearly.
        let pr = post_residual as f64;
        score += 0.05 * pr * pr / bin_capacity as f64;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            // Next item still fits here: mild reward proportional to tightness.
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here: penalize by the shortfall.
            score += 0.4 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is justified only when the item
    // is large relative to all residuals or open bins are very fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let pressure = item_size as f64 / bin_capacity as f64;
        // Cost of a fresh bin, discounted over remaining stream.
        let horizon = 1.0 - (step_index as f64 / (total_items.max(1) as f64 + 1.0));
        let mut open_cost = 35.0 * horizon;
        // If item is huge and fragmentation is high, opening a fresh bin is good.
        open_cost -= 30.0 * pressure * fragmentation;
        // With few open bins, packing tightly matters less than spreading.
        if open_bins_count <= 2 {
            open_cost -= 8.0;
        }
        score += open_cost.max(-40.0);
    } else {
        // Prefer bins whose residual is close to the item (best-fit flavor)
        // beyond what post_residual alone captures.
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += 6.0 * tightness;
        // Slightly prefer bins below mean residual (balancing load).
        if (bin_residual as f64) > mean_residual {
            score += 2.0;
        }
    }

    // Mild late-stream urgency: waste less as the stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: quadratic coupling of fill ratio with stream progress.
    let fill = item_size as f64 / cap;
    score -= 30.0 * fill * fill * (1.0 + progress);

    // Penalize post-residual dead space more as the stream advances (smoothly).
    let post_norm = post / cap;
    score += 25.0 * post_norm * post_norm * (0.5 + progress);

    // Lookahead: reward if next item fits into post-residual (smooth coupling).
    if next_item_size > 0 {
        let next_fits = if (next_item_size as f64) <= post { 1.0 } else { 0.0 };
        let compat = 1.0 - ((next_item_size as f64 - post).abs() / cap).min(1.0);
        score -= 12.0 * compat * compat * next_fits;
        // Penalize leaving residual that exactly blocks the next item marginally.
        let gap = post - next_item_size as f64;
        if gap > 0.0 && gap < 10.0 {
            score += 6.0 * (1.0 - gap / 10.0);
        }
    }

    // Last-chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - post_norm);
    }

    // Mild penalty for proliferating bins relative to mean residual.
    score += 0.05 * open_bins_count as f64 * (1.0 - (mean_residual / cap).min(1.0));

    // Smooth progress-scaled exploration term.
    score -= 5.0 * (progress * std::f64::consts::PI).sin().abs() * post_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual space: bins whose post-residual falls into
    // "small" classes (1..=10) are near-perfect fits; reward them strongly.
    if post_residual > 0 && post_residual <= 10 {
        score -= 25.0 + (10 - post_residual) as f64 * 2.0;
    }

    // Dead-space penalty for awkward mid-range post-residuals that few item
    // sizes (1..100) can still fill: residuals in (20, 33) or (50, 60) are
    // hard to complete. Penalize via modulo structure.
    let r = post_residual;
    if (r > 20 && r < 33) || (r > 50 && r < 60) {
        score += 12.0;
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Harmonic pairing: if the next item fits exactly into post_residual,
    // this bin chains perfectly — big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item still fits: mild reward proportional to leftover tightness.
        score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this residual: penalize proportionally to waste.
        score += 6.0 + (post_residual as f64 / bin_capacity as f64) * 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer it over
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual <= bin_capacity / 2 {
        score -= 20.0;
    }

    // New-bin candidate: give it a baseline cost so it's chosen only when
    // open bins have poor fits. Scale slightly with stream progression and
    // number of open bins (bin-opening overhead grows with fragmentation).
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.75
            + 0.1 * open_bins_count as f64
            + 5.0 * (step_index as f64 / total_items.max(1) as f64);
        // If the new bin can host both current and next item harmonically,
        // opening it is attractive.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0;
        }
    }

    // Mild global pressure: when many bins are open, prefer tighter packing.
    score += 0.05 * open_bins_count as f64;

    // Coupling with mean residual: prefer bins below mean residual (tighter bins).
    score += 0.15 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    // Dead space = post_residual too small to ever fit a meaningful item.
    let dead_threshold = 12.0f64; // below ~12 units, a gap is nearly unusable
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 18.0;
    } else if post_residual == 0 {
        // Perfect fit: heavily reward.
        score -= 60.0;
    }

    // Non-linear penalty on wasted fraction of the bin's usable space.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += waste_ratio * waste_ratio * 40.0;

    // Reward filling bins deeply (item_size large relative to residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Open-bin pressure: with many open bins, discourage opening more and
    // encourage closing out existing bins (small post_residual).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 4.0);
    score += pressure * 2.5;

    // If this is the last fitting bin, strongly prefer using it over a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a mild baseline penalty so it
    // is only chosen when existing bins would create bad dead space.
    if bin_residual == bin_capacity {
        score += 35.0 + mean_residual * 0.15;
    } else {
        // Prefer bins whose residual is below the mean (closing them out).
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        }
    }

    // Lookahead (k=2): if the next item fits exactly into the post_residual,
    // reward this placement; if next item needs more than post_residual but
    // would fit the current residual, penalize wasting that chance.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            score += 8.0;
        }
    }

    // Slight preference early in the stream for keeping residual flexibility.
    score += (1.0 - progress) * (post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 + (next_item_size as f64) * 0.5;
        // chain fit: post_residual minus next item leaves small remainder -> great
        let chain_left = post_residual - next_item_size;
        if chain_left < 10 {
            score -= 60.0;
        }
    } else if next_item_size > 0 {
        // penalize dead space that next item cannot use
        score += (next_item_size as f64 - post_residual as f64).abs() * 0.3;
    }

    // Relative residual matching vs mean residual
    if mean_residual > 0.0 {
        let ratio = post_residual as f64 / mean_residual;
        if ratio < 1.0 {
            score -= (1.0 - ratio) * 30.0; // tighter than average -> good
        } else {
            score += (ratio - 1.0) * 20.0;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        let tightness = if fitting_bins_count > 0 {
            (fitting_bins_count as f64).min(4.0)
        } else {
            0.0
        };
        score += 120.0 - tightness * 25.0;
        // new bin is attractive when the item is large relative to capacity
        score -= (item_size as f64 / bin_capacity as f64) * 60.0;
    }

    // Late-stream consolidation
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 15.0;

    // small tie-break: prefer filling larger fractions of the bin
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.08;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;
    score += 30.0 * norm_pr * norm_pr * (0.5 + progress);
    score -= 25.0 * norm_pr * (1.0 - progress) * (1.0 - progress);

    // Penalize tight fits less as stream progresses (fill existing bins late)
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness * progress;

    // Reward bins that can also host the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 10.0 * (nx / cap);
        } else {
            score += 12.0 * (1.0 - pr / nx.max(1.0));
        }
    }

    // Last-chance bonus: avoid opening new bins when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Mild pressure toward consolidation via mean residual deviation
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;
    score -= 5.0 * dev * (2.0 * progress - 1.0);

    // New-bin candidate: penalize slightly more early, less late
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: post_residual mod 10 buckets.
    // Residuals in classes {0} are "perfect" (bin exactly full or reusable by
    // multiples of 10); classes {1..9} waste increasing granularity.
    let pr = post_residual;
    let class = pr % 10;
    if class == 0 {
        score -= 12.0; // perfectly harmonized leftover
    } else if class <= 3 {
        score -= 4.0; // small, still usable by small items
    } else if class <= 6 {
        score += 3.0; // awkward mid-class dead space
    } else {
        score += 8.0; // large unusable remainder
    }

    // Harmonic compatibility: can next_item_size land exactly into post_residual?
    if next_item_size > 0 {
        let nxt = next_item_size;
        if nxt == pr {
            score -= 20.0; // next item closes this bin perfectly
        } else if pr >= nxt && (pr - nxt) % 10 == 0 {
            score -= 10.0; // chain stays on the 10-grid
        } else if pr >= nxt && (pr - nxt) <= 5 {
            score -= 6.0; // near-perfect chain
        } else if pr < nxt {
            score += 5.0; // next item can't use this bin's leftover
        }
        // modulo-class affinity between item and next item
        if item_size % 10 == nxt % 10 && item_size % 10 == 0 {
            score -= 3.0;
        }
    } else {
        // Last item: strongly reward filling the bin completely.
        if pr == 0 {
            score -= 25.0;
        }
    }

    // Last-chance bonus: only one open bin fits; strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Opening new bins is only attractive when the current fit is terrible
    // (large dead space) or the stream is early and future capacity matters.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize new bins mildly, more as the stream matures.
        score += 18.0 + 22.0 * progress;
        // But if placing here would strand > 30 units of dead space,
        // a fresh bin becomes competitive.
        if pr > 30 && pr % 10 != 0 {
            score -= 25.0;
        }
    }

    // Crowd control: many open bins with high mean residual -> prefer
    // consolidating into existing bins, penalize spreading.
    if open_bins_count > 2 {
        score += 0.05 * open_bins_count as f64;
        if (post_residual as f64) < mean_residual {
            score -= 4.0; // tighter than average: good consolidation
        }
    }

    // Integer-division threshold: reward leaving residuals that are
    // multiples of common small item sizes.
    if pr >= 10 && pr % 20 == 0 {
        score -= 5.0;
    }
    if pr >= 10 && pr % 25 == 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold the smallest plausible item (<= 10)
    // are pure waste; penalize them quadratically.
    if post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    } else if post_residual > 0 && post_residual < 20 {
        // Risky zone: only next_item_size or larger items can use it.
        if next_item_size == 0 || next_item_size > post_residual {
            score += 15.0 + (20 - post_residual) as f64 * 0.8;
        } else {
            // Next item fits perfectly into the would-be gap: reward chain fit.
            score -= (post_residual - next_item_size) as f64 * 0.5 + 5.0;
        }
    }

    // Reward tight fits (small but usable post_residual).
    if post_residual >= 10 {
        score -= (20 - post_residual.min(20)) as f64 * 0.3;
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item fits the post-residual, reward; otherwise slight penalty.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 3.0;
        }
    }

    // New-bin candidate: keep it competitive only when it's genuinely better
    // (early stream or no good existing fit). A fresh bin has full residual.
    if bin_residual == bin_capacity {
        let base = bin_capacity as f64;
        // Neutral-ish baseline; becomes more attractive late when bins are fragmented.
        score = base - 12.0 + pressure * 0.9 - mean_residual * 0.15;
        if fitting_bins_count == 0 {
            score -= 20.0; // must open a bin anyway
        }
        if post_residual < 10 && post_residual > 0 {
            score += 10.0; // avoid tiny-waste openings
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: exact fill is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item fits the post residual
    // (chaining placements), penalize dead space that nothing can use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item chains into this bin: reward proportionally to how snugly.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 60.0 - chain_waste.min(60.0);
        } else {
            // Dead space below next item size: penalize harder for small leftovers.
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
        // Bonus if the chain leaves an exact fill after the next item.
        if post_residual == next_item_size {
            score -= 250.0;
        }
    } else {
        // Last item: only current fit matters.
        score -= 30.0;
    }

    // Relative to mean residual: prefer bins that are tighter than average
    // (best-fit style), penalize using the emptiest bins for small items.
    score += (mean_residual - bin_residual as f64) * 0.6;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: make it attractive only when the item is large
    // relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score -= 20.0 + 40.0 * tightness;
        if next_item_size > 0 && post_residual < next_item_size {
            // Fresh bin can't chain the next item well; discourage.
            score += 25.0;
        }
    }

    // Mild preference to consolidate bins as the stream progresses.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 18.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement is perfect; if it cannot fit, mild penalty.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // New-bin candidate handling: fresh bins should only win when no open bin
    // offers a reasonable fit. Penalize the empty bin by the global slack.
    if bin_residual == bin_capacity {
        score += 40.0 + 0.35 * mean_residual;
        if fitting_bins_count > 0 {
            score += 55.0;
        }
    }

    // Prefer filling bins with large residuals when many bins are open
    // (consolidation pressure), scaled by stream progression.
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    score += 0.10 * (bin_residual as f64 - mean_residual) * (0.5 + progress);

    // Prefer bins whose residual is close to the item (minimal waste fraction).
    let waste_ratio = (post_residual as f64) / (bin_residual.max(1) as f64);
    score += 25.0 * waste_ratio;

    // Slight preference for reusing fewer bins overall.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: post-residual, smoothly warped by stream progress.
    // Early on, prefer leaving flexible space; later, prefer tight fits.
    let warp = 0.5 + 0.5 * (progress * std::f64::consts::PI).sin();
    let mut score = r * (0.6 + 0.8 * warp);

    // Non-linear penalty for awkward residual sizes (dead space):
    // residuals that are too small to be useful later get punished more as stream advances.
    let smallness = (1.0 - rn).powi(3);
    score += 18.0 * smallness * (0.3 + progress);

    // Reward tight fits (near-zero post residual) with a smooth quadratic bonus.
    score -= 30.0 * (1.0 - rn).powi(2) * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward; if next item can't fit post-residual but would fit a fresh bin,
    // penalize this bin slightly when it's nearly full anyway.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= r {
            let waste = (r - nx) / cap;
            score -= 12.0 * (1.0 - waste * waste);
        } else {
            score += 6.0 * (1.0 - rn) * (0.5 + 0.5 * progress);
        }
    }

    // Mild penalty for proliferating open bins when residuals are large.
    score += (open_bins_count as f64).ln() * 2.0 * (1.0 - rn);

    // Deviation from mean residual: prefer bins close to the mean (balanced packing),
    // with a smooth non-linear coupling to progress.
    let dev = (r - mean_residual) / cap;
    score += 8.0 * dev * dev * (0.4 + 0.6 * progress);

    // New-bin candidate: neutral-ish baseline, encourage only when nothing fits well.
    if bin_residual == bin_capacity {
        score += 10.0 - 20.0 * progress * (1.0 - (fitting_bins_count as f64).recip());
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into coarse buckets
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left over

    // Reward tight fits: dead space below ~15% is nearly unusable, penalize heavily
    if post_residual < bin_capacity / 7 {
        score += 60.0 - 4.0 * pr as f64;
    }

    // Harmonic tier: post_residual in "good" mid-range (fits common small items 1..30)
    if post_residual >= 30 && post_residual <= 50 {
        score -= 25.0;
    } else if post_residual > 50 && post_residual <= 70 {
        score -= 10.0;
    }

    // Modulo-class logic: residuals that are multiples of common item sizes are valuable
    let pr_u = post_residual;
    if pr_u % 10 == 0 {
        score -= 8.0;
    }
    if pr_u % 5 == 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 0.3 * next_item_size as f64;
            // penalize leaving a gap next item nearly fills but can't (dead space trap)
            if post_residual - next_item_size < 8 {
                score += 15.0;
            }
        } else {
            // next item cannot fit here: leftover may become dead space
            score += 0.15 * (next_item_size as f64 - pr);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize so it's chosen only when open bins are poor fits
    if bin_residual == bin_capacity {
        score += 45.0 + 0.5 * open_bins_count as f64;
    }

    // Stream progression: late in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - frac);

    // Mean residual coupling: prefer bins below mean residual (tighter bins first)
    score += 0.2 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps too small for typical items (1..=100 unknown dist,
    // be conservative: anything < ~12 is likely dead weight).
    if post_residual > 0 && post_residual < 12 {
        score += 60.0 * (12.0 - post_residual as f64) / 12.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Dead-space penalty scales with how much of the bin is wasted relative to capacity
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * waste_frac * waste_frac;

    // Open-bin pressure: discourage opening new bins when many bins are open
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 15.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 3.0; // prefer using existing bins
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward this placement
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // next item cannot use the leftover: extra dead-space penalty
            score += 10.0;
        }
    }

    // Mild preference for tighter bins (best-fit core) modulated by mean residual
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Late in the stream, be more frugal with opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: aggressive 2-step lookahead matching.
    if next_item_size > 0 {
        // Perfect chain: post_residual exactly equals next item -> strong reward.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Near-perfect chain (small gap) -> graded reward.
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 25.0 / (1.0 + gap * 0.5);

        // Penalize leaving a residual that cannot fit the next item (dead space risk),
        // scaled by how far below next_item_size the post_residual falls.
        if post_residual < next_item_size {
            score += 0.8 * (next_item_size - post_residual) as f64;
        }

        // If the next item fits snugly relative to capacity, prefer tight packing now.
        let snug = (item_size + next_item_size) as f64 / bin_capacity as f64;
        if snug > 0.95 {
            score -= 10.0 * (snug - 0.95) * 20.0;
        }
    } else {
        // Last item: just minimize waste.
        score -= 5.0;
    }

    // Tightness reward: prefer bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Penalize bins with residuals far from the mean (outliers are harder to fill later).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: mildly penalize opening a new bin early in the stream,
    // penalize more when many bins are already open and idle.
    if bin_residual == bin_capacity {
        score += 12.0;
        if fitting_bins_count > 1 {
            score += 10.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
        }
        // Late in the stream, opening new bins is more costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress;
    }

    // Small penalty per open bin to encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio over the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional tightness: how well the item fills the bin.
    let fill = item_size as f64 / bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 25.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Penalize dead space that cannot hold typical future items.
    if post_residual > 0 && post_residual < 20 {
        score += 12.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Lookahead: reward if the next item fits the post-residual exactly or well.
    if next_item_size > 0 && (post_residual as u64) >= next_item_size as u64 {
        let next_waste = post_residual as f64 - next_item_size as f64;
        score -= 15.0 * (1.0 - next_waste / bin_capacity as f64);
        if next_waste == 0.0 {
            score -= 20.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here after placement: mild penalty unless bin nearly full.
        score += 6.0 * (1.0 - tightness);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    score += 0.35 * open_bins_count as f64 * (1.0 - fill);

    // Deviation from mean residual: prefer bins whose residual is close to item need.
    let dev = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Early in the stream: be more exploratory, tolerate imperfect fits;
    // late in the stream: be greedy about tight packing.
    let time_weight = 0.5 + 0.5 * progress;
    score *= 0.6 + 0.4 * time_weight;

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the stream is early and open bins are crowded.
    if bin_residual == bin_capacity {
        let escape_valve = if fitting_bins_count == 0 { 0.0 } else { 14.0 };
        score = bin_capacity as f64
            - 10.0 * (1.0 - progress)
            + escape_valve
            + 0.25 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Smooth polynomial coupling: residual squared normalized, modulated by progress
    let norm_post = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * norm_post * norm_post * (0.5 + progress);

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_post;
    score -= 15.0 * tightness * tightness * tightness * (0.5 + progress);

    // Penalize dead space relative to next item (smooth interaction)
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).max(0.0) / bin_capacity as f64;
        score += 10.0 * gap * gap;
        // Reward leaving room for the next item
        let covers = if (post_residual as f64) >= next_item_size as f64 { 1.0 } else { 0.0 };
        score -= 5.0 * covers * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * open_bins_count as f64 * norm_post;

    // Deviation from mean residual (smooth quadratic)
    let dev = post_residual as f64 - mean_residual;
    score += 0.05 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues modulo 10 define "dead space" classes.
    // Residuals that are multiples of 10 are reusable by typical item sizes; odd/prime-ish
    // residues are harder to fill, so penalize them.
    let r = post_residual;
    if r > 0 {
        let r_mod = (r % 10) as f64;
        score += 2.5 * (r_mod / 10.0); // up to +2.5 penalty for awkward residue
        if r_mod == 0 {
            score -= 4.0; // perfectly reusable residual class
        }
    } else {
        score -= 12.0; // perfect fill: strongly reward
    }

    // Integer-division thresholds: small post-residuals below the minimum item size (1..=10)
    // are dead space; penalize proportionally.
    if r > 0 && r < 10 {
        score += 6.0 + (10 - r) as f64 * 0.5;
    }

    // Capacity fraction coupling: favor bins whose fill ratio lands in "good" harmonic
    // fractions (1/2, 2/3, 3/4, 4/5) of capacity after placement.
    let fill = (bin_capacity - r) as f64 / bin_capacity as f64;
    let good_fractions = [0.5f64, 2.0 / 3.0, 0.75, 0.8, 0.9];
    for (i, f) in good_fractions.iter().enumerate() {
        let d = (fill - f).abs();
        if d < 0.05 {
            score -= 3.0 - i as f64 * 0.4;
        }
    }

    // Lookahead coupling (k=2): if next item fits the post-residual exactly, big reward.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 10.0;
        } else if next_item_size <= r {
            let n_mod = (r % next_item_size.max(1)) as f64;
            score -= 3.0 * (1.0 - n_mod / (next_item_size.max(1) as f64));
        } else {
            // next item cannot fit here: mild penalty scaled by wasted residual
            score += 1.5;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin unless
    // the fit is terrible (large post-residual).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0 + 0.05 * r as f64;
    }

    // New-bin candidate handling: empty bin should only win when open bins are crowded
    // or the fit in open bins would be poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0;
        // Cheaper to open new bins early in the stream / when few bins open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        score -= 1.5 * open_bins_count as f64;
        // If mean residual across open bins is small, new bin is more attractive.
        score -= 0.08 * mean_residual;
        // Large items relative to capacity favor a fresh bin.
        score -= 0.1 * item_size as f64;
    }

    // Prefer tighter fits among open bins: reward small post-residual nonlinearly.
    score -= 20.0 / (1.0 + r as f64);

    // Mild penalty for spreading across many open bins (keep bin count lean).
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (< 10, min item size) are pure waste.
    if post_residual < 10 {
        score += 40.0; // unusable dead space
    } else if post_residual < 20 {
        score += 12.0; // nearly dead: only tiny items can use it
    } else if post_residual < 35 {
        score += 3.0;  // moderately awkward gap
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing ones;
    // with few open bins, opening a new bin is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress * 3.0);
    score += 0.8 * pressure;

    // Prefer bins whose residual is below mean (fill the emptier-but-usable side less,
    // keep mean residual low). Slight pull toward bins tighter than average.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Lookahead: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 30.0; // perfect chain fit
        } else {
            score -= 10.0 * (1.0 - gap as f64 / post_residual.max(1) as f64);
        }
    } else if next_item_size > post_residual {
        score += 5.0; // post residual useless for the known next item
    }

    // New-bin candidate: neutral residual; make it attractive only when existing bins
    // would create dead space or pressure is low.
    if bin_residual == bin_capacity {
        score = post_residual as f64 + 6.0 + 0.5 * pressure;
        if fitting_bins_count >= 1 && mean_residual < 40.0 {
            score += 10.0; // existing bins are roomy enough; discourage new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-perfect match: next item leaves tiny dead space afterward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        score -= 200.0 - (after_next as f64) * 3.0;
        if after_next < 10 {
            score -= 150.0; // leaves a small but potentially reusable residual
        }
    }
    // Item won't fit in this bin next round: penalize wasted capacity.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.0;
    }

    // Penalize large unusable dead space (below typical min item size).
    if post_residual < 10 && post_residual > 0 {
        score += 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual - item_size) as f64 * 0.3;

    // New empty bin: only attractive when no decent fit exists.
    if bin_residual == bin_capacity {
        score += 60.0 + open_bins_count as f64 * 2.0;
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize the brand-new empty bin candidate unless the item fits badly everywhere.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty: opening a new bin wastes the residual of existing bins.
        score += 60.0;
        // If this is the last fitting bin, we must use it (or open a new one) — soften penalty
        // so a new bin is chosen only when the fit here is truly poor.
        if fitting_bins_count <= 1 {
            score -= 70.0;
        }
        // Lookahead: if the next item would fit nicely in the residual left here, opening
        // a new bin is more attractive.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        }
    } else {
        // Reward tight fits in existing bins: small post_residual already favored.
        // Extra reward for near-perfect packing.
        if post_residual <= 5 {
            score -= 25.0;
        } else if post_residual <= 15 {
            score -= 10.0;
        }
        // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
        // to avoid opening a new bin.
        if fitting_bins_count <= 1 {
            score -= 40.0;
        } else if fitting_bins_count == 2 {
            score -= 12.0;
        }
        // Lookahead synergy: prefer bins whose post_residual accommodates the next item well.
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                // Next item also fits here: reward proportional to tightness of the pair.
                let pair_waste = (post_residual - next_item_size) as f64;
                score -= 15.0 - 0.3 * pair_waste;
            } else {
                // Next item won't fit here; mildly penalize leaving awkward space.
                let gap = (next_item_size - post_residual) as f64;
                if gap < 10.0 {
                    score += 0.4 * gap;
                }
            }
        }
        // Global state coupling: when many bins are open with high mean residual,
        // prefer filling existing bins harder (penalize loose fits).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste_pressure = mean_residual / bin_capacity as f64;
        score += waste_pressure * (post_residual as f64) * (0.5 + 0.5 * progress);
        // Late in the stream, tighten packing further.
        score += progress * 5.0;
        // Slight penalty scaling with number of open bins to consolidate load.
        score += 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // later in the stream, tight fits (small post_residual) are rewarded more strongly.
    let tightness = (1.0 - norm_pr) * (1.0 - norm_pr);
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score -= progress_weight * 40.0 * tightness * norm_item;

    // Penalize residual that is too small to be useful, smoothly via cubic term.
    let waste = norm_pr * norm_pr * norm_pr;
    score += 60.0 * waste;

    // Lookahead: if next item fits in post_residual, reward this placement smoothly.
    if next_item_size > 0 {
        let fits = (pr - next_item_size as f64).max(0.0) / cap;
        let bonus = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        let smooth = bonus * (1.0 - fits * fits);
        score -= 25.0 * smooth * (0.5 + progress);
    }

    // Last-chance bin: smooth reward when this is the only fitting bin.
    if fitting_bins_count <= 1 {
        score -= 30.0 * (1.0 - norm_pr);
    }

    // Coupling with mean residual: prefer bins below mean residual (tighter bins).
    let mean_norm = mean_residual / cap;
    let diff = norm_pr - mean_norm;
    score += 15.0 * diff * diff - 10.0 * diff;

    // Mild penalty for opening new bins late in stream (encourage packing into existing bins).
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * progress + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by common item sizes
    // (10..=80 multiples of 10) are reusable "harmonic" dead space.
    let pr = post_residual;
    let harmonic = if pr == 0 {
        3.0 // perfect fit is excellent
    } else if pr % 10 == 0 && pr >= 10 {
        -2.0 // residual matches the coarse harmonic class -> likely reusable
    } else if pr % 5 == 0 {
        -0.8
    } else {
        0.0
    };
    score -= harmonic;

    // Dead-space penalty grows for small non-harmonic leftovers.
    if pr > 0 && pr < 10 {
        score += 6.0; // unusable sliver
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 3.0 + 0.05 * (pr - next_item_size) as f64;
            // exact harmonic match with next item
            if pr == next_item_size { score -= 2.0; }
            if next_item_size % 10 == 0 && pr % 10 == 0 { score -= 1.0; }
        } else {
            score += 1.5; // next item won't fit here anyway
        }
    } else {
        // last item: just minimize residual
        score -= 1.0;
    }

    // Last-chance bin: strongly favor filling it rather than opening new bins.
    if fitting_bins_count == 1 {
        score -= 4.0;
    } else if fitting_bins_count > 1 {
        score += 0.5 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: only attractive when current fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 2.0 };
        score = post_residual as f64 + 4.0 - poor_fit
            + 0.02 * open_bins_count as f64
            - (step_index as f64 / total_items.max(1) as f64) * 2.0;
        if item_size % 10 == 0 { score += 1.0; } // round items pack well anywhere
    }

    // Mild preference for tighter-than-average bins.
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward (post_residual == 0 is ideal).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Strict dead-space avoidance: small unusable gaps are heavily penalized.
        // A residual gap is "unusable" if it's smaller than the smallest plausible item.
        let min_item = 1u32; // interface allows items down to 1, but gap utility scales smoothly
        let _ = min_item;
        // Penalize gaps that cannot accommodate the lookahead item (wasted space relative to future).
        if next_item_size > 0 && post_residual < next_item_size {
            score += 30.0 + (next_item_size - post_residual) as f64 * 1.5;
        }
        // Nonlinear penalty on tiny dead gaps (hard to fill later).
        if post_residual < 20 {
            score += (20 - post_residual) as f64 * (20 - post_residual) as f64 * 0.5;
        }
    }

    // Reward tight fits: post_residual close to 0 relative to bin size.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 10.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new bins;
    // when few bins are open, opening a fresh bin is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline plus pressure penalty, slightly relaxed by mean residual.
        score += 15.0 + pressure * 2.0 - mean_residual * 0.05;
    } else {
        // Existing bin: mild reward, stronger when many bins are open (consolidation).
        score -= pressure * 0.3;
        // Favor bins with below-average residual (more filled already).
        let diff = mean_residual - bin_residual as f64;
        score += diff * 0.1;
    }

    // Lookahead synergy: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is gold.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // exact chain fill
        } else if post_residual > next_item_size {
            // next item still fits after this one: reward tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize proportionally to gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    } else {
        // last item: just minimize waste
        score += 5.0;
    }

    // Reward tight fits overall (small post_residual relative to item).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio;

    // Penalize leaving tiny unusable slivers (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Prefer bins with below-mean residual (tighter bins first).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fit_ratio;

    // Mild penalty for spreading across many open bins.
    score += 0.5 * open_bins_count as f64;

    // New-bin candidate: neutral baseline, only chosen if all open bins look bad.
    if bin_residual == bin_capacity {
        score += 45.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a superlinear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if next_item_size > post_residual {
            // next item won't fit here; mildly penalize large leftover gaps
            score += 0.05 * (post_residual as f64);
        }
    }

    // New-bin candidate handling: only open a new bin when the item is large
    // (would leave little waste in a fresh bin) or no open bin fits well.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        let mut new_bin_score = post_residual as f64;
        // Prefer new bin for large items, discourage for small ones.
        new_bin_score -= 40.0 * fill * fill;
        // If many bins fit the item, opening a new one is wasteful.
        new_bin_score += 8.0 * (fitting_bins_count as f64).min(5.0);
        // Late in the stream, prefer packing into existing bins.
        new_bin_score += 20.0 * progress;
        // If mean residual across open bins is large, use existing bins.
        new_bin_score += (mean_residual - item_size as f64).max(0.0) * 0.3;
        score = new_bin_score;
    }

    // Slight preference for bins already below mean residual (balancing).
    if bin_residual < bin_capacity {
        score += 0.05 * ((bin_residual as f64) - mean_residual).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with a smooth non-linear penalty on post_residual
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // late in the stream, dead space matters more (less chance to fill it)
    let late = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 40.0 * late * norm_pr * norm_pr;

    // Reward near-perfect fits smoothly (quadratic dip around zero residual)
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - late);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: penalize if next item cannot use the post-residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            score += 10.0 + 0.2 * (nx - pr);
        } else {
            score -= 0.1 * (pr - nx);
        }
    }

    // Slight preference for bins with residuals below mean (consolidate waste)
    score += 0.05 * (pr - mean_residual);

    // Mild new-bin penalty to avoid opening bins unnecessarily
    if bin_residual == bin_capacity {
        score += 5.0 + 15.0 * late;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "nice"
    // residue classes (multiples of 25, 20, 10) are more reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit is ideal
    } else {
        let class_bonus: f64 = if pr % 50 == 0 {
            25.0
        } else if pr % 25 == 0 {
            18.0
        } else if pr % 20 == 0 {
            14.0
        } else if pr % 10 == 0 {
            10.0
        } else if pr % 5 == 0 {
            5.0
        } else {
            0.0
        };
        score -= class_bonus;

        // Dead-space penalty: small, awkward leftovers are nearly unusable.
        if pr < 10 {
            score += 30.0;
        } else if pr < 20 {
            score += 12.0;
        }

        // Integer-division thresholds: leftover must plausibly hold the next item.
        if next_item_size > 0 {
            if pr >= next_item_size {
                // Reward leftover that can host the lookahead item, especially
                // when the leftover is a close harmonic multiple of it.
                score -= 8.0;
                let q = pr / next_item_size;
                let r = pr % next_item_size;
                if r == 0 {
                    score -= 10.0; // leftover is an exact multiple of next item
                } else if r < 10 && q >= 1 {
                    score -= 4.0; // near-exact fit for next item
                }
            } else {
                // Leftover can't fit next item: penalize proportional to gap.
                score += (next_item_size - pr) as f64 * 0.5;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: keep empty bins attractive only when
    // current open bins have poor (small/awkward) residuals.
    if bin_residual == bin_capacity {
        // Base attractiveness of a fresh bin: its whole capacity.
        score = bin_capacity as f64 - 5.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 6.0; // fresh bin can host a clean pair
        }
        // If open bins are healthy on average, prefer them over a new bin.
        score += (mean_residual / bin_capacity as f64) * 15.0;
        // More open bins -> slightly discourage opening yet another.
        score += open_bins_count as f64 * 1.5;
    } else {
        // Prefer tighter existing bins: scale by fill fraction.
        score -= (1.0 - bin_residual as f64 / bin_capacity as f64) * 10.0;
    }

    // Stream progression: early on, be more willing to open bins (explore);
    // late, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 8.0;
    } else {
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in unusable small gaps is costly.
    // Gaps too small for the smallest plausible item (<=10) are dead space.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        // Small residual likely unusable: amplify penalty non-linearly.
        score += (20 - post_residual) as f64 * 2.5;
    } else {
        // Larger residuals are flexible: mild reward for using space well.
        score -= 8.0;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 15.0;

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (a new empty bin has max residual, so add penalty proportional to open count).
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 12.0;
        // Extra penalty late in the stream when consolidation matters.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    } else {
        // Favor existing bins slightly when they fit well.
        score -= 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits in the post-residual, reward;
    // if next item would be stranded by this placement, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else if post_residual < 10 && next_item_size > bin_capacity - post_residual {
            // Dead space that strands the next item.
            score += 15.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is near/below mean
    // (consolidating toward fuller bins).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual)
    score -= (bin_capacity as f64 - post_residual as f64) * 0.5;

    // 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0 + next_item_size as f64 * 0.4;
        } else {
            // Penalize leaving residual that is too small for the next item
            score += (next_item_size as f64 - post_residual as f64) * 0.6;
        }
        // Perfect chain: post_residual exactly matches next item
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Compare against mean residual across open bins
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize tiny unusable dead space
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // New bin candidate: mildly penalize opening a new bin unless residual is large
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 0.5;
    }

    score
}
